        IsActive       bit           NOT NULL CONSTRAINT DF_sel_MixtureModel_Active DEFAULT (1),
        SortOrder      int           NOT NULL CONSTRAINT DF_sel_MixtureModel_Sort   DEFAULT (0)
    );
