END
ELSE PRINT '  sec.RlsBypass                     skipped';
GO

/* =====================================================================================
   Row-level security
   ===================================================================================== */

/* sec.fn_UserOrgScope — every organisation code this login may read.  A grant on a node
   reaches every descendant through the closure table, so the tree is walked once at load
   time rather than per row at read time.                                                */
CREATE OR ALTER FUNCTION sec.fn_UserOrgScope (@LoginName nvarchar(128))
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
    /* A login on the bypass list sees every organisation. */
    SELECT n.OrgCode
    FROM sel.OrgNode n
    WHERE EXISTS (SELECT 1 FROM sec.RlsBypass b
                  JOIN sec.AppUser u ON u.AppUserId = b.AppUserId
                  WHERE u.LoginName = @LoginName AND u.IsActive = 1)
    UNION
    /* Otherwise, the granted nodes and everything under them. */
    SELECT a.OrgCode
    FROM sec.UserOrgGrant g
    JOIN sec.AppUser u ON u.AppUserId = g.AppUserId AND u.IsActive = 1
    JOIN sel.OrgAncestor a ON a.AncestorOrgCode = g.OrgCode
    WHERE u.LoginName = @LoginName;
GO
PRINT '  sec.fn_UserOrgScope               applied';
GO

/* =====================================================================================
   Screen access — the shipped precedence, in one place
   ===================================================================================== */

/* sec.fn_ScreenAccessAsOf — the decision, against an explicit as-of date.

   1  Bootstrap         the seeded administrator, so a fresh database is reachable
   2  Not registered    the login has no sec.AppUser row -> deny
   3  Expired           AuthorizationEndsOn < AsOf -> deny
   4  User override     replaces the role rule outright, and may widen or narrow it
   5  Role policy       sec.RoleScreenGrant
   6  No rule           deny

   An auditor's read-only flag is applied last: no grant can give it write.             */
CREATE OR ALTER FUNCTION sec.fn_ScreenAccessAsOf
(
    @LoginName  nvarchar(128),
    @ScreenCode nvarchar(160),
    @AsOf       date
)
RETURNS smallint
WITH SCHEMABINDING
AS
BEGIN
    DECLARE @userId int, @endsOn date, @isBootstrap bit, @isActive bit;

    SELECT @userId = u.AppUserId, @endsOn = u.AuthorizationEndsOn,
           @isBootstrap = u.IsBootstrap, @isActive = u.IsActive
    FROM sec.AppUser u WHERE u.LoginName = @LoginName;

    /* 2 — not registered. */
    IF @userId IS NULL OR @isActive = 0 RETURN 0;

    DECLARE @screenId int;
    SELECT @screenId = s.ScreenId FROM cfg.Screen s
    WHERE s.ScreenCode = @ScreenCode AND s.IsActive = 1;

    /* An unknown screen is a deny, not an allow: a screen that is not registered has
       no rule, and rule 6 says no rule denies. */
    IF @screenId IS NULL RETURN 0;

    /* Is this login read-only by role?  Needed for the final cap. */
    DECLARE @roleReadOnly bit = 0;
    IF EXISTS (SELECT 1 FROM sec.UserRole ur
               JOIN sec.Role r ON r.RoleId = ur.RoleId
               WHERE ur.AppUserId = @userId AND r.IsReadOnly = 1)
        SET @roleReadOnly = 1;

    /* 1 — bootstrap. */
    IF @isBootstrap = 1
        RETURN CASE WHEN @roleReadOnly = 1 THEN 1 ELSE 2 END;

    /* 3 — expired. */
    IF @endsOn IS NOT NULL AND @endsOn < @AsOf RETURN 0;

    /* 4 — user override replaces the role rule outright. */
    DECLARE @grant smallint;
    SELECT @grant = g.GrantValue FROM sec.UserScreenGrant g
    WHERE g.AppUserId = @userId AND g.ScreenId = @screenId;

    /* 5 — role policy.  Where a login holds several roles the most generous wins,
       because a role is a grant and holding two grants cannot take access away. */
    IF @grant IS NULL
        SELECT @grant = MAX(rsg.GrantValue)
        FROM sec.RoleScreenGrant rsg
        JOIN sec.UserRole ur ON ur.RoleId = rsg.RoleId
        JOIN sec.Role r ON r.RoleId = ur.RoleId AND r.IsActive = 1
        WHERE ur.AppUserId = @userId AND rsg.ScreenId = @screenId;

    /* 6 — no rule. */
    IF @grant IS NULL RETURN 0;

    /* The read-only cap, applied last. */
    IF @roleReadOnly = 1 AND @grant > 1 SET @grant = 1;

    RETURN @grant;
END
GO
PRINT '  sec.fn_ScreenAccessAsOf           applied';
GO

/* sec.fn_ScreenAccess — the two-argument form every procedure calls.  It resolves the
   as-of date from configuration so a caller cannot forget to pass one.                */
/* Not schema bound: it calls cfg.fn_SettingText and sec.fn_ScreenAccessAsOf, and binding
   a caller is what stops those two being re-applied on a second run of the migrations. */
CREATE OR ALTER FUNCTION sec.fn_ScreenAccess (@LoginName nvarchar(128), @ScreenCode nvarchar(160))
RETURNS smallint
AS
BEGIN
    DECLARE @asOf date = TRY_CONVERT(date, cfg.fn_SettingText(N'AS_OF_OVERRIDE'));
    IF @asOf IS NULL SET @asOf = CAST(SYSUTCDATETIME() AS date);
    RETURN sec.fn_ScreenAccessAsOf(@LoginName, @ScreenCode, @asOf);
END
GO
PRINT '  sec.fn_ScreenAccess               applied';
GO

/* sec.fn_ScreenAccessRule — which of the six rules decided, so the access screen can
   show the reason rather than only the outcome.                                        */
CREATE OR ALTER FUNCTION sec.fn_ScreenAccessRule
(
    @LoginName  nvarchar(128),
    @ScreenCode nvarchar(160),
    @AsOf       date
)
RETURNS nvarchar(40)
WITH SCHEMABINDING
AS
BEGIN
    DECLARE @userId int, @endsOn date, @isBootstrap bit, @isActive bit;
    SELECT @userId = u.AppUserId, @endsOn = u.AuthorizationEndsOn,
           @isBootstrap = u.IsBootstrap, @isActive = u.IsActive
    FROM sec.AppUser u WHERE u.LoginName = @LoginName;

    IF @userId IS NULL OR @isActive = 0 RETURN N'NOT_REGISTERED';
    IF @isBootstrap = 1 RETURN N'BOOTSTRAP';
    IF @endsOn IS NOT NULL AND @endsOn < @AsOf RETURN N'EXPIRED';

    DECLARE @screenId int;
    SELECT @screenId = ScreenId FROM cfg.Screen WHERE ScreenCode = @ScreenCode AND IsActive = 1;
    IF @screenId IS NULL RETURN N'NO_RULE';

    IF EXISTS (SELECT 1 FROM sec.UserScreenGrant g
               WHERE g.AppUserId = @userId AND g.ScreenId = @screenId)
        RETURN N'USER_OVERRIDE';

    IF EXISTS (SELECT 1 FROM sec.RoleScreenGrant rsg
               JOIN sec.UserRole ur ON ur.RoleId = rsg.RoleId
               WHERE ur.AppUserId = @userId AND rsg.ScreenId = @screenId)
        RETURN N'ROLE_POLICY';

    RETURN N'NO_RULE';
END
GO
PRINT '  sec.fn_ScreenAccessRule           applied';
GO

/* sec.fn_IsReadOnlyUser — the auditor flag, read by IUserContext once per request. */
CREATE OR ALTER FUNCTION sec.fn_IsReadOnlyUser (@LoginName nvarchar(128))
RETURNS bit
WITH SCHEMABINDING
AS
BEGIN
    IF EXISTS (SELECT 1 FROM sec.AppUser u
               JOIN sec.UserRole ur ON ur.AppUserId = u.AppUserId
               JOIN sec.Role r ON r.RoleId = ur.RoleId
               WHERE u.LoginName = @LoginName AND r.IsReadOnly = 1)
        RETURN 1;
    RETURN 0;
END
GO
PRINT '  sec.fn_IsReadOnlyUser             applied';
GO

/* sec.fn_CanEditCycle — a cycle design is editable by its owner or delegate, or an
   administrator, and never once Closed.                                                */
CREATE OR ALTER FUNCTION sec.fn_CanEditCycle (@LoginName nvarchar(128), @CycleId int)
RETURNS bit
AS
BEGIN
    IF @CycleId IS NULL RETURN 0;

    /* A closed cycle is never changed, only copied. */
    IF sel.fn_CycleStatusCode(@CycleId) = N'CLOSED' RETURN 0;

    /* An auditor never writes, whatever else is true. */
    IF sec.fn_IsReadOnlyUser(@LoginName) = 1 RETURN 0;

    /* The design screen's own write grant is the floor. */
    IF sec.fn_ScreenAccess(@LoginName, N'/Selection/CycleSetup/') < 2 RETURN 0;

    IF EXISTS (SELECT 1 FROM sel.Cycle c
               WHERE c.CycleId = @CycleId
                 AND (c.OwnerLogin = @LoginName OR c.DelegateLogin = @LoginName))
        RETURN 1;

    /* An administrator may edit any design. */
    IF EXISTS (SELECT 1 FROM sec.AppUser u
               JOIN sec.UserRole ur ON ur.AppUserId = u.AppUserId
               JOIN sec.Role r ON r.RoleId = ur.RoleId
               WHERE u.LoginName = @LoginName AND u.IsActive = 1 AND r.RoleCode = N'ADMIN')
        RETURN 1;

    RETURN 0;
END
GO
PRINT '  sec.fn_CanEditCycle               applied';
GO

/* sec.fn_CycleEditRefusal — the read-only bar states which reason applies. */
CREATE OR ALTER FUNCTION sec.fn_CycleEditRefusal (@LoginName nvarchar(128), @CycleId int)
RETURNS nvarchar(600)
AS
BEGIN
    IF sec.fn_CanEditCycle(@LoginName, @CycleId) = 1 RETURN NULL;
    IF sel.fn_CycleStatusCode(@CycleId) = N'CLOSED' RETURN cfg.fn_Message(N'CLOSED_CYCLE');
    IF sec.fn_IsReadOnlyUser(@LoginName) = 1 RETURN cfg.fn_Message(N'READONLY_REFUSAL');
    IF sec.fn_ScreenAccess(@LoginName, N'/Selection/CycleSetup/') < 2 RETURN cfg.fn_Message(N'READONLY_REFUSAL');
    RETURN cfg.fn_Message(N'NOT_OWNER_REFUSAL');
END
GO
PRINT '  sec.fn_CycleEditRefusal           applied';
GO

/* =====================================================================================
   Procedures — the Access control and Row-level security screens
   ===================================================================================== */

/* sec.usp_User_Context — resolved once per request into IUserContext. */
CREATE OR ALTER PROCEDURE sec.usp_User_Context
    @LoginName nvarchar(128),
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    SELECT u.AppUserId, u.LoginName, u.DisplayName, u.PersonnelNo, u.Email,
           u.AuthorizationEndsOn, u.IsBootstrap, u.IsActive,
           RoleCode = (SELECT TOP (1) r.RoleCode FROM sec.UserRole ur
                       JOIN sec.Role r ON r.RoleId = ur.RoleId
                       WHERE ur.AppUserId = u.AppUserId ORDER BY r.SortOrder),
           RoleName = (SELECT TOP (1) r.Name FROM sec.UserRole ur
                       JOIN sec.Role r ON r.RoleId = ur.RoleId
                       WHERE ur.AppUserId = u.AppUserId ORDER BY r.SortOrder),
           IsReadOnly = sec.fn_IsReadOnlyUser(u.LoginName),
           OrgScopeCount = (SELECT COUNT(*) FROM sec.fn_UserOrgScope(u.LoginName)),
           HasRlsBypass = CONVERT(bit, CASE WHEN EXISTS (SELECT 1 FROM sec.RlsBypass b WHERE b.AppUserId = u.AppUserId)
                               THEN 1 ELSE 0 END),
           /* "Authorization ended" / "Ends within four months", in words. */
           AuthorizationNote =
               CASE WHEN u.AuthorizationEndsOn IS NULL THEN NULL
                    WHEN u.AuthorizationEndsOn < @AsOf THEN cfg.fn_Message(N'AUTH_ENDED')
                    WHEN u.AuthorizationEndsOn < DATEADD(MONTH, 4, @AsOf) THEN cfg.fn_Message(N'AUTH_ENDING')
                    ELSE NULL END,
           AsOf = @AsOf
    FROM sec.AppUser u
    WHERE u.LoginName = @LoginName;
END
GO
PRINT '  sec.usp_User_Context              applied';
GO

/* sec.usp_Policy_Matrix — roles, screens and the grant matrix.  "No grant" is a
   visible third state, not an empty cell, so the matrix returns a row for every pair
   and a NULL grant means no rule.                                                      */
CREATE OR ALTER PROCEDURE sec.usp_Policy_Matrix
    @LoginName nvarchar(128)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT RoleId, RoleCode, Name, Description, IsReadOnly, SortOrder, IsActive,
           UserCount = (SELECT COUNT(*) FROM sec.UserRole ur WHERE ur.RoleId = sec.Role.RoleId)
    FROM sec.Role ORDER BY SortOrder, Name;

    SELECT s.ScreenId, s.ScreenCode, s.Name, s.AreaName, s.IsInMenu, s.SortOrder,
           g.Caption AS GroupCaption, g.SortOrder AS GroupSort
    FROM cfg.Screen s
    LEFT JOIN cfg.MenuGroup g ON g.MenuGroupId = s.MenuGroupId
    WHERE s.IsActive = 1
    ORDER BY g.SortOrder, s.SortOrder, s.Name;

    /* One row per (role, screen): GrantValue NULL means no rule. */
    SELECT r.RoleId, s.ScreenId, rsg.GrantValue
    FROM sec.Role r
    CROSS JOIN cfg.Screen s
    LEFT JOIN sec.RoleScreenGrant rsg ON rsg.RoleId = r.RoleId AND rsg.ScreenId = s.ScreenId
    WHERE s.IsActive = 1;
END
GO
PRINT '  sec.usp_Policy_Matrix             applied';
GO

/* sec.usp_User_List — the users table with its expiry wording and override count. */
CREATE OR ALTER PROCEDURE sec.usp_User_List
    @LoginName nvarchar(128),
    @AsOf      date = NULL,
    @Search    nvarchar(200) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    SELECT u.AppUserId, u.LoginName, u.DisplayName, u.PersonnelNo, u.Email,
           u.AuthorizationEndsOn, u.IsBootstrap, u.IsActive, u.AddedByLogin, u.AddedOnUtc,
           RoleCode = (SELECT TOP (1) r.RoleCode FROM sec.UserRole ur
                       JOIN sec.Role r ON r.RoleId = ur.RoleId
                       WHERE ur.AppUserId = u.AppUserId ORDER BY r.SortOrder),
           RoleName = (SELECT TOP (1) r.Name FROM sec.UserRole ur
                       JOIN sec.Role r ON r.RoleId = ur.RoleId
                       WHERE ur.AppUserId = u.AppUserId ORDER BY r.SortOrder),
           OverrideCount = (SELECT COUNT(*) FROM sec.UserScreenGrant g WHERE g.AppUserId = u.AppUserId),
           OrgGrantCount = (SELECT COUNT(*) FROM sec.UserOrgGrant og WHERE og.AppUserId = u.AppUserId),
           OrgScopeCount = (SELECT COUNT(*) FROM sec.fn_UserOrgScope(u.LoginName)),
           AuthorizationNote =
               CASE WHEN u.AuthorizationEndsOn IS NULL THEN NULL
                    WHEN u.AuthorizationEndsOn < @AsOf THEN cfg.fn_Message(N'AUTH_ENDED')
                    WHEN u.AuthorizationEndsOn < DATEADD(MONTH, 4, @AsOf) THEN cfg.fn_Message(N'AUTH_ENDING')
                    ELSE NULL END,
           AuthorizationRole =
               CASE WHEN u.AuthorizationEndsOn IS NULL THEN NULL
                    WHEN u.AuthorizationEndsOn < @AsOf THEN N'danger'
                    WHEN u.AuthorizationEndsOn < DATEADD(MONTH, 4, @AsOf) THEN N'warning'
                    ELSE NULL END
    FROM sec.AppUser u
    WHERE (@Search IS NULL OR u.LoginName LIKE N'%' + @Search + N'%' OR u.DisplayName LIKE N'%' + @Search + N'%')
    ORDER BY u.DisplayName;

    /* The per-user overrides. */
    SELECT g.AppUserId, u.LoginName, g.ScreenId, s.ScreenCode, s.Name AS ScreenName,
           g.GrantValue, g.Note, g.GrantedByLogin, g.GrantedOnUtc
    FROM sec.UserScreenGrant g
    JOIN sec.AppUser u ON u.AppUserId = g.AppUserId
    JOIN cfg.Screen s ON s.ScreenId = g.ScreenId
    ORDER BY u.DisplayName, s.SortOrder;
END
GO
PRINT '  sec.usp_User_List                 applied';
GO

/* sec.usp_ScreenAccess_Explain — the precedence made visible for one login: what each
   screen resolves to, and which of the six rules decided it.                          */
CREATE OR ALTER PROCEDURE sec.usp_ScreenAccess_Explain
    @LoginName    nvarchar(128),
    @TargetLogin  nvarchar(128),
    @AsOf         date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    SELECT s.ScreenId, s.ScreenCode, s.Name, s.AreaName, g.Caption AS GroupCaption,
           GrantValue = sec.fn_ScreenAccessAsOf(@TargetLogin, s.ScreenCode, @AsOf),
           RuleCode   = sec.fn_ScreenAccessRule(@TargetLogin, s.ScreenCode, @AsOf)
    FROM cfg.Screen s
    LEFT JOIN cfg.MenuGroup g ON g.MenuGroupId = s.MenuGroupId
    WHERE s.IsActive = 1
    ORDER BY g.SortOrder, s.SortOrder, s.Name;
END
GO
PRINT '  sec.usp_ScreenAccess_Explain      applied';
GO

/* sec.usp_Rls_Compare — two viewers' scopes side by side: units, pool and HIPO counts. */
CREATE OR ALTER PROCEDURE sec.usp_Rls_Compare
    @LoginName   nvarchar(128),
    @LoginA      nvarchar(128),
    @LoginB      nvarchar(128)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT WhichLogin = N'A', Login = @LoginA,
           Units = (SELECT COUNT(*) FROM sec.fn_UserOrgScope(@LoginA)),
           People = (SELECT COUNT(*) FROM sel.Employee e
                     JOIN sec.fn_UserOrgScope(@LoginA) s ON s.OrgCode = e.OrgCode
                     WHERE e.IsActive = 1),
           InPools = (SELECT COUNT(DISTINCT c.PersonnelNo) FROM sel.CycleCandidate c
                      JOIN sec.fn_UserOrgScope(@LoginA) s ON s.OrgCode = c.OrgCode)
    UNION ALL
    SELECT N'B', @LoginB,
           (SELECT COUNT(*) FROM sec.fn_UserOrgScope(@LoginB)),
           (SELECT COUNT(*) FROM sel.Employee e
            JOIN sec.fn_UserOrgScope(@LoginB) s ON s.OrgCode = e.OrgCode WHERE e.IsActive = 1),
           (SELECT COUNT(DISTINCT c.PersonnelNo) FROM sel.CycleCandidate c
            JOIN sec.fn_UserOrgScope(@LoginB) s ON s.OrgCode = c.OrgCode);
END
GO
PRINT '  sec.usp_Rls_Compare               applied';
GO

/* sec.usp_ScreenAccess_Check — the ScreenAccess authorization handler's one call.

   The handler could not call sec.fn_ScreenAccess directly without holding SQL text, and
   there is no SQL text in C#, so the function gets a procedure in front of it.  It returns
   the grant, the rule that decided it, and the refusal sentence to render, so the handler
   maps a row to a decision and composes nothing itself. */
CREATE OR ALTER PROCEDURE sec.usp_ScreenAccess_Check
    @LoginName  nvarchar(128),
    @ScreenCode nvarchar(160),
    @AsOf       date = NULL,
    @NeedsWrite bit = 0
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @grant smallint = sec.fn_ScreenAccessAsOf(@LoginName, @ScreenCode, @AsOf);
    DECLARE @rule nvarchar(40) = sec.fn_ScreenAccessRule(@LoginName, @ScreenCode, @AsOf);

    SELECT GrantValue = @grant,
           RuleCode   = @rule,
           CanRead    = CONVERT(bit, CASE WHEN @grant >= 1 THEN 1 ELSE 0 END),
           CanWrite   = CONVERT(bit, CASE WHEN @grant >= 2 THEN 1 ELSE 0 END),
           IsAllowed  = CONVERT(bit, CASE WHEN @NeedsWrite = 1 THEN CASE WHEN @grant >= 2 THEN 1 ELSE 0 END
                             ELSE CASE WHEN @grant >= 1 THEN 1 ELSE 0 END END),
           ScreenName = (SELECT Name FROM cfg.Screen WHERE ScreenCode = @ScreenCode),
           /* The sentence the refusal screen renders.  Which of the six rules applied is
              what makes a denial explainable rather than mysterious. */
           Refusal =
               CASE WHEN (@NeedsWrite = 0 AND @grant >= 1) OR (@NeedsWrite = 1 AND @grant >= 2) THEN NULL
                    WHEN @rule = N'NOT_REGISTERED'
                         THEN N'Your login is not registered in Maseera, so nothing is open to you yet. '
                            + N'An administrator adds people on the Access control screen.'
                    WHEN @rule = N'EXPIRED'
                         THEN N'Your authorization ended, so every screen is closed until it is renewed.'
                    WHEN @NeedsWrite = 1 AND @grant = 1
                         THEN cfg.fn_Message(N'READONLY_REFUSAL')
                    WHEN @rule = N'USER_OVERRIDE'
                         THEN N'A grant set against you denies this screen.'
                    WHEN @rule = N'ROLE_POLICY'
                         THEN N'Your role does not open this screen.'
                    ELSE N'Nothing grants you this screen.' END;
END
GO
PRINT '  sec.usp_ScreenAccess_Check        applied';
GO

PRINT '== 06_security complete ==============================================';
GO


/* ---- 07_evaluation_engine.sql ------------------------------------------------------- */

/* =====================================================================================
   07_evaluation_engine.sql  —  whether one person meets one requirement
   -------------------------------------------------------------------------------------
   One worker decides whether a person meets an item, and everything calls it: the profile
   ladder, the pool coverage percentages, the readiness distribution and the IDP's list of
   open obligations.  The four can never disagree because there is only one answer.

       itemMet(person, itemCode) -> { met, why, value, target, viaCode }

   The rules that make it correct:

   1. Candidate codes are the item itself plus every code equivalent to it.
   2. For EACH code, load THAT code's own event, its own rule and its own mapped source.
      An equivalent may live in a different table with different columns; judging it by
      the main item's rule reads the wrong field and returns a wrong answer with no error.
      This is the single most important correctness rule in the product.
   3. Flag mode: met when any candidate row passes its OWN rule; the code that satisfied
      it is returned so the UI can say "via ASM-360-02".
   4. Sum mode: each candidate row is filtered by its OWN conditions, the measure is
      summed over the survivors, and it is met when the total reaches the floor.
   5. One row against one rule: each set is evaluated independently (all / any / none),
      then the sets are folded left to right with their joins (and / or / except).
      A condition with no field chosen fails ITS OWN condition, not the others.
   6. why is not optional.  Return the reason, not the verdict.

   And the performance rule: the evaluation is set-based over people.  One statement per
   candidate code answers the whole pool.  Nothing here is ever called inside a loop over
   people — that shape is 240,000 evaluations to answer one screen.
   ===================================================================================== */
SET NOCOUNT ON;
GO

PRINT '';
PRINT '== 07_evaluation_engine ==============================================';
GO

/* =====================================================================================
   Escaping and predicate building
   ===================================================================================== */

/* cfg.fn_EscapeLiteral — a value as a safe SQL literal.  Nothing concatenates a raw
   user value into dynamic SQL anywhere in this database; it comes through here.        */
CREATE OR ALTER FUNCTION cfg.fn_EscapeLiteral (@Value nvarchar(400))
RETURNS nvarchar(1000)
AS
BEGIN
    IF @Value IS NULL RETURN N'NULL';
    RETURN N'N''' + REPLACE(@Value, N'''', N'''''') + N'''';
END
GO
PRINT '  cfg.fn_EscapeLiteral              applied';
GO

/* cfg.fn_EscapeList — a comma separated value as a safe, quoted IN list. */
CREATE OR ALTER FUNCTION cfg.fn_EscapeList (@Csv nvarchar(400))
RETURNS nvarchar(max)
AS
BEGIN
    IF @Csv IS NULL OR LTRIM(RTRIM(@Csv)) = N'' RETURN N'NULL';

    DECLARE @out nvarchar(max) =
        STUFF((SELECT N', ' + cfg.fn_EscapeLiteral(LTRIM(RTRIM(value)))
               FROM STRING_SPLIT(@Csv, N',')
               WHERE LTRIM(RTRIM(value)) <> N''
               FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, N'');

    RETURN ISNULL(@out, N'NULL');
END
GO
PRINT '  cfg.fn_EscapeList                 applied';
GO

/* cfg.fn_BuildPredicate — one condition as a SQL predicate, from the operator's own
   template.  The only place the SQL shape of an operator is decided; there is no
   if (op = '>=') chain anywhere in this product.

   A number or a date is re-emitted from its parsed value, never from the raw text, so a
   value that is not a number cannot become SQL.  Anything else is quoted.               */
CREATE OR ALTER FUNCTION cfg.fn_BuildPredicate
(
    @ColumnExpr   nvarchar(1000),
    @OperatorCode nvarchar(30),
    @Value1       nvarchar(400),
    @Value2       nvarchar(400),
    @DataType     nvarchar(20),
    @AsOf         date
)
RETURNS nvarchar(max)
AS
BEGIN
    IF @ColumnExpr IS NULL OR @OperatorCode IS NULL RETURN N'(1 = 0)';

    DECLARE @template nvarchar(400), @arity tinyint;
    SELECT @template = SqlTemplate, @arity = Arity
    FROM cfg.Operator WHERE OperatorCode = @OperatorCode AND IsActive = 1;

    /* An operator that is not in the table is not an operator. */
    IF @template IS NULL RETURN N'(1 = 0)';

    /* The number of values must match the operator's arity. */
    IF @arity >= 1 AND (@Value1 IS NULL OR LTRIM(RTRIM(@Value1)) = N'') RETURN N'(1 = 0)';
    IF @arity >= 2 AND (@Value2 IS NULL OR LTRIM(RTRIM(@Value2)) = N'') RETURN N'(1 = 0)';

    DECLARE @l1 nvarchar(max), @l2 nvarchar(max);

    IF @DataType = N'number'
    BEGIN
        IF @arity >= 1 AND TRY_CONVERT(decimal(38,10), @Value1) IS NULL RETURN N'(1 = 0)';
        IF @arity >= 2 AND TRY_CONVERT(decimal(38,10), @Value2) IS NULL RETURN N'(1 = 0)';
        SET @l1 = CONVERT(nvarchar(60), TRY_CONVERT(decimal(38,10), @Value1));
        SET @l2 = CONVERT(nvarchar(60), TRY_CONVERT(decimal(38,10), @Value2));
    END
    ELSE IF @DataType = N'date'
    BEGIN
        IF @arity >= 1 AND TRY_CONVERT(date, @Value1) IS NULL RETURN N'(1 = 0)';
        IF @arity >= 2 AND TRY_CONVERT(date, @Value2) IS NULL RETURN N'(1 = 0)';
        SET @l1 = N'CONVERT(date, ''' + CONVERT(nvarchar(10), TRY_CONVERT(date, @Value1), 23) + N''', 23)';
        SET @l2 = N'CONVERT(date, ''' + CONVERT(nvarchar(10), TRY_CONVERT(date, @Value2), 23) + N''', 23)';
    END
    ELSE
    BEGIN
        SET @l1 = cfg.fn_EscapeLiteral(@Value1);
        SET @l2 = cfg.fn_EscapeLiteral(@Value2);
    END;

    DECLARE @asOfLiteral nvarchar(80) =
        N'CONVERT(date, ''' + CONVERT(nvarchar(10), ISNULL(@AsOf, CAST(SYSUTCDATETIME() AS date)), 23) + N''', 23)';

    DECLARE @sql nvarchar(max) = @template;
    SET @sql = REPLACE(@sql, N'{col}',   @ColumnExpr);
    SET @sql = REPLACE(@sql, N'{asof}',  @asOfLiteral);
    SET @sql = REPLACE(@sql, N'{list1}', cfg.fn_EscapeList(@Value1));
    SET @sql = REPLACE(@sql, N'{like1}', cfg.fn_EscapeLiteral(N'%' + ISNULL(@Value1, N'') + N'%'));
    SET @sql = REPLACE(@sql, N'{v1}',    ISNULL(@l1, N'NULL'));
    SET @sql = REPLACE(@sql, N'{v2}',    ISNULL(@l2, N'NULL'));

    RETURN N'(' + @sql + N')';
END
GO
PRINT '  cfg.fn_BuildPredicate             applied';
GO

/* sel.fn_ConditionColumnExpr — how one field is read from one evidence row.
   A physical column is read directly; a learned field is read through
   sel.EmployeeRecordDetail, so a rule may name a column this schema never anticipated
   without needing a migration.                                                          */
CREATE OR ALTER FUNCTION sel.fn_ConditionColumnExpr
(
    @EvidenceSourceId int,
    @FieldName        nvarchar(128),
    @Alias            nvarchar(20),
    @DataType         nvarchar(20)
)
RETURNS nvarchar(1000)
AS
BEGIN
    IF @FieldName IS NULL OR LTRIM(RTRIM(@FieldName)) = N'' RETURN NULL;

    DECLARE @isPhysical bit, @appSchema nvarchar(128), @appTable nvarchar(128);
    SELECT @isPhysical = c.IsPhysical
    FROM sel.EvidenceSourceColumn c
    WHERE c.EvidenceSourceId = @EvidenceSourceId AND c.ColumnName = @FieldName;

    SELECT @appSchema = AppSchema, @appTable = AppTable
    FROM sel.EvidenceSource WHERE EvidenceSourceId = @EvidenceSourceId;

    /* A field the editor has never seen is treated as physical if the table really has
       it, and otherwise as a detail key. */
    IF @isPhysical IS NULL
        SET @isPhysical = CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
                                            WHERE TABLE_SCHEMA = @appSchema
                                              AND TABLE_NAME = @appTable
                                              AND COLUMN_NAME = @FieldName)
                               THEN 1 ELSE 0 END;

    IF @isPhysical = 1
        RETURN @Alias + N'.' + QUOTENAME(@FieldName);

    /* Only the record-based source carries a detail table. */
    IF @appTable <> N'EmployeeRecord' RETURN NULL;

    RETURN N'(SELECT TOP (1) '
         + CASE @DataType WHEN N'number' THEN N'd.ValueNum'
                          WHEN N'date'   THEN N'd.ValueDate'
                          ELSE N'd.ValueText' END
         + N' FROM sel.EmployeeRecordDetail d WHERE d.EmployeeRecordId = ' + @Alias
         + N'.EmployeeRecordId AND d.FieldName = ' + cfg.fn_EscapeLiteral(@FieldName) + N')';
END
GO
PRINT '  sel.fn_ConditionColumnExpr        applied';
GO

/* =====================================================================================
   sel.usp_Event_BuildWhere — one event's rule as a SQL predicate over one evidence row
   -------------------------------------------------------------------------------------
   Each set is evaluated independently, then the sets are folded left to right with their
   joins.  "except" is "and not".  An event with no sets returns the kind's default.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Event_BuildWhere
    @DevEventId int,
    @Alias      nvarchar(20) = N'r',
    @AsOf       date = NULL,
    @Where      nvarchar(max) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);
    SET @Where = NULL;

    DECLARE @kind nvarchar(30), @sourceId int, @statusCol nvarchar(128), @passValue nvarchar(120),
            @evalMode nvarchar(20), @eventPass nvarchar(120);

    SELECT @kind = e.KindCode, @eventPass = e.PassValue FROM sel.DevEvent e WHERE e.DevEventId = @DevEventId;
    IF @kind IS NULL BEGIN SET @Where = N'(1 = 0)'; RETURN; END;

    SELECT @evalMode = EvalModeCode FROM sel.RequirementKind WHERE KindCode = @kind;
    SELECT @sourceId = EvidenceSourceId, @statusCol = StatusColumn, @passValue = PassValue
    FROM sel.EvidenceSource WHERE KindCode = @kind;

    IF NOT EXISTS (SELECT 1 FROM sel.DevEventConditionSet WHERE DevEventId = @DevEventId)
    BEGIN
        /* No conditions: follow the kind's default. */
        IF @evalMode = N'SUM'
        BEGIN
            SET @Where = N'(1 = 1)';     -- every row of this person's coverage counts
            RETURN;
        END;

        DECLARE @pass nvarchar(120) = ISNULL(@eventPass, @passValue);
        IF @statusCol IS NULL OR @pass IS NULL
            SET @Where = N'(1 = 1)';
        ELSE
            SET @Where = N'(' + @Alias + N'.' + QUOTENAME(@statusCol) + N' = '
                       + cfg.fn_EscapeLiteral(@pass) + N')';
        RETURN;
    END;

    /* Build each set, then fold. */
    DECLARE @folded nvarchar(max) = NULL;
    DECLARE @setId int, @setMode nvarchar(60), @setJoin nvarchar(60), @first bit = 1;

    DECLARE setCur CURSOR LOCAL FAST_FORWARD FOR
        SELECT cs.SetId, mv.ValueCode, jv.ValueCode
        FROM sel.DevEventConditionSet cs
        JOIN cfg.DomainValue mv ON mv.DomainValueId = cs.SetModeValueId
        LEFT JOIN cfg.DomainValue jv ON jv.DomainValueId = cs.SetJoinValueId
        WHERE cs.DevEventId = @DevEventId
        ORDER BY cs.SortOrder, cs.SetLabel;

    OPEN setCur;
    FETCH NEXT FROM setCur INTO @setId, @setMode, @setJoin;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        /* Every condition in the set, each built from its own field and operator.
           A condition with no field chosen becomes (1 = 0): it fails itself, and
           because the set combines them it does not reach into the others.           */
        DECLARE @parts nvarchar(max) =
            STUFF((SELECT CASE WHEN @setMode = N'ALL' THEN N' AND ' ELSE N' OR ' END
                        + cfg.fn_BuildPredicate(
                              sel.fn_ConditionColumnExpr(@sourceId, c.FieldName, @Alias,
                                  ISNULL(esc.DataType, N'text')),
                              c.OperatorCode, c.Value1, c.Value2,
                              ISNULL(esc.DataType, N'text'), @AsOf)
                   FROM sel.DevEventCondition c
                   LEFT JOIN sel.EvidenceSourceColumn esc
                          ON esc.EvidenceSourceId = @sourceId AND esc.ColumnName = c.FieldName
                   WHERE c.SetId = @setId
                   ORDER BY c.SortOrder, c.ConditionId
                   FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'),
                  1, CASE WHEN @setMode = N'ALL' THEN 5 ELSE 4 END, N'');

        DECLARE @setSql nvarchar(max);
        IF @parts IS NULL
            /* A set with no conditions holds for every row rather than for none: an
               empty set is an unfinished edit, not a rule that excludes everybody. */
            SET @setSql = N'(1 = 1)';
        ELSE IF @setMode = N'NONE'
            SET @setSql = N'(NOT (' + @parts + N'))';
        ELSE
            SET @setSql = N'(' + @parts + N')';

        IF @first = 1
        BEGIN
            SET @folded = @setSql;
            SET @first = 0;
        END
        ELSE
            SET @folded = N'(' + @folded +
                CASE ISNULL(@setJoin, N'AND')
                     WHEN N'OR'     THEN N' OR '
                     WHEN N'EXCEPT' THEN N' AND NOT '
                     ELSE N' AND ' END
                + @setSql + N')';

        FETCH NEXT FROM setCur INTO @setId, @setMode, @setJoin;
    END;

    CLOSE setCur; DEALLOCATE setCur;

    SET @Where = ISNULL(@folded, N'(1 = 1)');
END
GO
PRINT '  sel.usp_Event_BuildWhere          applied';
GO

/* =====================================================================================
   sel.usp_Item_ResolveMet_Into — the worker
   -------------------------------------------------------------------------------------
   The caller creates #scope (PersonnelNo) and #met, and this appends one row per person
   in scope.  It iterates over candidate CODES (a handful) and is set-based over PEOPLE
   (the expensive dimension): one statement per code answers the whole pool.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Item_ResolveMet_Into
    @ItemCode nvarchar(60),
    @AsOf     date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    /* Per-code, per-person outcome, before the candidate codes are folded together. */
    CREATE TABLE #code_hit
    (
        PersonnelNo nvarchar(30)  NOT NULL,
        ViaCode     nvarchar(60)  NOT NULL,
        Passed      bit           NOT NULL,
        HasRow      bit           NOT NULL,
        NumValue    decimal(18,4) NULL,
        TextValue   nvarchar(200) NULL,
        Target      decimal(18,4) NULL
    );

    DECLARE @code nvarchar(60), @isMain bit;
    DECLARE codeCur CURSOR LOCAL FAST_FORWARD FOR
        SELECT ItemCode, IsMain FROM sel.fn_ItemCandidateCodes(@ItemCode) ORDER BY IsMain DESC, ItemCode;

    OPEN codeCur;
    FETCH NEXT FROM codeCur INTO @code, @isMain;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        /* --- this code's OWN event, rule and mapped source ------------------------- */
        DECLARE @evId int, @kind nvarchar(30), @evalMode nvarchar(20), @floor decimal(18,4),
                @appSchema nvarchar(128), @appTable nvarchar(128), @itemCol nvarchar(128),
                @measureCol nvarchar(128), @statusCol nvarchar(128), @isMapped bit;

        SELECT @evId = NULL, @kind = NULL, @evalMode = NULL, @floor = NULL,
               @appSchema = NULL, @appTable = NULL, @itemCol = NULL,
               @measureCol = NULL, @statusCol = NULL, @isMapped = NULL;

        SELECT TOP (1) @evId = e.DevEventId, @kind = e.KindCode, @floor = e.SumFloor
        FROM sel.DevEvent e
        WHERE e.ItemCode = @code AND e.IsActive = 1
        ORDER BY e.DevEventId;

        /* An equivalent code may have no event of its own; fall back to the catalogue
           entry's kind so its evidence is still read with that kind's default rule. */
        IF @kind IS NULL
            SELECT TOP (1) @kind = ci.KindCode FROM sel.CatalogItem ci
            WHERE ci.ItemCode = @code ORDER BY ci.CatalogItemId;

        IF @kind IS NOT NULL
        BEGIN
            SELECT @evalMode = EvalModeCode FROM sel.RequirementKind WHERE KindCode = @kind;
            SELECT @appSchema = AppSchema, @appTable = AppTable, @itemCol = ItemColumn,
                   @measureCol = MeasureColumn, @statusCol = StatusColumn, @isMapped = IsMapped
            FROM sel.EvidenceSource WHERE KindCode = @kind;
        END;

        /* An unmapped source can never be met — and that is said in words later, never
           rendered as a silent zero. */
        IF @kind IS NOT NULL AND ISNULL(@isMapped, 0) = 1
        BEGIN
            DECLARE @where nvarchar(max) = N'(1 = 1)';
            IF @evId IS NOT NULL
                EXEC sel.usp_Event_BuildWhere @DevEventId = @evId, @Alias = N'r',
                                              @AsOf = @AsOf, @Where = @where OUTPUT;
            ELSE IF @statusCol IS NOT NULL
                SELECT @where = N'(r.' + QUOTENAME(@statusCol) + N' = '
                              + cfg.fn_EscapeLiteral(s.PassValue) + N')'
                FROM sel.EvidenceSource s WHERE s.KindCode = @kind AND s.PassValue IS NOT NULL;

            DECLARE @sql nvarchar(max);
            DECLARE @obj nvarchar(300) = QUOTENAME(@appSchema) + N'.' + QUOTENAME(@appTable);

            IF @evalMode = N'SUM'
            BEGIN
                /* Each candidate row is filtered by its own conditions, and the measure
                   is summed over the survivors.  One statement, whole pool.            */
                SET @sql = N'
                INSERT #code_hit (PersonnelNo, ViaCode, Passed, HasRow, NumValue, TextValue, Target)
                SELECT s.PersonnelNo, @code,
                       CASE WHEN ISNULL(x.Total, 0) >= @floor THEN 1 ELSE 0 END,
                       CASE WHEN x.RowsSeen > 0 THEN 1 ELSE 0 END,
                       ISNULL(x.Total, 0), NULL, @floor
                FROM #scope s
                OUTER APPLY (
                    SELECT Total = SUM(CASE WHEN ' + @where + N' THEN ISNULL(r.'
                         + QUOTENAME(ISNULL(@measureCol, N'Days')) + N', 0) ELSE 0 END),
                           RowsSeen = COUNT(*)
                    FROM ' + @obj + N' r
                    WHERE r.PersonnelNo = s.PersonnelNo'
                    + CASE WHEN @itemCol IS NOT NULL
                           THEN N' AND (r.' + QUOTENAME(@itemCol) + N' = @code OR r.'
                                + QUOTENAME(@itemCol) + N' IS NULL)'
                           ELSE N'' END + N'
                ) x
                WHERE x.RowsSeen > 0;';

                EXEC sp_executesql @sql,
                     N'@code nvarchar(60), @floor decimal(18,4)',
                     @code = @code, @floor = @floor;
            END
            ELSE IF @evalMode = N'FLAG'
            BEGIN
                /* Met when ANY candidate row passes its own rule.  The score is carried
                   out so "why" can read "99 against 75" rather than only "not met".    */
                SET @sql = N'
                INSERT #code_hit (PersonnelNo, ViaCode, Passed, HasRow, NumValue, TextValue, Target)
                SELECT r.PersonnelNo, @code,
                       MAX(CASE WHEN ' + @where + N' THEN 1 ELSE 0 END),
                       1,
                       MAX(r.Score),
                       MAX(CAST(r.Status AS nvarchar(200))),
                       MAX(r.MaxScore)
                FROM ' + @obj + N' r
                JOIN #scope s ON s.PersonnelNo = r.PersonnelNo
                WHERE r.' + QUOTENAME(ISNULL(@itemCol, N'ItemCode')) + N' = @code'
                + CASE WHEN @kind IS NOT NULL THEN N' AND r.KindCode = @kind' ELSE N'' END + N'
                GROUP BY r.PersonnelNo;';

                EXEC sp_executesql @sql,
                     N'@code nvarchar(60), @kind nvarchar(30)',
                     @code = @code, @kind = @kind;
            END;
        END;

        FETCH NEXT FROM codeCur INTO @code, @isMain;
    END;

    CLOSE codeCur; DEALLOCATE codeCur;

    /* --- fold the candidate codes into one answer per person ---------------------- */
    DECLARE @mainEvId int, @mainMode nvarchar(20), @mainFloor decimal(18,4), @mainMapped bit;
    SELECT TOP (1) @mainEvId = e.DevEventId, @mainFloor = e.SumFloor,
           @mainMode = k.EvalModeCode,
           @mainMapped = ISNULL(s.IsMapped, 0)
    FROM sel.DevEvent e
    JOIN sel.RequirementKind k ON k.KindCode = e.KindCode
    LEFT JOIN sel.EvidenceSource s ON s.KindCode = e.KindCode
    WHERE e.ItemCode = @ItemCode AND e.IsActive = 1
    ORDER BY e.DevEventId;

    INSERT #met (PersonnelNo, ItemCode, Met, Why, NumValue, Target, ViaCode)
    SELECT sc.PersonnelNo,
           @ItemCode,
           Met = CONVERT(bit, CASE WHEN ISNULL(agg.AnyPassed, 0) = 1 THEN 1 ELSE 0 END),
           /* why is not optional: the reason, not the verdict. */
           Why =
               CASE
                   WHEN ISNULL(@mainMapped, 0) = 0
                        THEN cfg.fn_Message(N'SOURCE_UNMAPPED')
                   WHEN ISNULL(agg.AnyPassed, 0) = 1 AND @mainMode = N'SUM'
                        THEN CONVERT(nvarchar(40), CAST(ISNULL(agg.BestNum, 0) AS decimal(18,1)))
                           + N' against ' + CONVERT(nvarchar(40), CAST(ISNULL(agg.Target, 0) AS decimal(18,1)))
                   WHEN ISNULL(agg.AnyPassed, 0) = 1 AND agg.BestNum IS NOT NULL AND agg.Target IS NOT NULL
                        THEN CONVERT(nvarchar(40), CAST(agg.BestNum AS decimal(18,0)))
                           + N' against ' + CONVERT(nvarchar(40), CAST(agg.Target AS decimal(18,0)))
                           + CASE WHEN agg.PassedVia <> @ItemCode THEN N' via ' + agg.PassedVia ELSE N'' END
                   WHEN ISNULL(agg.AnyPassed, 0) = 1
                        THEN cfg.fn_Message(N'WHY_MET')
                           + CASE WHEN agg.PassedVia <> @ItemCode THEN N' via ' + agg.PassedVia ELSE N'' END
                   WHEN @mainMode = N'SUM' AND ISNULL(agg.AnyRow, 0) = 1
                        THEN CONVERT(nvarchar(40), CAST(ISNULL(agg.BestNum, 0) AS decimal(18,1)))
                           + N' against ' + CONVERT(nvarchar(40), CAST(ISNULL(@mainFloor, 0) AS decimal(18,1)))
                   WHEN ISNULL(agg.AnyRow, 0) = 0
                        THEN cfg.fn_Message(N'WHY_NOT_TAKEN')
                   WHEN agg.AnyStarted = 1
                        THEN cfg.fn_Message(N'WHY_STARTED')
                   ELSE cfg.fn_Message(N'WHY_NO_ROW_MATCHED')
               END,
           NumValue = agg.BestNum,
           Target   = CASE WHEN @mainMode = N'SUM' THEN @mainFloor ELSE agg.Target END,
           ViaCode  = agg.PassedVia
    FROM #scope sc
    OUTER APPLY
    (
        SELECT AnyPassed = MAX(CAST(h.Passed AS int)),
               AnyRow    = MAX(CAST(h.HasRow AS int)),
               BestNum   = MAX(h.NumValue),
               Target    = MAX(h.Target),
               PassedVia = MAX(CASE WHEN h.Passed = 1 THEN h.ViaCode END),
               /* A row that exists with a status but did not pass reads as started. */
               AnyStarted = MAX(CASE WHEN h.Passed = 0 AND h.TextValue IS NOT NULL THEN 1 ELSE 0 END)
        FROM #code_hit h WHERE h.PersonnelNo = sc.PersonnelNo
    ) agg;

    DROP TABLE #code_hit;
END
GO
PRINT '  sel.usp_Item_ResolveMet_Into      applied';
GO

/* sel.usp_Item_ResolveMet — the public form: one item, who in the pool meets it.
   Every read joins sec.fn_UserOrgScope, including this one.                            */
CREATE OR ALTER PROCEDURE sel.usp_Item_ResolveMet
    @LoginName   nvarchar(128),
    @ItemCode    nvarchar(60),
    @CycleId     int = NULL,
    @PersonnelNo nvarchar(30) = NULL,
    @AsOf        date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    CREATE TABLE #met
    (
        PersonnelNo nvarchar(30)  NOT NULL,
        ItemCode    nvarchar(60)  NOT NULL,
        Met         bit           NOT NULL,
        Why         nvarchar(600) NULL,
        NumValue    decimal(18,4) NULL,
        Target      decimal(18,4) NULL,
        ViaCode     nvarchar(60)  NULL
    );

    IF @PersonnelNo IS NOT NULL
        INSERT #scope (PersonnelNo)
        SELECT e.PersonnelNo FROM sel.Employee e
        JOIN sec.fn_UserOrgScope(@LoginName) s ON s.OrgCode = e.OrgCode
        WHERE e.PersonnelNo = @PersonnelNo;
    ELSE
        INSERT #scope (PersonnelNo)
        SELECT c.PersonnelNo FROM sel.CycleCandidate c
        JOIN sec.fn_UserOrgScope(@LoginName) s ON s.OrgCode = c.OrgCode
        WHERE c.CycleId = @CycleId;

    EXEC sel.usp_Item_ResolveMet_Into @ItemCode = @ItemCode, @AsOf = @AsOf;

    SELECT m.PersonnelNo, m.ItemCode, m.Met, m.Why, m.NumValue, m.Target, m.ViaCode,
           e.FullName, e.OrgCode, e.JobTitle, e.GradeCode
    FROM #met m
    JOIN sel.Employee e ON e.PersonnelNo = m.PersonnelNo
    ORDER BY m.Met DESC, e.FullName;

    DROP TABLE #met; DROP TABLE #scope;
END
GO
PRINT '  sel.usp_Item_ResolveMet           applied';
GO

/* sel.usp_Item_MetDetail — the drilldown behind every count.  It returns exactly the
   rows that count counted, including the organisation scope join, because a drilldown
   that shows a different set is the defect this rule exists to prevent.                */
CREATE OR ALTER PROCEDURE sel.usp_Item_MetDetail
    @LoginName nvarchar(128),
    @CycleId   int,
    @ItemCode  nvarchar(60),
    @MetOnly   bit = 1,
    @AsOf      date = NULL,
    @PageNo    int = 1,
    @PageSize  int = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);
    IF @PageSize IS NULL SET @PageSize = CAST(ISNULL(cfg.fn_SettingNum(N'PAGE_SIZE_DEFAULT'), 50) AS int);
    IF @PageNo IS NULL OR @PageNo < 1 SET @PageNo = 1;

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    CREATE TABLE #met
    (
        PersonnelNo nvarchar(30)  NOT NULL,
        ItemCode    nvarchar(60)  NOT NULL,
        Met         bit           NOT NULL,
        Why         nvarchar(600) NULL,
        NumValue    decimal(18,4) NULL,
        Target      decimal(18,4) NULL,
        ViaCode     nvarchar(60)  NULL
    );

    INSERT #scope (PersonnelNo)
    SELECT c.PersonnelNo FROM sel.CycleCandidate c
    JOIN sec.fn_UserOrgScope(@LoginName) s ON s.OrgCode = c.OrgCode
    WHERE c.CycleId = @CycleId;

    EXEC sel.usp_Item_ResolveMet_Into @ItemCode = @ItemCode, @AsOf = @AsOf;

    SELECT m.PersonnelNo, e.FullName, e.OrgCode, o.Name AS OrgName, e.JobTitle,
           e.GradeCode, m.Met, m.Why, m.NumValue, m.Target, m.ViaCode
    FROM #met m
    JOIN sel.Employee e ON e.PersonnelNo = m.PersonnelNo
    LEFT JOIN sel.OrgNode o ON o.OrgCode = e.OrgCode
    WHERE (@MetOnly = 0 OR m.Met = 1)
    ORDER BY e.FullName
    OFFSET (@PageNo - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;

    SELECT TotalRows = COUNT(*), MetCount = SUM(CAST(Met AS int)), PoolCount = (SELECT COUNT(*) FROM #scope)
    FROM #met WHERE (@MetOnly = 0 OR Met = 1);

    DROP TABLE #met; DROP TABLE #scope;
END
GO
PRINT '  sel.usp_Item_MetDetail            applied';
GO

/* =====================================================================================
   sel.usp_Framework_Attainment — the coverage panel
   -------------------------------------------------------------------------------------
   Pool-wide attainment: per item, how many met it; plus how many met everything, how many
   clear every mandatory item, and the median attainment.

   Above cfg.Setting 'ATTAINMENT_SAMPLE_CAP' the figures come off an evenly spaced sample
   and are scaled back, and the result says so.  An honest estimate beats a silent one and
   beats a five-second wait.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Framework_Attainment
    @LoginName      nvarchar(128),
    @CycleId        int,
    @DevFrameworkId int = NULL,
    @LevelNo        int = NULL,
    @AsOf           date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cap int = CAST(ISNULL(cfg.fn_SettingNum(N'ATTAINMENT_SAMPLE_CAP'), 600) AS int);

    /* The pool, inside this viewer's organisation scope. */
    CREATE TABLE #pool (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY, rn int NOT NULL);
    INSERT #pool (PersonnelNo, rn)
    SELECT c.PersonnelNo, ROW_NUMBER() OVER (ORDER BY c.PersonnelNo)
    FROM sel.CycleCandidate c
    JOIN sec.fn_UserOrgScope(@LoginName) s ON s.OrgCode = c.OrgCode
    WHERE c.CycleId = @CycleId;

    DECLARE @poolCount int = (SELECT COUNT(*) FROM #pool);
    DECLARE @isSampled bit = CASE WHEN @poolCount > @cap THEN 1 ELSE 0 END;
    DECLARE @sampleCount int = CASE WHEN @isSampled = 1 THEN @cap ELSE @poolCount END;

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    IF @isSampled = 1
        /* Evenly spaced, not the first N: the first N by personnel number is an
           organisation, not a sample. */
        INSERT #scope (PersonnelNo)
        SELECT PersonnelNo FROM #pool
        WHERE (rn - 1) % (CASE WHEN @cap = 0 THEN 1 ELSE (@poolCount / @cap) END) = 0
          AND rn <= (@poolCount / (CASE WHEN @cap = 0 THEN 1 ELSE (@poolCount / @cap) END)) * (CASE WHEN @cap = 0 THEN 1 ELSE (@poolCount / @cap) END);
    ELSE
        INSERT #scope (PersonnelNo) SELECT PersonnelNo FROM #pool;

    SET @sampleCount = (SELECT COUNT(*) FROM #scope);

    CREATE TABLE #met
    (
        PersonnelNo nvarchar(30)  NOT NULL,
        ItemCode    nvarchar(60)  NOT NULL,
        Met         bit           NOT NULL,
        Why         nvarchar(600) NULL,
        NumValue    decimal(18,4) NULL,
        Target      decimal(18,4) NULL,
        ViaCode     nvarchar(60)  NULL
    );

    /* The requirements this cycle asks for. */
    CREATE TABLE #req
    (
        DevEventId int NOT NULL, ItemCode nvarchar(60) NOT NULL,
        Weight decimal(9,4) NOT NULL, IsMust bit NOT NULL,
        LevelNo int NOT NULL, DevFrameworkId int NOT NULL
    );

    INSERT #req (DevEventId, ItemCode, Weight, IsMust, LevelNo, DevFrameworkId)
    SELECT i.DevEventId, e.ItemCode, i.Weight, i.IsMust, i.LevelNo, i.DevFrameworkId
    FROM sel.CycleFramework cf
    JOIN sel.DevFrameworkItem i ON i.DevFrameworkId = cf.DevFrameworkId
    JOIN sel.DevEvent e ON e.DevEventId = i.DevEventId
    WHERE cf.CycleId = @CycleId
      AND (@DevFrameworkId IS NULL OR cf.DevFrameworkId = @DevFrameworkId)
      AND (@LevelNo IS NULL OR i.LevelNo = @LevelNo)
      AND e.ItemCode IS NOT NULL;

    /* One statement per item, each answering the whole sample. */
    DECLARE @item nvarchar(60);
    DECLARE itemCur CURSOR LOCAL FAST_FORWARD FOR SELECT DISTINCT ItemCode FROM #req;
    OPEN itemCur; FETCH NEXT FROM itemCur INTO @item;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC sel.usp_Item_ResolveMet_Into @ItemCode = @item, @AsOf = @AsOf;
        FETCH NEXT FROM itemCur INTO @item;
    END;
    CLOSE itemCur; DEALLOCATE itemCur;

    DECLARE @scale decimal(18,6) =
        CASE WHEN @sampleCount = 0 THEN 1 ELSE CAST(@poolCount AS decimal(18,6)) / @sampleCount END;

    /* 1 — per item, worst first. */
    SELECT r.DevEventId, r.ItemCode, e.EventCode, e.Name AS EventName,
           r.Weight, r.IsMust, r.LevelNo, r.DevFrameworkId,
           RuleText = sel.fn_EventRuleText(e.DevEventId),
           MetInSample = ISNULL(x.MetCount, 0),
           /* Scaled back to the pool when the figures came off a sample. */
           MetCount   = CAST(ROUND(ISNULL(x.MetCount, 0) * @scale, 0) AS int),
           PoolCount  = @poolCount,
           SampleCount = @sampleCount,
           IsSampled  = @isSampled
    FROM (SELECT DISTINCT DevEventId, ItemCode, Weight, IsMust, LevelNo, DevFrameworkId FROM #req) r
    JOIN sel.DevEvent e ON e.DevEventId = r.DevEventId
    OUTER APPLY (SELECT MetCount = SUM(CAST(m.Met AS int)) FROM #met m WHERE m.ItemCode = r.ItemCode) x
    ORDER BY ISNULL(x.MetCount, 0) ASC, e.EventCode;

    /* 2 — the headline figures. */
    ;WITH perPerson AS
    (
        SELECT s.PersonnelNo,
               WeightTotal = (SELECT SUM(Weight) FROM (SELECT DISTINCT DevEventId, Weight FROM #req) z),
               WeightMet = ISNULL((SELECT SUM(r.Weight)
                                   FROM (SELECT DISTINCT DevEventId, ItemCode, Weight FROM #req) r
                                   JOIN #met m ON m.ItemCode = r.ItemCode AND m.PersonnelNo = s.PersonnelNo
                                   WHERE m.Met = 1), 0),
               MustOutstanding = ISNULL((SELECT COUNT(*)
                                   FROM (SELECT DISTINCT ItemCode FROM #req WHERE IsMust = 1) r
                                   LEFT JOIN #met m ON m.ItemCode = r.ItemCode AND m.PersonnelNo = s.PersonnelNo
                                   WHERE ISNULL(m.Met, 0) = 0), 0),
               ItemsOutstanding = ISNULL((SELECT COUNT(*)
                                   FROM (SELECT DISTINCT ItemCode FROM #req) r
                                   LEFT JOIN #met m ON m.ItemCode = r.ItemCode AND m.PersonnelNo = s.PersonnelNo
                                   WHERE ISNULL(m.Met, 0) = 0), 0)
        FROM #scope s
    ),
    pct AS
    (
        SELECT PersonnelNo,
               AttainmentPct = CASE WHEN ISNULL(WeightTotal, 0) = 0 THEN 0
                                    ELSE CAST(100.0 * WeightMet / WeightTotal AS decimal(9,4)) END,
               MustOutstanding, ItemsOutstanding
        FROM perPerson
    )
    SELECT PoolCount    = @poolCount,
           SampleCount  = @sampleCount,
           IsSampled    = @isSampled,
           ItemCount    = (SELECT COUNT(DISTINCT ItemCode) FROM #req),
           MustCount    = (SELECT COUNT(DISTINCT ItemCode) FROM #req WHERE IsMust = 1),
           MetEverything     = CAST(ROUND((SELECT COUNT(*) FROM pct WHERE ItemsOutstanding = 0) * @scale, 0) AS int),
           ClearAllMandatory = CAST(ROUND((SELECT COUNT(*) FROM pct WHERE MustOutstanding = 0) * @scale, 0) AS int),
           /* "Half the pool has finished 56% of this framework or more." */
           /* PERCENTILE_CONT returns a float; every other share in the application is a
              decimal, and a figure that changes type between screens is a figure that
              eventually rounds differently on one of them. */
           MedianAttainment = CONVERT(decimal(9,4),
                              (SELECT DISTINCT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY AttainmentPct)
                               OVER () FROM pct)),
           /* The panel says so, in the prototype's words. */
           SampleNote = CASE WHEN @isSampled = 1
                             THEN REPLACE(REPLACE(cfg.fn_Message(N'SAMPLED_FIGURES'),
                                  N'{sample}', CONVERT(nvarchar(20), @sampleCount)),
                                  N'{total}',  CONVERT(nvarchar(20), @poolCount))
                             ELSE NULL END;

    DROP TABLE #req; DROP TABLE #met; DROP TABLE #scope; DROP TABLE #pool;
END
GO
PRINT '  sel.usp_Framework_Attainment      applied';
GO

/* sel.usp_Attainment_PerPerson — one person's percentage against a cycle's requirements,
   and the requirement checklist behind it.  The profile ladder reads this, so the ladder
   and the attainment panel cannot disagree.                                             */
CREATE OR ALTER PROCEDURE sel.usp_Attainment_PerPerson
    @LoginName   nvarchar(128),
    @CycleId     int,
    @PersonnelNo nvarchar(30),
    @AsOf        date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    INSERT #scope (PersonnelNo)
    SELECT e.PersonnelNo FROM sel.Employee e
    JOIN sec.fn_UserOrgScope(@LoginName) s ON s.OrgCode = e.OrgCode
    WHERE e.PersonnelNo = @PersonnelNo;

    CREATE TABLE #met
    (
        PersonnelNo nvarchar(30)  NOT NULL, ItemCode nvarchar(60) NOT NULL,
        Met bit NOT NULL, Why nvarchar(600) NULL,
        NumValue decimal(18,4) NULL, Target decimal(18,4) NULL, ViaCode nvarchar(60) NULL
    );

    CREATE TABLE #req
    (
        DevEventId int NOT NULL, ItemCode nvarchar(60) NOT NULL,
        Weight decimal(9,4) NOT NULL, IsMust bit NOT NULL,
        LevelNo int NOT NULL, DevFrameworkId int NOT NULL
    );
    INSERT #req
    SELECT i.DevEventId, e.ItemCode, i.Weight, i.IsMust, i.LevelNo, i.DevFrameworkId
    FROM sel.CycleFramework cf
    JOIN sel.DevFrameworkItem i ON i.DevFrameworkId = cf.DevFrameworkId
    JOIN sel.DevEvent e ON e.DevEventId = i.DevEventId
    WHERE cf.CycleId = @CycleId AND e.ItemCode IS NOT NULL;

    DECLARE @item nvarchar(60);
    DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT DISTINCT ItemCode FROM #req;
    OPEN c; FETCH NEXT FROM c INTO @item;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC sel.usp_Item_ResolveMet_Into @ItemCode = @item, @AsOf = @AsOf;
        FETCH NEXT FROM c INTO @item;
    END;
    CLOSE c; DEALLOCATE c;

    /* 1 — the requirement checklist, with the reason on every row. */
    SELECT r.DevEventId, r.ItemCode, e.EventCode, e.Name AS EventName, r.Weight, r.IsMust,
           r.LevelNo, r.DevFrameworkId, f.Name AS FrameworkName,
           Met = ISNULL(m.Met, 0), m.Why, m.NumValue, m.Target, m.ViaCode,
           RuleShort = sel.fn_EventRuleShort(e.DevEventId)
    FROM (SELECT DISTINCT DevEventId, ItemCode, Weight, IsMust, LevelNo, DevFrameworkId FROM #req) r
    JOIN sel.DevEvent e ON e.DevEventId = r.DevEventId
    JOIN sel.DevFramework f ON f.DevFrameworkId = r.DevFrameworkId
    LEFT JOIN #met m ON m.ItemCode = r.ItemCode
    ORDER BY r.LevelNo, ISNULL(m.Met, 0), e.EventCode;

    /* 2 — the person's percentage, and whether a "must" disqualifies them. */
    SELECT PersonnelNo = @PersonnelNo,
           WeightTotal = (SELECT SUM(Weight) FROM (SELECT DISTINCT DevEventId, Weight FROM #req) z),
           WeightMet   = ISNULL((SELECT SUM(r.Weight)
                                 FROM (SELECT DISTINCT DevEventId, ItemCode, Weight FROM #req) r
                                 JOIN #met m ON m.ItemCode = r.ItemCode WHERE m.Met = 1), 0),
           AttainmentPct = CASE WHEN ISNULL((SELECT SUM(Weight) FROM (SELECT DISTINCT DevEventId, Weight FROM #req) z), 0) = 0
                                THEN 0
                                ELSE CAST(100.0 * ISNULL((SELECT SUM(r.Weight)
                                        FROM (SELECT DISTINCT DevEventId, ItemCode, Weight FROM #req) r
                                        JOIN #met m ON m.ItemCode = r.ItemCode WHERE m.Met = 1), 0)
                                     / (SELECT SUM(Weight) FROM (SELECT DISTINCT DevEventId, Weight FROM #req) z)
                                     AS decimal(9,4)) END,
           MustOutstanding = (SELECT COUNT(*) FROM (SELECT DISTINCT ItemCode FROM #req WHERE IsMust = 1) r
                              LEFT JOIN #met m ON m.ItemCode = r.ItemCode WHERE ISNULL(m.Met, 0) = 0),
           ItemsOutstanding = (SELECT COUNT(*) FROM (SELECT DISTINCT ItemCode FROM #req) r
                               LEFT JOIN #met m ON m.ItemCode = r.ItemCode WHERE ISNULL(m.Met, 0) = 0),
           InScope = (SELECT COUNT(*) FROM #scope);

    /* 3 — the readiness ladder: each level, what it asks, and where the person stands.
       Readiness is the highest level whose percentage is met; a "must" not met
       disqualifies outright. */
    ;WITH att AS
    (
        SELECT AttainmentPct = CASE WHEN ISNULL((SELECT SUM(Weight) FROM (SELECT DISTINCT DevEventId, Weight FROM #req) z), 0) = 0
                                    THEN 0
                                    ELSE CAST(100.0 * ISNULL((SELECT SUM(r.Weight)
                                            FROM (SELECT DISTINCT DevEventId, ItemCode, Weight FROM #req) r
                                            JOIN #met m ON m.ItemCode = r.ItemCode WHERE m.Met = 1), 0)
                                         / (SELECT SUM(Weight) FROM (SELECT DISTINCT DevEventId, Weight FROM #req) z)
                                         AS decimal(9,4)) END,
               MustOutstanding = (SELECT COUNT(*) FROM (SELECT DISTINCT ItemCode FROM #req WHERE IsMust = 1) r
                                  LEFT JOIN #met m ON m.ItemCode = r.ItemCode WHERE ISNULL(m.Met, 0) = 0)
    )
    SELECT lv.CycleReadinessId, lv.LevelCode, lv.Name, lv.ThresholdPct, lv.SortOrder,
           a.AttainmentPct, a.MustOutstanding,
           IsHeld = CONVERT(bit, CASE WHEN a.MustOutstanding > 0 THEN 0
                         WHEN lv.ThresholdPct IS NULL THEN 0
                         WHEN a.AttainmentPct >= lv.ThresholdPct THEN 1 ELSE 0 END),
           ShortByPct = CASE WHEN lv.ThresholdPct IS NULL THEN NULL
                             WHEN a.AttainmentPct >= lv.ThresholdPct THEN NULL
                             ELSE CAST(lv.ThresholdPct - a.AttainmentPct AS decimal(9,2)) END,
           StateWord = CASE WHEN a.MustOutstanding > 0 THEN cfg.fn_Message(N'LADDER_DISQUALIFIED')
                            WHEN lv.ThresholdPct IS NULL THEN cfg.fn_Message(N'LADDER_NO_THRESHOLD')
                            WHEN a.AttainmentPct >= lv.ThresholdPct THEN cfg.fn_Message(N'LADDER_HELD')
                            ELSE REPLACE(cfg.fn_Message(N'LADDER_SHORT'), N'{pct}',
                                 CONVERT(nvarchar(20), CAST(lv.ThresholdPct - a.AttainmentPct AS decimal(9,1)))) END
    FROM sel.CycleReadiness lv CROSS JOIN att a
    WHERE lv.CycleId = @CycleId
    ORDER BY lv.SortOrder;

    DROP TABLE #req; DROP TABLE #met; DROP TABLE #scope;
END
GO
PRINT '  sel.usp_Attainment_PerPerson      applied';
GO

/* sel.usp_Readiness_Spread — where the pool falls today.  Each person is counted at the
   HIGHEST level they clear, plus how many hold no level yet.  It reads the same
   per-person percentages as the ladder, so the two always agree.                        */
CREATE OR ALTER PROCEDURE sel.usp_Readiness_Spread
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cap int = CAST(ISNULL(cfg.fn_SettingNum(N'ATTAINMENT_SAMPLE_CAP'), 600) AS int);

    CREATE TABLE #pool (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY, rn int NOT NULL);
    INSERT #pool SELECT c.PersonnelNo, ROW_NUMBER() OVER (ORDER BY c.PersonnelNo)
    FROM sel.CycleCandidate c
    JOIN sec.fn_UserOrgScope(@LoginName) s ON s.OrgCode = c.OrgCode
    WHERE c.CycleId = @CycleId;

    DECLARE @poolCount int = (SELECT COUNT(*) FROM #pool);
    DECLARE @isSampled bit = CASE WHEN @poolCount > @cap THEN 1 ELSE 0 END;
    DECLARE @step int = CASE WHEN @isSampled = 1 AND @cap > 0 THEN (@poolCount / @cap) ELSE 1 END;

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    INSERT #scope SELECT PersonnelNo FROM #pool WHERE (rn - 1) % @step = 0;
    DECLARE @sampleCount int = (SELECT COUNT(*) FROM #scope);

    CREATE TABLE #met
    (
        PersonnelNo nvarchar(30) NOT NULL, ItemCode nvarchar(60) NOT NULL,
        Met bit NOT NULL, Why nvarchar(600) NULL,
        NumValue decimal(18,4) NULL, Target decimal(18,4) NULL, ViaCode nvarchar(60) NULL
    );
    CREATE TABLE #req
    (
        DevEventId int NOT NULL, ItemCode nvarchar(60) NOT NULL,
        Weight decimal(9,4) NOT NULL, IsMust bit NOT NULL
    );
    INSERT #req
    SELECT DISTINCT i.DevEventId, e.ItemCode, i.Weight, i.IsMust
    FROM sel.CycleFramework cf
    JOIN sel.DevFrameworkItem i ON i.DevFrameworkId = cf.DevFrameworkId
    JOIN sel.DevEvent e ON e.DevEventId = i.DevEventId
    WHERE cf.CycleId = @CycleId AND e.ItemCode IS NOT NULL;

    DECLARE @item nvarchar(60);
    DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT DISTINCT ItemCode FROM #req;
    OPEN c; FETCH NEXT FROM c INTO @item;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC sel.usp_Item_ResolveMet_Into @ItemCode = @item, @AsOf = @AsOf;
        FETCH NEXT FROM c INTO @item;
    END;
    CLOSE c; DEALLOCATE c;

    DECLARE @scale decimal(18,6) =
        CASE WHEN @sampleCount = 0 THEN 1 ELSE CAST(@poolCount AS decimal(18,6)) / @sampleCount END;
    DECLARE @wTotal decimal(18,4) = (SELECT SUM(Weight) FROM #req);

    ;WITH perPerson AS
    (
        SELECT s.PersonnelNo,
               AttainmentPct = CASE WHEN ISNULL(@wTotal, 0) = 0 THEN 0
                                    ELSE CAST(100.0 * ISNULL((SELECT SUM(r.Weight) FROM #req r
                                         JOIN #met m ON m.ItemCode = r.ItemCode AND m.PersonnelNo = s.PersonnelNo
                                         WHERE m.Met = 1), 0) / @wTotal AS decimal(9,4)) END,
               MustOutstanding = (SELECT COUNT(*) FROM #req r
                                  LEFT JOIN #met m ON m.ItemCode = r.ItemCode AND m.PersonnelNo = s.PersonnelNo
                                  WHERE r.IsMust = 1 AND ISNULL(m.Met, 0) = 0)
        FROM #scope s
    ),
    placed AS
    (
        SELECT p.PersonnelNo, p.AttainmentPct, p.MustOutstanding,
               /* The highest level they clear. */
               TopLevel = (SELECT TOP (1) lv.LevelCode FROM sel.CycleReadiness lv
                           WHERE lv.CycleId = @CycleId AND lv.ThresholdPct IS NOT NULL
                             AND p.MustOutstanding = 0 AND p.AttainmentPct >= lv.ThresholdPct
                           ORDER BY lv.ThresholdPct DESC)
        FROM perPerson p
    )
    SELECT lv.CycleReadinessId, lv.LevelCode, lv.Name, lv.ThresholdPct, lv.SortOrder,
           /* How many clear this cut at all... */
           ClearCutInSample = (SELECT COUNT(*) FROM placed p
                               WHERE p.MustOutstanding = 0 AND p.AttainmentPct >= lv.ThresholdPct),
           ClearCut = CAST(ROUND((SELECT COUNT(*) FROM placed p
                               WHERE p.MustOutstanding = 0 AND p.AttainmentPct >= lv.ThresholdPct) * @scale, 0) AS int),
           /* ...and how many are counted HERE, at the highest level they clear. */
           AtThisLevel = CAST(ROUND((SELECT COUNT(*) FROM placed p WHERE p.TopLevel = lv.LevelCode) * @scale, 0) AS int),
           PoolCount = @poolCount, SampleCount = @sampleCount, IsSampled = @isSampled
    FROM sel.CycleReadiness lv
    WHERE lv.CycleId = @CycleId
    ORDER BY lv.SortOrder;

    /* The people who hold no level yet, and those a "must" disqualifies. */
    ;WITH perPerson AS
    (
        SELECT s.PersonnelNo,
               AttainmentPct = CASE WHEN ISNULL(@wTotal, 0) = 0 THEN 0
                                    ELSE CAST(100.0 * ISNULL((SELECT SUM(r.Weight) FROM #req r
                                         JOIN #met m ON m.ItemCode = r.ItemCode AND m.PersonnelNo = s.PersonnelNo
                                         WHERE m.Met = 1), 0) / @wTotal AS decimal(9,4)) END,
               MustOutstanding = (SELECT COUNT(*) FROM #req r
                                  LEFT JOIN #met m ON m.ItemCode = r.ItemCode AND m.PersonnelNo = s.PersonnelNo
                                  WHERE r.IsMust = 1 AND ISNULL(m.Met, 0) = 0)
        FROM #scope s
    )
    SELECT PoolCount = @poolCount, SampleCount = @sampleCount, IsSampled = @isSampled,
           NoLevelYet = CAST(ROUND((SELECT COUNT(*) FROM perPerson p
                            WHERE NOT EXISTS (SELECT 1 FROM sel.CycleReadiness lv
                                              WHERE lv.CycleId = @CycleId AND lv.ThresholdPct IS NOT NULL
                                                AND p.MustOutstanding = 0 AND p.AttainmentPct >= lv.ThresholdPct)) * @scale, 0) AS int),
           Disqualified = CAST(ROUND((SELECT COUNT(*) FROM perPerson WHERE MustOutstanding > 0) * @scale, 0) AS int),
           SampleNote = CASE WHEN @isSampled = 1
                             THEN REPLACE(REPLACE(cfg.fn_Message(N'SAMPLED_FIGURES'),
                                  N'{sample}', CONVERT(nvarchar(20), @sampleCount)),
                                  N'{total}',  CONVERT(nvarchar(20), @poolCount))
                             ELSE NULL END;

    DROP TABLE #req; DROP TABLE #met; DROP TABLE #scope; DROP TABLE #pool;
END
GO
PRINT '  sel.usp_Readiness_Spread          applied';
GO

PRINT '== 07_evaluation_engine complete =====================================';
GO


/* ---- 08_pool_and_open.sql ------------------------------------------------------- */

/* =====================================================================================
   08_pool_and_open.sql  —  resolving the pool, validating the design, opening the cycle
   -------------------------------------------------------------------------------------
   The criteria builder writes sets of conditions; sel.usp_Criteria_BuildWhere turns them
   into one predicate over the mapped roster table; sel.usp_Pool_Preview answers "how many
   people is that" with a reach count per set, a sample, and — when the question could not
   be asked at all — a sentence instead of a zero.

   Each person has exactly one roster row, so the prototype's set operations over people
   (or also / and also / but not) reduce exactly to OR / AND / AND NOT over that row.
   That equivalence is what keeps a 79,000-row preview to a single scan.
   ===================================================================================== */
SET NOCOUNT ON;
GO

PRINT '';
PRINT '== 08_pool_and_open ==================================================';
GO

/* sel.vw_Candidate — the stable core of a candidate, for every screen that does not need
   the wide roster.  The ~200-column record is reached through the mapping, not mirrored
   here, so a new roster column never needs a migration.                                 */
CREATE OR ALTER VIEW sel.vw_Candidate
AS
SELECT e.PersonnelNo, e.FullName, e.OrgCode, o.Name AS OrgName, o.OrgLevel,
       e.JobTitle, e.PermJobSuffix, e.PermJobSuffixDesc, e.CurrentJobSuffix,
       e.GradeCode, e.ManagementLevelCode, e.IsActive, e.PermChiefInd,
       e.HireDate, e.PromotionDate, e.BirthDate, e.Gender, e.Nationality, e.Email
FROM sel.Employee e
LEFT JOIN sel.OrgNode o ON o.OrgCode = e.OrgCode;
GO
PRINT '  sel.vw_Candidate                  applied';
GO

/* sel.usp_RosterField_Sync — discovers every roster column, switched off.  Approving one
   makes it available to the criteria builder; the sensitive toggle is a separate
   question and is never set by discovery.                                               */
CREATE OR ALTER PROCEDURE sel.usp_RosterField_Sync
    @LoginName nvarchar(128),
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;

    IF sec.fn_ScreenAccess(@LoginName, N'/Selection/Setup/') < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS int) AS RosterFieldId;
        RETURN;
    END;

    DECLARE @schema nvarchar(128), @table nvarchar(128), @isMapped bit;
    SELECT @schema = SchemaName, @table = TableName, @isMapped = IsMapped
    FROM sel.TableMapping WHERE SourceKey = N'ROSTER';

    IF ISNULL(@isMapped, 0) = 0
    BEGIN
        SET @Problem = cfg.fn_Message(N'ROSTER_UNMAPPED');
        SELECT TOP (0) CAST(NULL AS int) AS RosterFieldId;
        RETURN;
    END;

    BEGIN TRAN;

    /* Anything previously discovered that is no longer in the table is marked absent
       rather than deleted, so a criterion that names it can still explain itself. */
    UPDATE sel.RosterField SET IsPresent = 0
    WHERE SourceKind = N'ROSTER'
      AND FieldName NOT IN (SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS
                            WHERE TABLE_SCHEMA = @schema AND TABLE_NAME = @table);

    MERGE sel.RosterField AS t
    USING (SELECT ColumnName = c.COLUMN_NAME,
                  SqlType    = c.DATA_TYPE,
                  DataType   = sel.fn_SqlTypeToDataType(c.DATA_TYPE),
                  OrdinalPos = c.ORDINAL_POSITION
           FROM INFORMATION_SCHEMA.COLUMNS c
           WHERE c.TABLE_SCHEMA = @schema AND c.TABLE_NAME = @table) AS s
       ON t.FieldName = s.ColumnName AND t.SourceKind = N'ROSTER'
    WHEN MATCHED THEN
        UPDATE SET SqlType = s.SqlType, DataType = s.DataType,
                   SortOrder = s.OrdinalPos, IsPresent = 1, LastSeenOnUtc = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        /* Discovered switched off. */
        INSERT (FieldName, Caption, DataType, SqlType, SourceKind, IsEnabled, IsSensitive,
                GroupName, SortOrder, LastSeenOnUtc)
        VALUES (s.ColumnName, s.ColumnName, s.DataType, s.SqlType, N'ROSTER', 0, 0,
                N'Roster', s.OrdinalPos, SYSUTCDATETIME());

    /* Derived figures are filterable too, and are read from sel.EmployeeMetric. */
    MERGE sel.RosterField AS t
    USING (SELECT MetricKey, Name, DataType FROM sel.MetricDefinition WHERE IsActive = 1) AS s
       ON t.FieldName = s.MetricKey AND t.SourceKind = N'METRIC'
    WHEN MATCHED THEN
        UPDATE SET Caption = s.Name, DataType = s.DataType, IsPresent = 1, LastSeenOnUtc = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (FieldName, Caption, DataType, SqlType, SourceKind, IsEnabled, IsSensitive,
                GroupName, SortOrder, LastSeenOnUtc)
        VALUES (s.MetricKey, s.Name, s.DataType, NULL, N'METRIC', 0, 0, N'Derived', 9000, SYSUTCDATETIME());

    /* Usage count: how many live criteria name each field. */
    UPDATE f SET UsageCount = ISNULL(x.N, 0)
    FROM sel.RosterField f
    OUTER APPLY (SELECT N = COUNT(*) FROM sel.CycleCriterion c WHERE c.RosterFieldId = f.RosterFieldId) x;

    COMMIT;

    EXEC audit.usp_Log @TableName = N'sel.RosterField', @KeyText = N'(sync)',
                       @ActionCode = N'SYNC', @LoginName = @LoginName;
    EXEC sel.usp_RosterField_List @LoginName = @LoginName;
END
GO
PRINT '  sel.usp_RosterField_Sync          applied';
GO

/* =====================================================================================
   sel.usp_Criteria_BuildWhere — the criteria as one predicate over the roster row
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Criteria_BuildWhere
    @CycleId int,
    @Alias   nvarchar(20) = N'rs',
    @AsOf    date = NULL,
    @Where   nvarchar(max) OUTPUT,
    @Problem nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);
    SET @Where = NULL; SET @Problem = NULL;

    IF NOT EXISTS (SELECT 1 FROM sel.CycleCriterionSet WHERE CycleId = @CycleId)
    BEGIN
        /* No criteria is not an error: the whole active roster is the pool. */
        SET @Where = N'(1 = 1)';
        RETURN;
    END;

    /* A criterion whose field is disabled, sensitive or absent cannot be asked.  Refuse
       with a sentence rather than quietly dropping the condition, which would widen the
       pool without anybody noticing. */
    DECLARE @badField nvarchar(300);
    SELECT TOP (1) @badField = f.FieldName +
           CASE WHEN f.IsPresent = 0  THEN N' is no longer in the roster'
                WHEN f.IsSensitive = 1 THEN N' is a sensitive field and cannot be filtered on'
                WHEN f.IsEnabled = 0   THEN N' has not been approved for use in criteria'
                ELSE N'' END
    FROM sel.CycleCriterion c
    JOIN sel.CycleCriterionSet cs ON cs.CriterionSetId = c.CriterionSetId
    JOIN sel.RosterField f ON f.RosterFieldId = c.RosterFieldId
    WHERE cs.CycleId = @CycleId
      AND (f.IsPresent = 0 OR f.IsSensitive = 1 OR f.IsEnabled = 0);

    IF @badField IS NOT NULL
    BEGIN
        SET @Problem = N'This pool cannot be resolved: ' + @badField + N'.';
        RETURN;
    END;

    DECLARE @folded nvarchar(max) = NULL, @first bit = 1;
    DECLARE @setId int, @mode nvarchar(60), @join nvarchar(60);

    DECLARE setCur CURSOR LOCAL FAST_FORWARD FOR
        SELECT cs.CriterionSetId, mv.ValueCode, jv.ValueCode
        FROM sel.CycleCriterionSet cs
        JOIN cfg.DomainValue mv ON mv.DomainValueId = cs.SetModeValueId
        LEFT JOIN cfg.DomainValue jv ON jv.DomainValueId = cs.SetJoinValueId
        WHERE cs.CycleId = @CycleId
        ORDER BY cs.SortOrder, cs.SetLabel;

    OPEN setCur; FETCH NEXT FROM setCur INTO @setId, @mode, @join;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        DECLARE @parts nvarchar(max) =
            STUFF((SELECT CASE WHEN @mode = N'ALL' THEN N' AND ' ELSE N' OR ' END
                        + cfg.fn_BuildPredicate(
                              /* A roster column is read from the roster row; a derived
                                 figure is read from sel.EmployeeMetric for that person. */
                              CASE WHEN f.SourceKind = N'METRIC'
                                   THEN N'(SELECT TOP (1) em.NumValue FROM sel.EmployeeMetric em WHERE em.PersonnelNo = '
                                      + @Alias + N'.' + QUOTENAME((SELECT KeyColumn FROM sel.TableMapping WHERE SourceKey = N'ROSTER'))
                                      + N' AND em.MetricKey = ' + cfg.fn_EscapeLiteral(f.FieldName) + N')'
                                   ELSE @Alias + N'.' + QUOTENAME(f.FieldName) END,
                              c.OperatorCode, c.Value1, c.Value2, f.DataType, @AsOf)
                   FROM sel.CycleCriterion c
                   JOIN sel.RosterField f ON f.RosterFieldId = c.RosterFieldId
                   WHERE c.CriterionSetId = @setId
                   ORDER BY c.SortOrder, c.CriterionId
                   FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'),
                  1, CASE WHEN @mode = N'ALL' THEN 5 ELSE 4 END, N'');

        DECLARE @setSql nvarchar(max);
        IF @parts IS NULL                       SET @setSql = N'(1 = 1)';
        ELSE IF @mode = N'NONE'                 SET @setSql = N'(NOT (' + @parts + N'))';
        ELSE                                    SET @setSql = N'(' + @parts + N')';

        IF @first = 1 BEGIN SET @folded = @setSql; SET @first = 0; END
        ELSE
            /* or also = union, and also = intersection, but not = difference. */
            SET @folded = N'(' + @folded +
                CASE ISNULL(@join, N'INTERSECT')
                     WHEN N'UNION'     THEN N' OR '
                     WHEN N'EXCEPT'    THEN N' AND NOT '
                     ELSE N' AND ' END
                + @setSql + N')';

        FETCH NEXT FROM setCur INTO @setId, @mode, @join;
    END;

    CLOSE setCur; DEALLOCATE setCur;
    SET @Where = ISNULL(@folded, N'(1 = 1)');
END
GO
PRINT '  sel.usp_Criteria_BuildWhere       applied';
GO

/* =====================================================================================
   sel.usp_Pool_Preview — the reach, the sample and the drill-down
   -------------------------------------------------------------------------------------
   Result 1: the rule read back, with a reach count per set and in total.
   Result 2: the sample / drill-down page, inside the viewer's organisation scope.
   Result 3: the totals, and whether the figures were sampled.

   When the question cannot be asked at all, @Problem carries the sentence and the counts
   come back NULL.  Distinguish "nobody qualifies" from "the question could not be asked":
   the UI must never render the second as a zero.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Pool_Preview
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL,
    @PageNo    int = 1,
    @PageSize  int = NULL,
    @Search    nvarchar(200) = NULL,
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);
    IF @PageSize IS NULL SET @PageSize = CAST(ISNULL(cfg.fn_SettingNum(N'PAGE_SIZE_DEFAULT'), 50) AS int);
    IF @PageNo IS NULL OR @PageNo < 1 SET @PageNo = 1;
    SET @Problem = NULL;

    DECLARE @obj nvarchar(300) = sel.fn_MappedObject(N'ROSTER');
    DECLARE @keyCol nvarchar(128) = (SELECT KeyColumn FROM sel.TableMapping WHERE SourceKey = N'ROSTER');

    IF @obj IS NULL OR @keyCol IS NULL
    BEGIN
        SET @Problem = cfg.fn_Message(N'ROSTER_UNMAPPED');
        SELECT TOP (0) CAST(NULL AS nvarchar(10)) AS SetLabel;
        SELECT TOP (0) CAST(NULL AS nvarchar(30)) AS PersonnelNo;
        SELECT TotalRows = CAST(NULL AS int), PoolCount = CAST(NULL AS int),
               IsSampled = CAST(0 AS bit), Problem = @Problem;
        RETURN;
    END;

    DECLARE @where nvarchar(max), @p nvarchar(400);
    EXEC sel.usp_Criteria_BuildWhere @CycleId = @CycleId, @Alias = N'rs', @AsOf = @AsOf,
                                     @Where = @where OUTPUT, @Problem = @p OUTPUT;
    IF @p IS NOT NULL
    BEGIN
        SET @Problem = @p;
        SELECT TOP (0) CAST(NULL AS nvarchar(10)) AS SetLabel;
        SELECT TOP (0) CAST(NULL AS nvarchar(30)) AS PersonnelNo;
        SELECT TotalRows = CAST(NULL AS int), PoolCount = CAST(NULL AS int),
               IsSampled = CAST(0 AS bit), Problem = @Problem;
        RETURN;
    END;

    /* The matching personnel numbers, once, inside the viewer's organisation scope. */
    CREATE TABLE #hit (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);

    DECLARE @sql nvarchar(max) = N'
        INSERT #hit (PersonnelNo)
        SELECT DISTINCT CONVERT(nvarchar(30), rs.' + QUOTENAME(@keyCol) + N')
        FROM ' + @obj + N' rs
        JOIN sel.Employee e ON e.PersonnelNo = CONVERT(nvarchar(30), rs.' + QUOTENAME(@keyCol) + N')
        JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = e.OrgCode
        WHERE ' + @where + N';';

    BEGIN TRY
        EXEC sp_executesql @sql, N'@LoginName nvarchar(128)', @LoginName = @LoginName;
    END TRY
    BEGIN CATCH
        /* The question could not be asked.  Say so; never answer zero. */
        SET @Problem = N'This pool could not be resolved: ' + ERROR_MESSAGE();
        SELECT TOP (0) CAST(NULL AS nvarchar(10)) AS SetLabel;
        SELECT TOP (0) CAST(NULL AS nvarchar(30)) AS PersonnelNo;
        SELECT TotalRows = CAST(NULL AS int), PoolCount = CAST(NULL AS int),
               IsSampled = CAST(0 AS bit), Problem = @Problem;
        RETURN;
    END CATCH;

    /* 1 — the rule read back as a sentence, with per-set reach. */
    CREATE TABLE #setReach (SetLabel nvarchar(10), Sentence nvarchar(max), Reach int, SortOrder int);

    DECLARE @setId int, @label nvarchar(10), @mode nvarchar(60), @join nvarchar(60), @sort int;
    DECLARE setCur CURSOR LOCAL FAST_FORWARD FOR
        SELECT cs.CriterionSetId, cs.SetLabel, mv.Name, jv.Name, cs.SortOrder
        FROM sel.CycleCriterionSet cs
        JOIN cfg.DomainValue mv ON mv.DomainValueId = cs.SetModeValueId
        LEFT JOIN cfg.DomainValue jv ON jv.DomainValueId = cs.SetJoinValueId
        WHERE cs.CycleId = @CycleId ORDER BY cs.SortOrder, cs.SetLabel;

    OPEN setCur; FETCH NEXT FROM setCur INTO @setId, @label, @mode, @join, @sort;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        DECLARE @sentence nvarchar(max) =
            ISNULL(@join + N' ', N'') + N'Set ' + @label + N': ' + @mode + N' of ' +
            ISNULL(STUFF((SELECT N'; ' + f.Caption + N' ' + o.Name
                           + CASE WHEN o.Arity = 0 THEN N''
                                  WHEN o.Arity = 1 THEN N' ' + ISNULL(c.Value1, N'(no value)')
                                  ELSE N' ' + ISNULL(c.Value1, N'(no value)') + N' and ' + ISNULL(c.Value2, N'(no value)') END
                   FROM sel.CycleCriterion c
                   JOIN sel.RosterField f ON f.RosterFieldId = c.RosterFieldId
                   JOIN cfg.Operator o ON o.OperatorCode = c.OperatorCode
                   WHERE c.CriterionSetId = @setId ORDER BY c.SortOrder
                   FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, N''), N'(no conditions yet)');

        /* This set's own reach, independent of the others. */
        DECLARE @setWhere nvarchar(max) =
            ISNULL(STUFF((SELECT N' AND ' + cfg.fn_BuildPredicate(
                                CASE WHEN f.SourceKind = N'METRIC'
                                     THEN N'(SELECT TOP (1) em.NumValue FROM sel.EmployeeMetric em WHERE em.PersonnelNo = rs.'
                                        + QUOTENAME(@keyCol) + N' AND em.MetricKey = ' + cfg.fn_EscapeLiteral(f.FieldName) + N')'
                                     ELSE N'rs.' + QUOTENAME(f.FieldName) END,
                                c.OperatorCode, c.Value1, c.Value2, f.DataType, @AsOf)
                          FROM sel.CycleCriterion c
                          JOIN sel.RosterField f ON f.RosterFieldId = c.RosterFieldId
                          WHERE c.CriterionSetId = @setId ORDER BY c.SortOrder
                          FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 5, N''), N'(1 = 1)');

        DECLARE @reach int = NULL;
        DECLARE @rsql nvarchar(max) = N'
            SELECT @reach = COUNT(DISTINCT CONVERT(nvarchar(30), rs.' + QUOTENAME(@keyCol) + N'))
            FROM ' + @obj + N' rs
            JOIN sel.Employee e ON e.PersonnelNo = CONVERT(nvarchar(30), rs.' + QUOTENAME(@keyCol) + N')
            JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = e.OrgCode
            WHERE ' + @setWhere + N';';
        BEGIN TRY
            EXEC sp_executesql @rsql, N'@LoginName nvarchar(128), @reach int OUTPUT',
                 @LoginName = @LoginName, @reach = @reach OUTPUT;
        END TRY
        BEGIN CATCH SET @reach = NULL; END CATCH;

        INSERT #setReach VALUES (@label, @sentence, @reach, @sort);
        FETCH NEXT FROM setCur INTO @setId, @label, @mode, @join, @sort;
    END;
    CLOSE setCur; DEALLOCATE setCur;

    SELECT SetLabel, Sentence, Reach, SortOrder FROM #setReach ORDER BY SortOrder;

    /* 2 — the sample / drill-down page. */
    /* The same columns sel.usp_Employee_Roster returns, in the same order: one record
       is filled from both. */
    SELECT c.PersonnelNo, c.FullName, c.OrgCode, c.OrgName, c.JobTitle,
           c.PermJobSuffix, c.PermJobSuffixDesc, c.GradeCode, c.ManagementLevelCode,
           c.HireDate, c.PromotionDate, c.IsActive, c.PermChiefInd
    FROM #hit h
    JOIN sel.vw_Candidate c ON c.PersonnelNo = h.PersonnelNo
    WHERE (@Search IS NULL OR c.FullName LIKE N'%' + @Search + N'%'
           OR c.PersonnelNo LIKE N'%' + @Search + N'%'
           OR c.JobTitle LIKE N'%' + @Search + N'%'
           OR c.OrgName LIKE N'%' + @Search + N'%')
    ORDER BY c.FullName
    OFFSET (@PageNo - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;

    /* 3 — the totals. */
    SELECT TotalRows = (SELECT COUNT(*) FROM #hit h JOIN sel.vw_Candidate c ON c.PersonnelNo = h.PersonnelNo
                        WHERE (@Search IS NULL OR c.FullName LIKE N'%' + @Search + N'%'
                               OR c.PersonnelNo LIKE N'%' + @Search + N'%'
                               OR c.JobTitle LIKE N'%' + @Search + N'%'
                               OR c.OrgName LIKE N'%' + @Search + N'%')),
           PoolCount = (SELECT COUNT(*) FROM #hit),
           IsSampled = CAST(0 AS bit),
           Problem   = CAST(NULL AS nvarchar(400));

    DROP TABLE #setReach; DROP TABLE #hit;
END
GO
PRINT '  sel.usp_Pool_Preview              applied';
GO

/* =====================================================================================
   sel.usp_Cycle_Validate — what blocks opening, each with the step that fixes it
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Cycle_Validate
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL,
    /* The wizard wants all three result sets; sel.usp_Cycle_Open wants only the to-do
       list, because INSERT ... EXEC captures every set a procedure returns and would
       fail on the two that follow. One flag beats two procedures drifting apart. */
    @TodoOnly  bit = 0
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @skipped TABLE (StepNo int PRIMARY KEY);
    INSERT @skipped SELECT StepNo FROM sel.CycleSkippedStep WHERE CycleId = @CycleId;

    DECLARE @fail TABLE (RuleCode nvarchar(60) PRIMARY KEY);

    /* Step 1 — the cycle itself. */
    IF EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleId = @CycleId AND (StartDate IS NULL OR EndDate IS NULL))
        INSERT @fail VALUES (N'CYCLE_NO_WINDOW');
    IF EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleId = @CycleId AND NULLIF(LTRIM(RTRIM(Name)), N'') IS NULL)
        INSERT @fail VALUES (N'CYCLE_NO_NAME');
    IF EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleId = @CycleId AND StartDate IS NOT NULL
                 AND EndDate IS NOT NULL AND EndDate < StartDate)
        INSERT @fail VALUES (N'CYCLE_WINDOW_BACKWARDS');
    IF EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleId = @CycleId AND NULLIF(LTRIM(RTRIM(OwnerLogin)), N'') IS NULL)
        INSERT @fail VALUES (N'CYCLE_NO_OWNER');

    /* Step 2 — the eligible pool. */
    IF NOT EXISTS (SELECT 1 FROM @skipped WHERE StepNo = 2)
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM sel.CycleCriterionSet WHERE CycleId = @CycleId)
            INSERT @fail VALUES (N'POOL_NO_SET');

        /* An unfinished value: an operator that needs a value and has not got one. */
        IF EXISTS (SELECT 1 FROM sel.CycleCriterion c
                   JOIN sel.CycleCriterionSet cs ON cs.CriterionSetId = c.CriterionSetId
                   JOIN cfg.Operator o ON o.OperatorCode = c.OperatorCode
                   WHERE cs.CycleId = @CycleId
                     AND ((o.Arity >= 1 AND NULLIF(LTRIM(RTRIM(ISNULL(c.Value1, N''))), N'') IS NULL)
                       OR (o.Arity >= 2 AND NULLIF(LTRIM(RTRIM(ISNULL(c.Value2, N''))), N'') IS NULL)))
            INSERT @fail VALUES (N'POOL_UNFINISHED_VALUE');

        /* A pool linked but no membership table mapped. */
        IF EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleId = @CycleId AND ExistingPoolCode IS NOT NULL)
           AND ISNULL((SELECT IsMapped FROM sel.TableMapping WHERE SourceKey = N'POOL'), 0) = 0
            INSERT @fail VALUES (N'POOL_LINK_UNMAPPED');
    END;

    /* Step 3 — frameworks. */
    IF NOT EXISTS (SELECT 1 FROM @skipped WHERE StepNo = 3)
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM sel.CycleFramework WHERE CycleId = @CycleId)
            INSERT @fail VALUES (N'FRAMEWORK_NONE');
        IF EXISTS (SELECT 1 FROM sel.CycleFramework cf
                   JOIN sel.DevFramework f ON f.DevFrameworkId = cf.DevFrameworkId
                   JOIN cfg.DomainValue dv ON dv.DomainValueId = f.StatusValueId
                   WHERE cf.CycleId = @CycleId AND dv.ValueCode = N'DRAFT')
            INSERT @fail VALUES (N'FRAMEWORK_DRAFT');
        IF EXISTS (SELECT 1 FROM sel.CycleFramework cf
                   WHERE cf.CycleId = @CycleId
                     AND NOT EXISTS (SELECT 1 FROM sel.DevFrameworkItem i WHERE i.DevFrameworkId = cf.DevFrameworkId))
            INSERT @fail VALUES (N'FRAMEWORK_EMPTY');
        IF EXISTS (SELECT 1 FROM sel.CycleFramework cf
                   JOIN sel.DevFramework f ON f.DevFrameworkId = cf.DevFrameworkId
                   WHERE cf.CycleId = @CycleId AND f.IsActive = 0)
            INSERT @fail VALUES (N'FRAMEWORK_RETIRED');
    END;

    /* Step 4 — readiness levels. */
    IF NOT EXISTS (SELECT 1 FROM @skipped WHERE StepNo = 4)
    BEGIN
        IF EXISTS (SELECT 1 FROM sel.CycleReadiness WHERE CycleId = @CycleId
                     AND (NULLIF(LTRIM(RTRIM(LevelCode)), N'') IS NULL OR NULLIF(LTRIM(RTRIM(Name)), N'') IS NULL))
            INSERT @fail VALUES (N'READINESS_NO_NAME');
        IF EXISTS (SELECT 1 FROM sel.CycleReadiness WHERE CycleId = @CycleId AND ThresholdPct IS NULL)
            INSERT @fail VALUES (N'READINESS_NO_PCT');
        IF EXISTS (SELECT ThresholdPct FROM sel.CycleReadiness WHERE CycleId = @CycleId
                   GROUP BY ThresholdPct HAVING COUNT(*) > 1)
            INSERT @fail VALUES (N'READINESS_DUP_PCT');
        IF EXISTS (SELECT 1 FROM sel.CycleReadiness WHERE CycleId = @CycleId)
           AND NOT EXISTS (SELECT 1 FROM sel.CycleFramework cf
                           JOIN sel.DevFrameworkItem i ON i.DevFrameworkId = cf.DevFrameworkId
                           WHERE cf.CycleId = @CycleId)
            INSERT @fail VALUES (N'READINESS_NO_EVENTS');
    END;

    /* Step 5 — stages. */
    IF NOT EXISTS (SELECT 1 FROM @skipped WHERE StepNo = 5)
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM sel.CycleProcess WHERE CycleId = @CycleId)
            INSERT @fail VALUES (N'STAGE_NO_PROCESS');
        IF EXISTS (SELECT 1 FROM sel.CycleProcess p
                   WHERE p.CycleId = @CycleId
                     AND NOT EXISTS (SELECT 1 FROM sel.CycleStage s WHERE s.CycleProcessId = p.CycleProcessId))
            INSERT @fail VALUES (N'STAGE_NO_STAGES');
        IF EXISTS (SELECT 1 FROM sel.CycleStage s
                   JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                   WHERE p.CycleId = @CycleId AND (s.StartDate IS NULL OR s.EndDate IS NULL))
            INSERT @fail VALUES (N'STAGE_NO_WINDOW');
        IF EXISTS (SELECT 1 FROM sel.CycleStage s
                   JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                   JOIN sel.Cycle cy ON cy.CycleId = p.CycleId
                   WHERE p.CycleId = @CycleId AND s.StartDate IS NOT NULL AND cy.StartDate IS NOT NULL
                     AND (s.StartDate < cy.StartDate OR s.EndDate > cy.EndDate))
            INSERT @fail VALUES (N'STAGE_OUTSIDE_CYCLE');
        IF EXISTS (SELECT 1 FROM sel.CycleStage a
                   JOIN sel.CycleStage b ON b.CycleProcessId = a.CycleProcessId AND b.CycleStageId <> a.CycleStageId
                   JOIN sel.CycleProcess p ON p.CycleProcessId = a.CycleProcessId
                   WHERE p.CycleId = @CycleId AND a.SortOrder < b.SortOrder
                     AND a.EndDate IS NOT NULL AND b.StartDate IS NOT NULL AND a.EndDate > b.StartDate)
            INSERT @fail VALUES (N'STAGE_OVERLAP');
        IF EXISTS (SELECT 1 FROM sel.CycleStage s
                   JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                   WHERE p.CycleId = @CycleId AND s.PerformerLevelValueId IS NULL)
            INSERT @fail VALUES (N'STAGE_NO_PERFORMER');
    END;

    /* Up to five to-dos, each with the step that fixes it. */
    SELECT TOP (CAST(ISNULL(cfg.fn_SettingNum(N'VALIDATION_MAX_SHOWN'), 5) AS int))
           v.ValidationRuleId, v.RuleCode, v.StepNo, v.Sentence, v.Severity, v.SortOrder,
           StepCaption = (SELECT Caption FROM sel.WizardStep w WHERE w.StepNo = v.StepNo)
    FROM sel.ValidationRule v
    JOIN @fail f ON f.RuleCode = v.RuleCode
    WHERE v.IsActive = 1
    ORDER BY v.SortOrder, v.RuleCode;

    IF @TodoOnly = 1 RETURN;

    /* The progress meter: "3 of 5 set · 1 skipped · still to do: Eligible pool." */
    SELECT TotalBlocking = (SELECT COUNT(*) FROM sel.ValidationRule v JOIN @fail f ON f.RuleCode = v.RuleCode
                            WHERE v.IsActive = 1 AND v.Severity = N'BLOCK'),
           IsReadyToOpen = CONVERT(bit, CASE WHEN EXISTS (SELECT 1 FROM sel.ValidationRule v JOIN @fail f ON f.RuleCode = v.RuleCode
                                             WHERE v.IsActive = 1 AND v.Severity = N'BLOCK')
                                THEN 0 ELSE 1 END),
           StepsSet     = (SELECT COUNT(*) FROM sel.fn_CycleConfiguredTracks(@CycleId) WHERE IsSet = 1),
           StepsTotal   = (SELECT COUNT(*) FROM sel.fn_CycleConfiguredTracks(@CycleId)),
           StepsSkipped = (SELECT COUNT(*) FROM @skipped);

    /* The five tracks, so the design list can show which step is missing without a number. */
    SELECT TrackCode, IsSet, SortOrder FROM sel.fn_CycleConfiguredTracks(@CycleId) ORDER BY SortOrder;
END
GO
PRINT '  sel.usp_Cycle_Validate            applied';
GO

/* =====================================================================================
   sel.usp_Cycle_AutoSchedule — setting both dates gives every undated process and stage
   its share of the window, in order.  A hand-set window is never overwritten.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Cycle_AutoSchedule
    @LoginName nvarchar(128),
    @CycleId   int,
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;

    IF sec.fn_CanEditCycle(@LoginName, @CycleId) = 0
    BEGIN
        SET @Problem = sec.fn_CycleEditRefusal(@LoginName, @CycleId);
        SELECT TOP (0) CAST(NULL AS int) AS CycleProcessId;
        RETURN;
    END;

    DECLARE @start date, @end date;
    SELECT @start = StartDate, @end = EndDate FROM sel.Cycle WHERE CycleId = @CycleId;

    IF @start IS NULL OR @end IS NULL
    BEGIN
        SET @Problem = N'Set both a start and an end date before the stages can be scheduled.';
        SELECT TOP (0) CAST(NULL AS int) AS CycleProcessId;
        RETURN;
    END;

    BEGIN TRAN;

    DECLARE @days int = DATEDIFF(DAY, @start, @end);
    DECLARE @procCount int = (SELECT COUNT(*) FROM sel.CycleProcess WHERE CycleId = @CycleId AND (StartDate IS NULL OR EndDate IS NULL));

    /* Undated processes take an equal share of the window, in order. */
    IF @procCount > 0
    BEGIN
        ;WITH p AS
        (
            SELECT CycleProcessId, rn = ROW_NUMBER() OVER (ORDER BY SortOrder, CycleProcessId),
                   n = COUNT(*) OVER ()
            FROM sel.CycleProcess WHERE CycleId = @CycleId AND (StartDate IS NULL OR EndDate IS NULL)
        )
        UPDATE cp
           SET StartDate = DATEADD(DAY, CAST(@days * (p.rn - 1.0) / p.n AS int), @start),
               EndDate   = DATEADD(DAY, CAST(@days * (p.rn * 1.0)  / p.n AS int) - 1, @start)
        FROM sel.CycleProcess cp JOIN p ON p.CycleProcessId = cp.CycleProcessId;
    END;

    /* Each process's undated stages split that process's window, in order. */
    ;WITH s AS
    (
        SELECT st.CycleStageId, st.CycleProcessId,
               rn = ROW_NUMBER() OVER (PARTITION BY st.CycleProcessId ORDER BY st.SortOrder, st.CycleStageId),
               n  = COUNT(*)     OVER (PARTITION BY st.CycleProcessId),
               pStart = cp.StartDate, pDays = DATEDIFF(DAY, cp.StartDate, cp.EndDate)
        FROM sel.CycleStage st
        JOIN sel.CycleProcess cp ON cp.CycleProcessId = st.CycleProcessId
        WHERE cp.CycleId = @CycleId AND (st.StartDate IS NULL OR st.EndDate IS NULL)
          AND cp.StartDate IS NOT NULL AND cp.EndDate IS NOT NULL
    )
    UPDATE cs
       SET StartDate = DATEADD(DAY, CAST(s.pDays * (s.rn - 1.0) / s.n AS int), s.pStart),
           EndDate   = DATEADD(DAY, CAST(s.pDays * (s.rn * 1.0)  / s.n AS int) - 1, s.pStart)
    FROM sel.CycleStage cs JOIN s ON s.CycleStageId = cs.CycleStageId;

    COMMIT;

    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @CycleId);
    EXEC audit.usp_Log @TableName = N'sel.CycleStage', @KeyText = @keyText,
                       @ActionCode = N'AUTOSCHEDULE', @LoginName = @LoginName;

    SELECT p.CycleProcessId, p.Name AS ProcessName, p.StartDate AS ProcessStart, p.EndDate AS ProcessEnd,
           s.CycleStageId, s.Name AS StageName, s.StartDate, s.EndDate, s.SortOrder
    FROM sel.CycleProcess p
    LEFT JOIN sel.CycleStage s ON s.CycleProcessId = p.CycleProcessId
    WHERE p.CycleId = @CycleId
    ORDER BY p.SortOrder, s.SortOrder;
END
GO
PRINT '  sel.usp_Cycle_AutoSchedule        applied';
GO

/* =====================================================================================
   sel.usp_Cycle_Open — resolve the pool, write it as a snapshot, start the first stage,
   and make the draft Active permanently.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Cycle_Open
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL,
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);
    SET @Problem = NULL;

    IF sec.fn_CanEditCycle(@LoginName, @CycleId) = 0
    BEGIN
        SET @Problem = sec.fn_CycleEditRefusal(@LoginName, @CycleId);
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        RETURN;
    END;

    IF sel.fn_CycleStatusCode(@CycleId) <> N'DRAFT'
    BEGIN
        SET @Problem = N'Only a draft can be opened. This cycle is already '
                     + LOWER(ISNULL(sel.fn_CycleStatusCode(@CycleId), N'unknown')) + N'.';
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        RETURN;
    END;

    /* The design must pass its own validation first. */
    /* Re-run the validation into a table so the refusal names the real count.  The same
       procedure the wizard calls, asked for its to-do list alone. */
    CREATE TABLE #todo (ValidationRuleId int, RuleCode nvarchar(60), StepNo int,
                        Sentence nvarchar(600), Severity nvarchar(20), SortOrder int,
                        StepCaption nvarchar(120));
    INSERT #todo EXEC sel.usp_Cycle_Validate @LoginName = @LoginName, @CycleId = @CycleId,
                                             @AsOf = @AsOf, @TodoOnly = 1;

    DECLARE @blocking int = (SELECT COUNT(*) FROM #todo WHERE Severity = N'BLOCK');
    IF @blocking > 0
    BEGIN
        SET @Problem = CONVERT(nvarchar(10), @blocking) + N' thing'
                     + CASE WHEN @blocking = 1 THEN N' is' ELSE N's are' END
                     + N' unfinished, so this cycle cannot be opened yet.';
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        DROP TABLE #todo;
        RETURN;
    END;
    DROP TABLE #todo;

    DECLARE @obj nvarchar(300) = sel.fn_MappedObject(N'ROSTER');
    DECLARE @keyCol nvarchar(128) = (SELECT KeyColumn FROM sel.TableMapping WHERE SourceKey = N'ROSTER');
    IF @obj IS NULL
    BEGIN
        SET @Problem = cfg.fn_Message(N'ROSTER_UNMAPPED');
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        RETURN;
    END;

    DECLARE @where nvarchar(max), @p nvarchar(400);
    EXEC sel.usp_Criteria_BuildWhere @CycleId = @CycleId, @Alias = N'rs', @AsOf = @AsOf,
                                     @Where = @where OUTPUT, @Problem = @p OUTPUT;
    IF @p IS NOT NULL
    BEGIN
        SET @Problem = @p;
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        RETURN;
    END;

    BEGIN TRAN;

    /* The eligible pool.  Note this resolves across the WHOLE organisation, not the
       opener's scope: the snapshot is the cycle's, not one viewer's.  Row-level security
       is applied on every read of it afterwards. */
    DECLARE @sql nvarchar(max) = N'
        INSERT sel.CycleCandidate (CycleId, PersonnelNo, SourceCode, OrgCode, AddedByLogin)
        SELECT DISTINCT @CycleId, e.PersonnelNo, N''ELIGIBLE'', e.OrgCode, @LoginName
        FROM ' + @obj + N' rs
        JOIN sel.Employee e ON e.PersonnelNo = CONVERT(nvarchar(30), rs.' + QUOTENAME(@keyCol) + N')
        WHERE ' + @where + N'
          AND NOT EXISTS (SELECT 1 FROM sel.CycleCandidate cc
                          WHERE cc.CycleId = @CycleId AND cc.PersonnelNo = e.PersonnelNo);';

    EXEC sp_executesql @sql, N'@CycleId int, @LoginName nvarchar(128)',
         @CycleId = @CycleId, @LoginName = @LoginName;

    /* The existing pool carried in: matched on end year - 1 = pool year and the successor
       suffix.  A carried person is marked so the source tag persists through every stage. */
    IF EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleId = @CycleId AND ExistingPoolCode IS NOT NULL)
       AND ISNULL((SELECT IsMapped FROM sel.TableMapping WHERE SourceKey = N'POOL'), 0) = 1
    BEGIN
        DECLARE @poolObj nvarchar(300) = sel.fn_MappedObject(N'POOL');
        DECLARE @poolKey nvarchar(128) = (SELECT KeyColumn  FROM sel.TableMapping WHERE SourceKey = N'POOL');
        DECLARE @poolItem nvarchar(128) = (SELECT ItemColumn FROM sel.TableMapping WHERE SourceKey = N'POOL');
        DECLARE @poolCode nvarchar(60) = (SELECT ExistingPoolCode FROM sel.Cycle WHERE CycleId = @CycleId);
        DECLARE @poolYear int = (SELECT YEAR(EndDate) - 1 FROM sel.Cycle WHERE CycleId = @CycleId);

        DECLARE @psql nvarchar(max) = N'
            INSERT sel.CycleCandidate (CycleId, PersonnelNo, SourceCode, OrgCode, AddedByLogin)
            SELECT DISTINCT @CycleId, e.PersonnelNo, N''EXISTING POOL'', e.OrgCode, @LoginName
            FROM ' + @poolObj + N' pm
            JOIN sel.Employee e ON e.PersonnelNo = CONVERT(nvarchar(30), pm.' + QUOTENAME(@poolKey) + N')
            WHERE pm.' + QUOTENAME(@poolItem) + N' = @poolCode
              AND NOT EXISTS (SELECT 1 FROM sel.CycleCandidate cc
                              WHERE cc.CycleId = @CycleId AND cc.PersonnelNo = e.PersonnelNo);';
        BEGIN TRY
            EXEC sp_executesql @psql,
                 N'@CycleId int, @LoginName nvarchar(128), @poolCode nvarchar(60)',
                 @CycleId = @CycleId, @LoginName = @LoginName, @poolCode = @poolCode;
        END TRY
        BEGIN CATCH
            /* A carry-in that cannot be read is a load exception, not a silent omission. */
            INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText)
            VALUES (N'POOL', @poolObj, @poolCode, N'CARRY_IN_FAILED',
                    N'Last year''s pool could not be carried into this cycle: ' + ERROR_MESSAGE());
        END CATCH;
    END;

    /* The trace: for each pooled person, which criterion was satisfied and with what. */
    INSERT sel.CycleCandidateTrace (CycleId, PersonnelNo, CriterionId, SetLabel, FieldName,
                                    OperatorName, TestedValue, ActualValue, Passed)
    SELECT cc.CycleId, cc.PersonnelNo, c.CriterionId, cs.SetLabel, f.FieldName, o.Name,
           CASE WHEN o.Arity = 0 THEN NULL
                WHEN o.Arity = 1 THEN c.Value1
                ELSE c.Value1 + N' and ' + ISNULL(c.Value2, N'') END,
           NULL, 1
    FROM sel.CycleCandidate cc
    JOIN sel.CycleCriterionSet cs ON cs.CycleId = cc.CycleId
    JOIN sel.CycleCriterion c ON c.CriterionSetId = cs.CriterionSetId
    JOIN sel.RosterField f ON f.RosterFieldId = c.RosterFieldId
    JOIN cfg.Operator o ON o.OperatorCode = c.OperatorCode
    WHERE cc.CycleId = @CycleId AND cc.SourceCode = N'ELIGIBLE';

    /* Every process starts with the whole pool. */
    INSERT sel.ProcessCandidate (CycleProcessId, PersonnelNo, SourceCode, AddedByLogin)
    SELECT p.CycleProcessId, cc.PersonnelNo, cc.SourceCode, @LoginName
    FROM sel.CycleProcess p
    JOIN sel.CycleCandidate cc ON cc.CycleId = p.CycleId
    WHERE p.CycleId = @CycleId
      AND NOT EXISTS (SELECT 1 FROM sel.ProcessCandidate pc
                      WHERE pc.CycleProcessId = p.CycleProcessId AND pc.PersonnelNo = cc.PersonnelNo);

    DECLARE @count int = (SELECT COUNT(*) FROM sel.CycleCandidate WHERE CycleId = @CycleId);

    UPDATE sel.Cycle
       SET StatusValueId = cfg.fn_DomainValueId(N'CYCLE_STATUS', N'ACTIVE'),
           OpenedOnUtc = SYSUTCDATETIME(),
           PoolResolvedOnUtc = SYSUTCDATETIME(),
           PoolCount = @count
    WHERE CycleId = @CycleId;

    COMMIT;

    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @CycleId);
    EXEC audit.usp_Log @TableName = N'sel.Cycle', @KeyText = @keyText,
                       @ActionCode = N'OPEN', @LoginName = @LoginName;

    SELECT CycleId = @CycleId, PoolCount = @count,
           FirstStageId = (SELECT TOP (1) s.CycleStageId
                           FROM sel.CycleStage s
                           JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                           WHERE p.CycleId = @CycleId
                           ORDER BY p.SortOrder, s.SortOrder);
END
GO
PRINT '  sel.usp_Cycle_Open                applied';
GO

/* =====================================================================================
   sel.usp_Cycle_Copy — carries design, criteria, levels, processes, frameworks and pool
   rules forward as a new Draft.  It never carries the snapshot or the decisions.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Cycle_Copy
    @LoginName   nvarchar(128),
    @SourceCycleId int,
    @NewCode     nvarchar(40),
    @NewName     nvarchar(300),
    @Problem     nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;

    /* Copying reads the source and writes a new design, so the source may be Closed —
       that is the whole point of "a closed cycle is never changed, only copied". */
    IF sec.fn_ScreenAccess(@LoginName, N'/Selection/CycleSetup/') < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        RETURN;
    END;

    IF NOT EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleId = @SourceCycleId)
    BEGIN
        SET @Problem = N'That cycle no longer exists, so there is nothing to copy.';
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        RETURN;
    END;

    IF EXISTS (SELECT 1 FROM sel.Cycle WHERE CycleCode = @NewCode)
    BEGIN
        SET @Problem = N'There is already a cycle with the code ' + @NewCode + N'.';
        SELECT TOP (0) CAST(NULL AS int) AS CycleId;
        RETURN;
    END;

    BEGIN TRAN;

    INSERT sel.Cycle (CycleCode, Name, StartDate, EndDate, StatusValueId, OwnerLogin, DelegateLogin,
                      Notes, IncumbentSuffix, SuccessorSuffix, ExistingPoolCode, ActiveMembersOnly,
                      RecipeId, CreatedByLogin)
    SELECT @NewCode, @NewName, NULL, NULL,
           cfg.fn_DomainValueId(N'CYCLE_STATUS', N'DRAFT'),
           @LoginName, DelegateLogin, Notes, IncumbentSuffix, SuccessorSuffix,
           ExistingPoolCode, ActiveMembersOnly, RecipeId, @LoginName
    FROM sel.Cycle WHERE CycleId = @SourceCycleId;

    DECLARE @newId int = SCOPE_IDENTITY();

    INSERT sel.CycleJobSuffix (CycleId, RoleCode, JobSuffix, SuffixDesc)
    SELECT @newId, RoleCode, JobSuffix, SuffixDesc FROM sel.CycleJobSuffix WHERE CycleId = @SourceCycleId;

    /* Criteria, with their sets, keeping the labels and the joins. */
    DECLARE @setMap TABLE (OldId int, NewId int);
    MERGE sel.CycleCriterionSet AS t
    USING (SELECT CriterionSetId, SetLabel, SetModeValueId, SetJoinValueId, SortOrder
           FROM sel.CycleCriterionSet WHERE CycleId = @SourceCycleId) AS s
       ON 1 = 0
    WHEN NOT MATCHED THEN
        INSERT (CycleId, SetLabel, SetModeValueId, SetJoinValueId, SortOrder)
        VALUES (@newId, s.SetLabel, s.SetModeValueId, s.SetJoinValueId, s.SortOrder)
    OUTPUT s.CriterionSetId, inserted.CriterionSetId INTO @setMap (OldId, NewId);

    INSERT sel.CycleCriterion (CriterionSetId, RosterFieldId, OperatorCode, Value1, Value2, SortOrder)
    SELECT m.NewId, c.RosterFieldId, c.OperatorCode, c.Value1, c.Value2, c.SortOrder
    FROM sel.CycleCriterion c
    JOIN @setMap m ON m.OldId = c.CriterionSetId;

    INSERT sel.CycleFramework (CycleId, DevFrameworkId)
    SELECT @newId, DevFrameworkId FROM sel.CycleFramework WHERE CycleId = @SourceCycleId;

    INSERT sel.CycleReadiness (CycleId, LevelCode, Name, ThresholdPct, SortOrder)
    SELECT @newId, LevelCode, Name, ThresholdPct, SortOrder FROM sel.CycleReadiness WHERE CycleId = @SourceCycleId;

    INSERT sel.CycleRequirement (CycleId, DevEventId, LevelCode, Weight, IsMust, SortOrder)
    SELECT @newId, DevEventId, LevelCode, Weight, IsMust, SortOrder FROM sel.CycleRequirement WHERE CycleId = @SourceCycleId;

    /* Processes and their stages, undated: the new design sets its own window. */
    DECLARE @procMap TABLE (OldId int, NewId int);
    MERGE sel.CycleProcess AS t
    USING (SELECT CycleProcessId, ProcessTypeCode, Name, SortOrder
           FROM sel.CycleProcess WHERE CycleId = @SourceCycleId) AS s
       ON 1 = 0
    WHEN NOT MATCHED THEN
        INSERT (CycleId, ProcessTypeCode, Name, StartDate, EndDate, SortOrder)
        VALUES (@newId, s.ProcessTypeCode, s.Name, NULL, NULL, s.SortOrder)
    OUTPUT s.CycleProcessId, inserted.CycleProcessId INTO @procMap (OldId, NewId);

    INSERT sel.CycleStage (CycleProcessId, StageKindCode, Name, StartDate, EndDate, PerformerLevelValueId, SortOrder)
    SELECT m.NewId, s.StageKindCode, s.Name, NULL, NULL, s.PerformerLevelValueId, s.SortOrder
    FROM sel.CycleStage s JOIN @procMap m ON m.OldId = s.CycleProcessId;

    INSERT sel.CycleSkippedStep (CycleId, StepNo, SkippedByLogin)
    SELECT @newId, StepNo, @LoginName FROM sel.CycleSkippedStep WHERE CycleId = @SourceCycleId;

    COMMIT;

    DECLARE @after nvarchar(max) = (SELECT CycleId, CycleCode, Name FROM sel.Cycle WHERE CycleId = @newId
                                    FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);
    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @newId);
    EXEC audit.usp_Log @TableName = N'sel.Cycle', @KeyText = @keyText, @ActionCode = N'COPY',
                       @AfterJson = @after, @LoginName = @LoginName;

    SELECT CycleId = @newId, CycleCode = @NewCode, Name = @NewName,
           CopiedFrom = @SourceCycleId;
END
GO
PRINT '  sel.usp_Cycle_Copy                applied';
GO

PRINT '== 08_pool_and_open complete =========================================';
GO


/* ---- 09_reference_data.sql ------------------------------------------------------- */

/* =====================================================================================
   09_reference_data.sql  —  the seeded configuration
   -------------------------------------------------------------------------------------
   Everything the application would otherwise hardcode.  Each block is a MERGE against a
   literal source, so running this twice changes nothing.

   SemanticRole names a meaning, never a colour: the stylesheet turns 'warning' into
   whatever amber is this year.  The database never carries a hex code.
   ===================================================================================== */
SET NOCOUNT ON;
GO

PRINT '';
PRINT '== 09_reference_data =================================================';
GO

/* ---------------------------------------------------------------------------------
   Domains
   --------------------------------------------------------------------------------- */
MERGE cfg.Domain AS t
USING (VALUES
    (N'CYCLE_STATUS',     N'Cycle status',            N'Where a cycle is in its life.', 1, 10),
    (N'SET_MODE',         N'Condition set mode',      N'How the conditions inside one set combine.', 1, 20),
    (N'SET_JOIN',         N'Condition set join',      N'How a condition set joins the ones before it.', 1, 30),
    (N'CRITERIA_JOIN',    N'Criterion set join',      N'How a criterion set joins the ones before it.', 1, 40),
    (N'DECISION',         N'Decision',                N'Every decision word the log can carry.', 1, 50),
    (N'MANAGEMENT_LEVEL', N'Management level',        N'Who can perform a stage.', 0, 60),
    (N'FRAMEWORK_STATUS', N'Framework status',        N'Draft or active.', 1, 70),
    (N'EVENT_TYPE',       N'Event type',              N'What kind of thing a development event is.', 0, 80),
    (N'PART',             N'Mixture part',            N'Experience, assessment or course.', 0, 90),
    (N'MEASURE',          N'Measure',                 N'How an event is measured.', 0, 100),
    (N'PHASE',            N'Phase',                   N'Before, after, or neither.', 0, 110),
    (N'CANDIDATE_SOURCE', N'Candidate source',        N'How a person came to be in the pool.', 1, 120),
    (N'COVERAGE_TYPE',    N'Coverage type',           N'Acting, secondment or project cover.', 0, 130),
    (N'ITEM_CATEGORY',    N'Item category',           N'How the catalogue is grouped.', 0, 140),
    (N'IDP_STATUS',       N'Plan item status',        N'Where one requirement is in a plan.', 1, 150),
    (N'IDP_SOURCE',       N'Plan item source',        N'What put this requirement in the plan.', 1, 160),
    (N'RATING_BAND',      N'Performance rating band', N'The letters a performance year is reported as.', 0, 170),
    (N'JOB_SUFFIX_ROLE',  N'Job suffix role',         N'Incumbent or successor.', 1, 180)
) AS s (DomainCode, Name, Description, IsSystem, SortOrder)
   ON t.DomainCode = s.DomainCode
WHEN MATCHED THEN UPDATE SET Name = s.Name, Description = s.Description,
                             IsSystem = s.IsSystem, SortOrder = s.SortOrder
WHEN NOT MATCHED BY TARGET THEN
    INSERT (DomainCode, Name, Description, IsSystem, SortOrder)
    VALUES (s.DomainCode, s.Name, s.Description, s.IsSystem, s.SortOrder);
PRINT '  cfg.Domain                        seeded';
GO

