/* =====================================================================================
   sel.usp_Idp_Suggest — the one-click plan
   -------------------------------------------------------------------------------------
   Books every open requirement onto the EARLIEST session with a free seat that falls
   inside the target date; leaves a pencilled date where no session exists; and NEVER
   assigns coverage, because coverage costs leave and is a human decision.
   It returns what it did as a list of sentences.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Idp_Suggest
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @PersonnelNo  nvarchar(30) = NULL,   -- NULL means every remaining plan
    @AsOf         date = NULL,
    @TestMode     bit = 0,
    @Problem      nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cycleId int, @screenCode nvarchar(160);
    SELECT @cycleId = p.CycleId, @screenCode = sk.ScreenCode
    FROM sel.CycleStage s
    JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
    JOIN sel.StageKind sk ON sk.StageKindCode = s.StageKindCode
    WHERE s.CycleStageId = @CycleStageId;

    IF @cycleId IS NULL OR sec.fn_IsReadOnlyUser(@LoginName) = 1
       OR sec.fn_ScreenAccess(@LoginName, @screenCode) < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS nvarchar(600)) AS Sentence; RETURN;
    END;
    IF sel.fn_StageState(@CycleStageId, @AsOf, @TestMode) <> N'OPEN'
    BEGIN
        SET @Problem = N'This stage is not open, so nothing can be planned.';
        SELECT TOP (0) CAST(NULL AS nvarchar(600)) AS Sentence; RETURN;
    END;

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    INSERT #scope
    SELECT cc.PersonnelNo FROM sel.CycleCandidate cc
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    WHERE cc.CycleId = @cycleId AND (@PersonnelNo IS NULL OR cc.PersonnelNo = @PersonnelNo);

    CREATE TABLE #obl
    (
        PersonnelNo nvarchar(30) NOT NULL, DevEventId int NOT NULL, ItemCode nvarchar(60) NOT NULL,
        EventCode nvarchar(60) NULL, EventName nvarchar(300) NULL, KindCode nvarchar(30) NULL,
        IsMust int NOT NULL, IsMet int NOT NULL, Why nvarchar(600) NULL,
        Sources nvarchar(400) NULL, LevelNo int NULL
    );
    EXEC sel.usp_Idp_OpenRequirements_Into @CycleId = @cycleId, @AsOf = @AsOf;

    /* What still needs planning, with each person's target date. */
    CREATE TABLE #todo
    (
        PersonnelNo nvarchar(30) NOT NULL, DevEventId int NOT NULL,
        EventCode nvarchar(60) NULL, EventName nvarchar(300) NULL, KindCode nvarchar(30) NULL,
        TargetDate date NULL, OrgCode nvarchar(40) NULL,
        PRIMARY KEY (PersonnelNo, DevEventId)
    );
    INSERT #todo (PersonnelNo, DevEventId, EventCode, EventName, KindCode, TargetDate, OrgCode)
    SELECT o.PersonnelNo, o.DevEventId, o.EventCode, o.EventName, o.KindCode,
           sel.fn_IdpTargetDate(@cycleId, o.PersonnelNo, @CycleStageId),
           (SELECT OrgCode FROM sel.CycleCandidate cc WHERE cc.CycleId = @cycleId AND cc.PersonnelNo = o.PersonnelNo)
    FROM #obl o
    WHERE o.IsMet = 0
      AND NOT EXISTS (SELECT 1 FROM sel.IdpItem i
                      WHERE i.CycleId = @cycleId AND i.PersonnelNo = o.PersonnelNo
                        AND i.DevEventId = o.DevEventId
                        AND (i.DevSessionId IS NOT NULL OR i.PencilledDate IS NOT NULL))
      AND NOT EXISTS (SELECT 1 FROM sel.IdpCoverage cv
                      WHERE cv.CycleId = @cycleId AND cv.PersonnelNo = o.PersonnelNo
                        AND cv.DevEventId = o.DevEventId AND cv.Days > 0);

    CREATE TABLE #did (Sentence nvarchar(600) NOT NULL, SortOrder int NOT NULL IDENTITY(1,1));

    /* Seat counts are consumed as we go, so a large cohort cannot over-book a session.
       This walks the to-do list one row at a time on purpose: a set-based booking would
       hand the same last seat to several people at once. */
    DECLARE @person nvarchar(30), @event int, @eventName nvarchar(300), @target date,
            @org nvarchar(40), @kind nvarchar(30);
    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT PersonnelNo, DevEventId, EventName, TargetDate, OrgCode, KindCode
        FROM #todo ORDER BY TargetDate, PersonnelNo, DevEventId;

    OPEN cur; FETCH NEXT FROM cur INTO @person, @event, @eventName, @target, @org, @kind;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        /* Coverage is never auto-assigned.  A summed obligation is left for a human. */
        IF (SELECT EvalModeCode FROM sel.RequirementKind WHERE KindCode = @kind) = N'SUM'
        BEGIN
            INSERT #did (Sentence)
            VALUES (N'Left "' + @eventName + N'" for ' + @person
                  + N' — ' + cfg.fn_Message(N'IDP_COVERAGE_MANUAL'));
        END
        ELSE
        BEGIN
            /* The earliest session with a free seat that falls inside the target date. */
            DECLARE @sessionId int = NULL, @sessionCode nvarchar(60), @start date;
            SELECT TOP (1) @sessionId = ds.DevSessionId, @sessionCode = ds.SessionCode, @start = ds.StartDate
            FROM sel.DevSession ds
            WHERE ds.DevEventId = @event AND ds.IsCancelled = 0
              AND (ds.Seats IS NULL
                   OR ds.Seats > (SELECT COUNT(*) FROM sel.IdpItem i WHERE i.DevSessionId = ds.DevSessionId))
              AND (@target IS NULL OR ds.StartDate IS NULL OR ds.StartDate <= @target)
              AND (ds.StartDate IS NULL OR ds.StartDate >= @AsOf)
            ORDER BY ISNULL(ds.StartDate, '9999-12-31'), ds.DevSessionId;

            IF @sessionId IS NOT NULL
            BEGIN
                MERGE sel.IdpItem AS t
                USING (SELECT @person AS PersonnelNo) AS s
                   ON t.CycleId = @cycleId AND t.PersonnelNo = s.PersonnelNo AND t.DevEventId = @event
                WHEN MATCHED THEN
                    UPDATE SET DevSessionId = @sessionId, PencilledDate = NULL,
                               StatusValueId = cfg.fn_DomainValueId(N'IDP_STATUS', N'BOOKED'),
                               ActorLogin = @LoginName, ChangedOnUtc = SYSUTCDATETIME()
                WHEN NOT MATCHED BY TARGET THEN
                    INSERT (CycleId, PersonnelNo, DevEventId, DevSessionId, StatusValueId, SourceValueId, OrgCode, ActorLogin)
                    VALUES (@cycleId, @person, @event, @sessionId,
                            cfg.fn_DomainValueId(N'IDP_STATUS', N'BOOKED'),
                            cfg.fn_DomainValueId(N'IDP_SOURCE', N'LEVEL'), @org, @LoginName);

                INSERT #did (Sentence)
                VALUES (N'Booked ' + @person + N' onto ' + @sessionCode + N' for "' + @eventName + N'"'
                      + ISNULL(N' on ' + CONVERT(nvarchar(10), @start, 23), N''));
            END
            ELSE
            BEGIN
                /* No session exists, so leave a pencilled date on the target. */
                DECLARE @pencil date = ISNULL(@target, DATEADD(MONTH, 6, @AsOf));
                MERGE sel.IdpItem AS t
                USING (SELECT @person AS PersonnelNo) AS s
                   ON t.CycleId = @cycleId AND t.PersonnelNo = s.PersonnelNo AND t.DevEventId = @event
                WHEN MATCHED THEN
                    UPDATE SET DevSessionId = NULL, PencilledDate = @pencil,
                               StatusValueId = cfg.fn_DomainValueId(N'IDP_STATUS', N'PENCILLED'),
                               ActorLogin = @LoginName, ChangedOnUtc = SYSUTCDATETIME()
                WHEN NOT MATCHED BY TARGET THEN
                    INSERT (CycleId, PersonnelNo, DevEventId, PencilledDate, StatusValueId, SourceValueId, OrgCode, ActorLogin)
                    VALUES (@cycleId, @person, @event, @pencil,
                            cfg.fn_DomainValueId(N'IDP_STATUS', N'PENCILLED'),
                            cfg.fn_DomainValueId(N'IDP_SOURCE', N'LEVEL'), @org, @LoginName);

                INSERT #did (Sentence)
                VALUES (N'Pencilled ' + @person + N' in for "' + @eventName + N'" on '
                      + CONVERT(nvarchar(10), @pencil, 23) + N' — no session is scheduled.');
            END;
        END;

        FETCH NEXT FROM cur INTO @person, @event, @eventName, @target, @org, @kind;
    END;
    CLOSE cur; DEALLOCATE cur;

    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @cycleId) + N'/' + ISNULL(@PersonnelNo, N'cohort');
    EXEC audit.usp_Log @TableName = N'sel.IdpItem', @KeyText = @keyText, @ActionCode = N'SUGGEST',
                       @LoginName = @LoginName;

    /* What it did, as a list of sentences. */
    SELECT Sentence, SortOrder FROM #did ORDER BY SortOrder;
    SELECT Changed = (SELECT COUNT(*) FROM #did);

    DROP TABLE #did; DROP TABLE #todo; DROP TABLE #obl; DROP TABLE #scope;
END
GO
PRINT '  sel.usp_Idp_Suggest               applied';
GO

/* =====================================================================================
   Coverage — an acting assignment.  The day count is computed here, and the person's
   remaining coverage balance is deducted and persisted.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Idp_Coverage_Add
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @PersonnelNo  nvarchar(30),
    @DevEventId   int = NULL,
    @Department   nvarchar(200) = NULL,
    @PositionCode nvarchar(60) = NULL,
    @IncumbentPersonnelNo nvarchar(30) = NULL,
    @StartDate    date,
    @EndDate      date,
    @AsOf         date = NULL,
    @TestMode     bit = 0,
    @Problem      nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cycleId int, @screenCode nvarchar(160);
    SELECT @cycleId = p.CycleId, @screenCode = sk.ScreenCode
    FROM sel.CycleStage s
    JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
    JOIN sel.StageKind sk ON sk.StageKindCode = s.StageKindCode
    WHERE s.CycleStageId = @CycleStageId;

    IF @cycleId IS NULL OR sec.fn_IsReadOnlyUser(@LoginName) = 1
       OR sec.fn_ScreenAccess(@LoginName, @screenCode) < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpCoverageId; RETURN;
    END;
    IF sel.fn_StageState(@CycleStageId, @AsOf, @TestMode) <> N'OPEN'
    BEGIN
        SET @Problem = N'This stage is not open, so coverage cannot be assigned.';
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpCoverageId; RETURN;
    END;
    IF @StartDate IS NULL OR @EndDate IS NULL OR @EndDate < @StartDate
    BEGIN
        SET @Problem = N'Coverage needs a start and an end date, and it cannot end before it starts.';
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpCoverageId; RETURN;
    END;

    DECLARE @org nvarchar(40) = (SELECT OrgCode FROM sel.CycleCandidate
                                 WHERE CycleId = @cycleId AND PersonnelNo = @PersonnelNo);
    IF @org IS NULL OR NOT EXISTS (SELECT 1 FROM sec.fn_UserOrgScope(@LoginName) sc WHERE sc.OrgCode = @org)
    BEGIN
        SET @Problem = N'This person is not in this cycle''s cohort, or not in an organisation you have been granted.';
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpCoverageId; RETURN;
    END;

    /* The day count is computed in SQL, inclusive of both ends. */
    DECLARE @days int = DATEDIFF(DAY, @StartDate, @EndDate) + 1;

    BEGIN TRAN;
    INSERT sel.IdpCoverage (CycleId, PersonnelNo, DevEventId, Department, PositionCode,
                            IncumbentPersonnelNo, StartDate, EndDate, Days, OrgCode, ActorLogin)
    VALUES (@cycleId, @PersonnelNo, @DevEventId, @Department, @PositionCode,
            @IncumbentPersonnelNo, @StartDate, @EndDate, @days, @org, @LoginName);
    DECLARE @id bigint = SCOPE_IDENTITY();

    /* The balance is deducted and persisted, so it survives the request. */
    MERGE sel.EmployeeMetric AS t
    USING (SELECT @PersonnelNo AS PersonnelNo) AS s
       ON t.PersonnelNo = s.PersonnelNo AND t.MetricKey = N'CoverageDaysPlanned'
    WHEN MATCHED THEN UPDATE SET NumValue = ISNULL(t.NumValue, 0) + @days, RefreshedUtc = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (PersonnelNo, MetricKey, NumValue, AsOfDate) VALUES (s.PersonnelNo, N'CoverageDaysPlanned', @days, @AsOf);
    COMMIT;

    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @id);
    EXEC audit.usp_Log @TableName = N'sel.IdpCoverage', @KeyText = @keyText, @ActionCode = N'ADD',
                       @LoginName = @LoginName;

    SELECT IdpCoverageId = @id, PersonnelNo = @PersonnelNo, Days = @days,
           StartDate = @StartDate, EndDate = @EndDate,
           BalanceDays = (SELECT NumValue FROM sel.EmployeeMetric
                          WHERE PersonnelNo = @PersonnelNo AND MetricKey = N'CoverageDaysPlanned');
END
GO
PRINT '  sel.usp_Idp_Coverage_Add          applied';
GO

CREATE OR ALTER PROCEDURE sel.usp_Idp_Coverage_Remove
    @LoginName     nvarchar(128),
    @IdpCoverageId bigint,
    @Problem       nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;

    DECLARE @cycleId int, @person nvarchar(30), @days int;
    SELECT @cycleId = CycleId, @person = PersonnelNo, @days = Days
    FROM sel.IdpCoverage WHERE IdpCoverageId = @IdpCoverageId;

    IF @cycleId IS NULL
    BEGIN
        SET @Problem = N'That coverage assignment no longer exists.';
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpCoverageId; RETURN;
    END;
    IF sec.fn_IsReadOnlyUser(@LoginName) = 1
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpCoverageId; RETURN;
    END;
    IF sel.fn_CycleStatusCode(@cycleId) = N'CLOSED'
    BEGIN
        SET @Problem = cfg.fn_Message(N'CLOSED_CYCLE');
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpCoverageId; RETURN;
    END;

    BEGIN TRAN;
    DELETE FROM sel.IdpCoverage WHERE IdpCoverageId = @IdpCoverageId;
    /* Give the days back. */
    UPDATE sel.EmployeeMetric SET NumValue = ISNULL(NumValue, 0) - @days, RefreshedUtc = SYSUTCDATETIME()
    WHERE PersonnelNo = @person AND MetricKey = N'CoverageDaysPlanned';
    COMMIT;

    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @IdpCoverageId);
    EXEC audit.usp_Log @TableName = N'sel.IdpCoverage', @KeyText = @keyText, @ActionCode = N'REMOVE',
                       @LoginName = @LoginName;

    SELECT IdpCoverageId = @IdpCoverageId, Removed = CAST(1 AS bit), DaysReturned = @days;
END
GO
PRINT '  sel.usp_Idp_Coverage_Remove       applied';
GO

/* sel.usp_Idp_Coverage_Board — the Coverage tab: the incumbent's demand and the
   successors available.                                                              */
CREATE OR ALTER PROCEDURE sel.usp_Idp_Coverage_Board
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @Search       nvarchar(200) = NULL,
    @AsOf         date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cycleId int = (SELECT p.CycleId FROM sel.CycleStage s
                            JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                            WHERE s.CycleStageId = @CycleStageId);

    /* The assignments already made. */
    SELECT cv.IdpCoverageId, cv.PersonnelNo, e.FullName, cv.Department, cv.PositionCode,
           cv.IncumbentPersonnelNo, cv.StartDate, cv.EndDate, cv.Days, cv.ActorLogin, cv.AddedOnUtc,
           IncumbentName = (SELECT FullName FROM sel.Employee ie WHERE ie.PersonnelNo = cv.IncumbentPersonnelNo),
           EventName = (SELECT Name FROM sel.DevEvent de WHERE de.DevEventId = cv.DevEventId),
           OrgName = o.Name
    FROM sel.IdpCoverage cv
    JOIN sel.Employee e ON e.PersonnelNo = cv.PersonnelNo
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cv.OrgCode
    LEFT JOIN sel.OrgNode o ON o.OrgCode = cv.OrgCode
    WHERE cv.CycleId = @cycleId
      AND (@Search IS NULL OR e.FullName LIKE N'%' + @Search + N'%' OR cv.Department LIKE N'%' + @Search + N'%')
    ORDER BY cv.StartDate, e.FullName;

    /* The successors available: people in the cohort with a summed obligation still open. */
    SELECT e.PersonnelNo, e.FullName, e.OrgCode, o.Name AS OrgName, e.JobTitle,
           DaysPlanned = ISNULL((SELECT SUM(cv.Days) FROM sel.IdpCoverage cv
                                 WHERE cv.CycleId = @cycleId AND cv.PersonnelNo = e.PersonnelNo), 0),
           DaysRecorded = ISNULL((SELECT NumValue FROM sel.EmployeeMetric m
                                  WHERE m.PersonnelNo = e.PersonnelNo AND m.MetricKey = N'DaysCovered'), 0)
    FROM sel.CycleCandidate cc
    JOIN sel.Employee e ON e.PersonnelNo = cc.PersonnelNo
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    LEFT JOIN sel.OrgNode o ON o.OrgCode = cc.OrgCode
    WHERE cc.CycleId = @cycleId
      AND (@Search IS NULL OR e.FullName LIKE N'%' + @Search + N'%')
    ORDER BY e.FullName;
END
GO
PRINT '  sel.usp_Idp_Coverage_Board        applied';
GO

/* sel.usp_Idp_Conflicts — overlapping bookings, coverage overlapping a booking, and a
   person covering an incumbent on days they are booked away.                          */
CREATE OR ALTER PROCEDURE sel.usp_Idp_Conflicts
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @PersonnelNo  nvarchar(30) = NULL,
    @AsOf         date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @cycleId int = (SELECT p.CycleId FROM sel.CycleStage s
                            JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                            WHERE s.CycleStageId = @CycleStageId);

    /* 1 — two bookings whose sessions overlap. */
    SELECT ConflictKind = N'BOOKING_OVERLAP',
           a.PersonnelNo, e.FullName,
           FirstWhat = ea.Name, FirstFrom = sa.StartDate, FirstTo = sa.EndDate,
           SecondWhat = eb.Name, SecondFrom = sb.StartDate, SecondTo = sb.EndDate,
           Sentence = e.FullName + N' is booked on "' + ea.Name + N'" and "' + eb.Name
                    + N'" over the same days.'
    FROM sel.IdpItem a
    JOIN sel.IdpItem b ON b.CycleId = a.CycleId AND b.PersonnelNo = a.PersonnelNo AND b.IdpItemId > a.IdpItemId
    JOIN sel.DevSession sa ON sa.DevSessionId = a.DevSessionId
    JOIN sel.DevSession sb ON sb.DevSessionId = b.DevSessionId
    JOIN sel.DevEvent ea ON ea.DevEventId = a.DevEventId
    JOIN sel.DevEvent eb ON eb.DevEventId = b.DevEventId
    JOIN sel.Employee e ON e.PersonnelNo = a.PersonnelNo
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = a.OrgCode
    WHERE a.CycleId = @cycleId
      AND (@PersonnelNo IS NULL OR a.PersonnelNo = @PersonnelNo)
      AND sa.StartDate IS NOT NULL AND sb.StartDate IS NOT NULL
      AND sa.StartDate <= ISNULL(sb.EndDate, sb.StartDate)
      AND sb.StartDate <= ISNULL(sa.EndDate, sa.StartDate)

    UNION ALL

    /* 2 — coverage overlapping a booking: they are away on days they are covering. */
    SELECT N'COVERAGE_OVERLAPS_BOOKING',
           cv.PersonnelNo, e.FullName,
           N'Covering ' + ISNULL(cv.Department, N'a department'), cv.StartDate, cv.EndDate,
           ev.Name, ds.StartDate, ds.EndDate,
           e.FullName + N' is covering ' + ISNULL(cv.Department, N'a department')
             + N' on days they are booked onto "' + ev.Name + N'".'
    FROM sel.IdpCoverage cv
    JOIN sel.IdpItem i ON i.CycleId = cv.CycleId AND i.PersonnelNo = cv.PersonnelNo
    JOIN sel.DevSession ds ON ds.DevSessionId = i.DevSessionId
    JOIN sel.DevEvent ev ON ev.DevEventId = i.DevEventId
    JOIN sel.Employee e ON e.PersonnelNo = cv.PersonnelNo
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cv.OrgCode
    WHERE cv.CycleId = @cycleId
      AND (@PersonnelNo IS NULL OR cv.PersonnelNo = @PersonnelNo)
      AND ds.StartDate IS NOT NULL
      AND cv.StartDate <= ISNULL(ds.EndDate, ds.StartDate)
      AND ds.StartDate <= cv.EndDate

    UNION ALL

    /* 3 — two coverage spells over the same days. */
    SELECT N'COVERAGE_OVERLAP',
           a.PersonnelNo, e.FullName,
           ISNULL(a.Department, N'a department'), a.StartDate, a.EndDate,
           ISNULL(b.Department, N'a department'), b.StartDate, b.EndDate,
           e.FullName + N' is assigned to cover two places over the same days.'
    FROM sel.IdpCoverage a
    JOIN sel.IdpCoverage b ON b.CycleId = a.CycleId AND b.PersonnelNo = a.PersonnelNo
                          AND b.IdpCoverageId > a.IdpCoverageId
    JOIN sel.Employee e ON e.PersonnelNo = a.PersonnelNo
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = a.OrgCode
    WHERE a.CycleId = @cycleId
      AND (@PersonnelNo IS NULL OR a.PersonnelNo = @PersonnelNo)
      AND a.StartDate <= b.EndDate AND b.StartDate <= a.EndDate
    ORDER BY 2, 1;
END
GO
PRINT '  sel.usp_Idp_Conflicts             applied';
GO

/* sel.usp_Idp_Target_Save / sel.usp_Idp_Note_Add */
CREATE OR ALTER PROCEDURE sel.usp_Idp_Target_Save
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @PersonnelNo  nvarchar(30),
    @TargetDate   date = NULL,        -- NULL clears the override and goes back to derived
    @Problem      nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Problem = NULL;
    DECLARE @cycleId int = (SELECT p.CycleId FROM sel.CycleStage s
                            JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                            WHERE s.CycleStageId = @CycleStageId);
    IF @cycleId IS NULL OR sec.fn_IsReadOnlyUser(@LoginName) = 1
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS date) AS TargetDate; RETURN;
    END;

    MERGE sel.IdpTarget AS t
    USING (SELECT @cycleId AS CycleId, @PersonnelNo AS PersonnelNo) AS s
       ON t.CycleId = s.CycleId AND t.PersonnelNo = s.PersonnelNo
    WHEN MATCHED THEN UPDATE SET TargetDate = @TargetDate, SetByLogin = @LoginName, SetOnUtc = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (CycleId, PersonnelNo, TargetDate, SetByLogin)
        VALUES (s.CycleId, s.PersonnelNo, @TargetDate, @LoginName);

    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @cycleId) + N'/' + @PersonnelNo;
    EXEC audit.usp_Log @TableName = N'sel.IdpTarget', @KeyText = @keyText, @ActionCode = N'SAVE',
                       @LoginName = @LoginName;

    SELECT TargetDate = sel.fn_IdpTargetDate(@cycleId, @PersonnelNo, @CycleStageId),
           IsOverridden = CONVERT(bit, CASE WHEN @TargetDate IS NULL THEN 0 ELSE 1 END);
END
GO
PRINT '  sel.usp_Idp_Target_Save           applied';
GO

CREATE OR ALTER PROCEDURE sel.usp_Idp_Note_Add
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @PersonnelNo  nvarchar(30),
    @NoteText     nvarchar(max),
    @Problem      nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Problem = NULL;
    DECLARE @cycleId int = (SELECT p.CycleId FROM sel.CycleStage s
                            JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                            WHERE s.CycleStageId = @CycleStageId);
    IF @cycleId IS NULL OR sec.fn_IsReadOnlyUser(@LoginName) = 1
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpNoteId; RETURN;
    END;
    IF NULLIF(LTRIM(RTRIM(ISNULL(@NoteText, N''))), N'') IS NULL
    BEGIN
        SET @Problem = N'An empty note is not worth keeping.';
        SELECT TOP (0) CAST(NULL AS bigint) AS IdpNoteId; RETURN;
    END;

    INSERT sel.IdpNote (CycleId, PersonnelNo, NoteText, ActorLogin)
    VALUES (@cycleId, @PersonnelNo, @NoteText, @LoginName);

    SELECT IdpNoteId = SCOPE_IDENTITY(), NoteText = @NoteText, ActorLogin = @LoginName;
END
GO
PRINT '  sel.usp_Idp_Note_Add              applied';
GO

/* =====================================================================================
   Approval — at plan level, never per requirement
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Idp_ApproveMany
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @People       dbo.IdList READONLY,
    @AsOf         date = NULL,
    @TestMode     bit = 0,
    @Problem      nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cycleId int, @processId int, @screenCode nvarchar(160), @performerId int;
    SELECT @cycleId = p.CycleId, @processId = s.CycleProcessId, @screenCode = sk.ScreenCode,
           @performerId = s.PerformerLevelValueId
    FROM sel.CycleStage s
    JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
    JOIN sel.StageKind sk ON sk.StageKindCode = s.StageKindCode
    WHERE s.CycleStageId = @CycleStageId;

    IF @cycleId IS NULL OR sec.fn_IsReadOnlyUser(@LoginName) = 1
       OR sec.fn_ScreenAccess(@LoginName, @screenCode) < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS nvarchar(30)) AS PersonnelNo; RETURN;
    END;
    IF sel.fn_StageState(@CycleStageId, @AsOf, @TestMode) <> N'OPEN'
    BEGIN
        SET @Problem = N'This stage is not open, so nothing can be approved.';
        SELECT TOP (0) CAST(NULL AS nvarchar(30)) AS PersonnelNo; RETURN;
    END;

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    INSERT #scope
    SELECT cc.PersonnelNo FROM @People p
    JOIN sel.CycleCandidate cc ON cc.CycleId = @cycleId AND cc.PersonnelNo = p.Id
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode;

    CREATE TABLE #obl
    (
        PersonnelNo nvarchar(30) NOT NULL, DevEventId int NOT NULL, ItemCode nvarchar(60) NOT NULL,
        EventCode nvarchar(60) NULL, EventName nvarchar(300) NULL, KindCode nvarchar(30) NULL,
        IsMust int NOT NULL, IsMet int NOT NULL, Why nvarchar(600) NULL,
        Sources nvarchar(400) NULL, LevelNo int NULL
    );
    EXEC sel.usp_Idp_OpenRequirements_Into @CycleId = @cycleId, @AsOf = @AsOf;

    /* Refuses unless every open requirement has a booking, a date, or coverage days. */
    CREATE TABLE #notready (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY, Outstanding int NOT NULL);
    INSERT #notready (PersonnelNo, Outstanding)
    SELECT s.PersonnelNo,
           (SELECT COUNT(*) FROM #obl o
            WHERE o.PersonnelNo = s.PersonnelNo AND o.IsMet = 0
              AND NOT EXISTS (SELECT 1 FROM sel.IdpItem i
                              WHERE i.CycleId = @cycleId AND i.PersonnelNo = o.PersonnelNo
                                AND i.DevEventId = o.DevEventId
                                AND (i.DevSessionId IS NOT NULL OR i.PencilledDate IS NOT NULL))
              AND NOT EXISTS (SELECT 1 FROM sel.IdpCoverage cv
                              WHERE cv.CycleId = @cycleId AND cv.PersonnelNo = o.PersonnelNo
                                AND cv.DevEventId = o.DevEventId AND cv.Days > 0))
    FROM #scope s;

    DELETE FROM #scope WHERE PersonnelNo IN (SELECT PersonnelNo FROM #notready WHERE Outstanding > 0);

    DECLARE @blocked int = (SELECT COUNT(*) FROM #notready WHERE Outstanding > 0);
    DECLARE @ready int = (SELECT COUNT(*) FROM #scope);

    IF @ready = 0
    BEGIN
        SET @Problem = cfg.fn_Message(N'IDP_NOT_READY');
        SELECT TOP (0) CAST(NULL AS nvarchar(30)) AS PersonnelNo;
        DROP TABLE #notready; DROP TABLE #obl; DROP TABLE #scope; RETURN;
    END;

    BEGIN TRAN;
    MERGE sel.IdpApproval AS t
    USING (SELECT s.PersonnelNo, cc.OrgCode FROM #scope s
           JOIN sel.CycleCandidate cc ON cc.CycleId = @cycleId AND cc.PersonnelNo = s.PersonnelNo) AS src
       ON t.CycleId = @cycleId AND t.PersonnelNo = src.PersonnelNo
    WHEN MATCHED THEN UPDATE SET ApprovedByLogin = @LoginName, ApprovedOnUtc = SYSUTCDATETIME(),
                                 NotifiedOnUtc = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (CycleId, PersonnelNo, ApprovedByLogin, NotifiedOnUtc, OrgCode)
        VALUES (@cycleId, src.PersonnelNo, @LoginName, SYSUTCDATETIME(), src.OrgCode);

    /* Approval is a decision, and lands in the decision log like every other one. */
    INSERT sel.CandidateDecision (CycleId, CycleProcessId, CycleStageId, PersonnelNo,
                                  DecisionValueId, Reason, PerformerLevelValueId, ActorLogin, IsTest, OrgCode)
    SELECT @cycleId, @processId, @CycleStageId, s.PersonnelNo,
           cfg.fn_DomainValueId(N'DECISION', N'PLAN_APPROVED'),
           N'Development plan approved and notified',
           @performerId, @LoginName, @TestMode, cc.OrgCode
    FROM #scope s
    JOIN sel.CycleCandidate cc ON cc.CycleId = @cycleId AND cc.PersonnelNo = s.PersonnelNo;
    COMMIT;

    DECLARE @keyText nvarchar(200) = CONVERT(nvarchar(20), @cycleId) + N'/' + CONVERT(nvarchar(10), @ready) + N' plans';
    EXEC audit.usp_Log @TableName = N'sel.IdpApproval', @KeyText = @keyText, @ActionCode = N'APPROVE',
                       @LoginName = @LoginName;

    /* A partial success says so, rather than claiming everything landed. */
    IF @blocked > 0
        SET @Problem = CONVERT(nvarchar(10), @ready) + N' plan' + CASE WHEN @ready = 1 THEN N' was' ELSE N's were' END
                     + N' approved. ' + CONVERT(nvarchar(10), @blocked) + N' still ha'
                     + CASE WHEN @blocked = 1 THEN N's' ELSE N've' END
                     + N' requirements with no booking, date or coverage days.';

    SELECT s.PersonnelNo, e.FullName, ApprovedOnUtc = SYSUTCDATETIME(), ApprovedByLogin = @LoginName
    FROM #scope s JOIN sel.Employee e ON e.PersonnelNo = s.PersonnelNo;

    DROP TABLE #notready; DROP TABLE #obl; DROP TABLE #scope;
END
GO
PRINT '  sel.usp_Idp_ApproveMany           applied';
GO

CREATE OR ALTER PROCEDURE sel.usp_Idp_Approve
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @PersonnelNo  nvarchar(30),
    @AsOf         date = NULL,
    @TestMode     bit = 0,
    @Problem      nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @one dbo.IdList;
    INSERT @one (Id) VALUES (@PersonnelNo);
    EXEC sel.usp_Idp_ApproveMany @LoginName = @LoginName, @CycleStageId = @CycleStageId,
         @People = @one, @AsOf = @AsOf, @TestMode = @TestMode, @Problem = @Problem OUTPUT;
END
GO
PRINT '  sel.usp_Idp_Approve               applied';
GO

/* sel.usp_Idp_Risk — demand against supply per organisation: days owed against
   successors available, banded.                                                       */
CREATE OR ALTER PROCEDURE sel.usp_Idp_Risk
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @AsOf         date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cycleId int = (SELECT p.CycleId FROM sel.CycleStage s
                            JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                            WHERE s.CycleStageId = @CycleStageId);

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    INSERT #scope
    SELECT cc.PersonnelNo FROM sel.CycleCandidate cc
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    WHERE cc.CycleId = @cycleId;

    CREATE TABLE #obl
    (
        PersonnelNo nvarchar(30) NOT NULL, DevEventId int NOT NULL, ItemCode nvarchar(60) NOT NULL,
        EventCode nvarchar(60) NULL, EventName nvarchar(300) NULL, KindCode nvarchar(30) NULL,
        IsMust int NOT NULL, IsMet int NOT NULL, Why nvarchar(600) NULL,
        Sources nvarchar(400) NULL, LevelNo int NULL
    );
    EXEC sel.usp_Idp_OpenRequirements_Into @CycleId = @cycleId, @AsOf = @AsOf;

    /* What is already assigned, per person and requirement.  It is aggregated here
       rather than inside the sum below: SQL Server will not aggregate an expression that
       contains a subquery, and folding it in first is also one pass instead of one per
       row. */
    ;WITH assigned AS
    (
        SELECT cv.PersonnelNo, cv.DevEventId, DaysAssigned = SUM(cv.Days)
        FROM sel.IdpCoverage cv
        WHERE cv.CycleId = @cycleId
        GROUP BY cv.PersonnelNo, cv.DevEventId
    ),
    shortfall AS
    (
        SELECT e.OrgCode, o.PersonnelNo, IsSummed = k.EvalModeCode,
               /* Days owed: this requirement's floor, less what is already assigned,
                  and never less than nothing. */
               DaysOwed = CASE WHEN k.EvalModeCode = N'SUM'
                               THEN CASE WHEN ISNULL(ev.SumFloor, 0) - ISNULL(a.DaysAssigned, 0) > 0
                                         THEN ISNULL(ev.SumFloor, 0) - ISNULL(a.DaysAssigned, 0)
                                         ELSE 0 END
                               ELSE 0 END
        FROM #obl o
        JOIN sel.DevEvent ev ON ev.DevEventId = o.DevEventId
        JOIN sel.RequirementKind k ON k.KindCode = ev.KindCode
        JOIN sel.Employee e ON e.PersonnelNo = o.PersonnelNo
        LEFT JOIN assigned a ON a.PersonnelNo = o.PersonnelNo AND a.DevEventId = o.DevEventId
        WHERE o.IsMet = 0
    ),
    owed AS
    (
        SELECT OrgCode,
               DaysOwed = SUM(DaysOwed),
               PeopleOwing = COUNT(DISTINCT CASE WHEN IsSummed = N'SUM' THEN PersonnelNo END)
        FROM shortfall
        GROUP BY OrgCode
    )
    SELECT w.OrgCode, o.Name AS OrgName,
           DaysOwed = CAST(w.DaysOwed AS int),
           w.PeopleOwing,
           SuccessorsAvailable = (SELECT COUNT(*) FROM sel.CycleCandidate cc
                                  JOIN sel.Employee e2 ON e2.PersonnelNo = cc.PersonnelNo
                                  WHERE cc.CycleId = @cycleId AND e2.OrgCode = w.OrgCode),
           /* Banded: Nothing outstanding / 1-120 / 121-360 / over 360. */
           Band = CASE WHEN w.DaysOwed <= 0  THEN N'Nothing outstanding'
                       WHEN w.DaysOwed <= 120 THEN N'1–120 days'
                       WHEN w.DaysOwed <= 360 THEN N'121–360 days'
                       ELSE N'Over 360 days' END,
           BandRole = CASE WHEN w.DaysOwed <= 0  THEN N'positive'
                           WHEN w.DaysOwed <= 120 THEN N'neutral'
                           WHEN w.DaysOwed <= 360 THEN N'warning'
                           ELSE N'danger' END
    FROM owed w
    LEFT JOIN sel.OrgNode o ON o.OrgCode = w.OrgCode
    ORDER BY w.DaysOwed DESC;

    DROP TABLE #obl; DROP TABLE #scope;
END
GO
PRINT '  sel.usp_Idp_Risk                  applied';
GO

/* sel.usp_Idp_Export — the cohort's plans as one flat result set for CSV and XLSX.
   It streams from the same procedure the screen reads, with paging off, so an export
   can never disagree with what was on screen.                                         */
CREATE OR ALTER PROCEDURE sel.usp_Idp_Export
    @LoginName    nvarchar(128),
    @CycleStageId int,
    @AsOf         date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    DECLARE @cycleId int = (SELECT p.CycleId FROM sel.CycleStage s
                            JOIN sel.CycleProcess p ON p.CycleProcessId = s.CycleProcessId
                            WHERE s.CycleStageId = @CycleStageId);

    CREATE TABLE #scope (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY);
    INSERT #scope
    SELECT cc.PersonnelNo FROM sel.CycleCandidate cc
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    WHERE cc.CycleId = @cycleId;

    CREATE TABLE #obl
    (
        PersonnelNo nvarchar(30) NOT NULL, DevEventId int NOT NULL, ItemCode nvarchar(60) NOT NULL,
        EventCode nvarchar(60) NULL, EventName nvarchar(300) NULL, KindCode nvarchar(30) NULL,
        IsMust int NOT NULL, IsMet int NOT NULL, Why nvarchar(600) NULL,
        Sources nvarchar(400) NULL, LevelNo int NULL
    );
    EXEC sel.usp_Idp_OpenRequirements_Into @CycleId = @cycleId, @AsOf = @AsOf;

    SELECT [Personnel No] = ob.PersonnelNo,
           [Name] = e.FullName,
           [Organisation] = o.Name,
           [Job title] = e.JobTitle,
           [Requirement] = ob.EventName,
           [Item code] = ob.ItemCode,
           [Source] = ob.Sources,
           [Must] = CASE WHEN ob.IsMust = 1 THEN N'Yes' ELSE N'No' END,
           [Met] = CASE WHEN ob.IsMet = 1 THEN N'Yes' ELSE N'No' END,
           [Why] = ob.Why,
           [Status] = ISNULL(sv.Name, N'Open'),
           [Session] = ds.SessionCode,
           [Session starts] = ds.StartDate,
           [Pencilled date] = i.PencilledDate,
           [Coverage days] = (SELECT SUM(cv.Days) FROM sel.IdpCoverage cv
                              WHERE cv.CycleId = @cycleId AND cv.PersonnelNo = ob.PersonnelNo
                                AND cv.DevEventId = ob.DevEventId),
           [Target date] = sel.fn_IdpTargetDate(@cycleId, ob.PersonnelNo, @CycleStageId),
           [Approved on] = (SELECT ApprovedOnUtc FROM sel.IdpApproval a
                            WHERE a.CycleId = @cycleId AND a.PersonnelNo = ob.PersonnelNo),
           [Approved by] = (SELECT ApprovedByLogin FROM sel.IdpApproval a
                            WHERE a.CycleId = @cycleId AND a.PersonnelNo = ob.PersonnelNo)
    FROM #obl ob
    JOIN sel.Employee e ON e.PersonnelNo = ob.PersonnelNo
    LEFT JOIN sel.OrgNode o ON o.OrgCode = e.OrgCode
    LEFT JOIN sel.IdpItem i ON i.CycleId = @cycleId AND i.PersonnelNo = ob.PersonnelNo AND i.DevEventId = ob.DevEventId
    LEFT JOIN cfg.DomainValue sv ON sv.DomainValueId = i.StatusValueId
    LEFT JOIN sel.DevSession ds ON ds.DevSessionId = i.DevSessionId
    ORDER BY e.FullName, ob.EventCode;

    DROP TABLE #obl; DROP TABLE #scope;
END
GO
PRINT '  sel.usp_Idp_Export                applied';
GO

/* The coverage balance metric this file writes needs a definition like any other. */
MERGE sel.MetricDefinition AS t
USING (VALUES (N'CoverageDaysPlanned', N'Coverage days planned',
               N'Days of coverage assigned in a development plan, deducted as they are assigned.', N'number', 60))
    AS s (MetricKey, Name, Description, DataType, SortOrder)
   ON t.MetricKey = s.MetricKey
WHEN MATCHED THEN UPDATE SET Name = s.Name, Description = s.Description
WHEN NOT MATCHED BY TARGET THEN
    INSERT (MetricKey, Name, Description, DataType, SortOrder)
    VALUES (s.MetricKey, s.Name, s.Description, s.DataType, s.SortOrder);
PRINT '  sel.MetricDefinition              extended';
GO

PRINT '== 12_idp complete ===================================================';
GO


/* ---- 13_loads.sql ------------------------------------------------------- */

/* =====================================================================================
   13_loads.sql  —  bringing the source tables in
   -------------------------------------------------------------------------------------
   Every load reads through sel.TableMapping, so a table or column that is named
   differently in the real database is a mapping change, never a code change.  The column
   names inside the roster are settings for the same reason.

   The two things that will actually go wrong, and what is done about them:

     * Personnel-number mismatch.  If a source's EmployeeId is not the roster's
       PersonnelNo, it is mapped through sel.PersonAlias.  Nothing here ever fuzzy-matches
       on a name.
     * Item codes not in the catalogue.  CRS-CAP-02 matches nothing if the extract says
       CAP02.  Codes are normalised on the way in, unknown ones are upserted into
       sel.CatalogItem with NeedsReview = 1, and every unmatched row is written to
       stg.LoadException.

   A missing source is never a silent zero: it is a refusal with a sentence.
   ===================================================================================== */
SET NOCOUNT ON;
GO

PRINT '';
PRINT '== 13_loads ==========================================================';
GO

/* The roster's own column names.  Defaults match the prototype; if the real column is
   called something else, change the setting rather than the procedure.                */
MERGE cfg.Setting AS t
USING (VALUES
    (N'ROSTER_COL_NAME',         N'EmployeeName',       N'The roster column holding the person''s name.'),
    (N'ROSTER_COL_ORG',          N'OrgCode',            N'The roster column holding the organisation code.'),
    (N'ROSTER_COL_ORG_NAME',     N'OrgName',            N'The roster column holding the organisation name.'),
    (N'ROSTER_COL_ORG_PARENT',   N'ParentOrgCode',      N'The roster column holding the parent organisation code.'),
    (N'ROSTER_COL_JOBTITLE',     N'JobTitle',           N'The roster column holding the job title.'),
    (N'ROSTER_COL_SUFFIX',       N'PermJobSuffix',      N'The roster column holding the permanent job suffix.'),
    (N'ROSTER_COL_SUFFIXDESC',   N'PermJobSuffixDesc',  N'The roster column describing the permanent job suffix.'),
    (N'ROSTER_COL_CURRENT_SUFFIX', N'CurrentJobSuffix', N'The roster column holding the current job suffix.'),
    (N'ROSTER_COL_GRADE',        N'GradeCode',          N'The roster column holding the grade.'),
    (N'ROSTER_COL_MGMTLEVEL',    N'ManagementLevel',    N'The roster column holding the management level.'),
    (N'ROSTER_COL_ACTIVE',       N'ActiveInd',          N'The roster column saying whether the person is active.'),
    (N'ROSTER_COL_CHIEF',        N'PermChiefInd',       N'The roster column marking a chief position.'),
    (N'ROSTER_COL_HIREDATE',     N'HireDate',           N'The roster column holding the hire date.'),
    (N'ROSTER_COL_PROMODATE',    N'PromotionDate',      N'The roster column holding the last promotion date.'),
    (N'ROSTER_COL_BIRTHDATE',    N'BirthDate',          N'The roster column holding the date of birth.'),
    (N'ROSTER_COL_GENDER',       N'Gender',             N'The roster column holding gender.'),
    (N'ROSTER_COL_NATIONALITY',  N'Nationality',        N'The roster column holding nationality.'),
    (N'ROSTER_COL_EMAIL',        N'Email',              N'The roster column holding the email address.')
) AS s (SettingKey, TextValue, Description)
   ON t.SettingKey = s.SettingKey
WHEN MATCHED THEN UPDATE SET Description = s.Description
WHEN NOT MATCHED BY TARGET THEN
    INSERT (SettingKey, TextValue, Description) VALUES (s.SettingKey, s.TextValue, s.Description);
PRINT '  cfg.Setting (roster columns)      seeded';
GO

/* Columns the prototype treats as sensitive: readable on a record, refused as a filter. */
MERGE cfg.Setting AS t
USING (VALUES (N'SENSITIVE_COLUMNS', N'Gender,Nationality,BirthDate,DateOfBirth,SpecialNeedInd,MaritalStatus',
               N'Roster columns that are readable on a person''s record but never usable as a filter.'))
    AS s (SettingKey, TextValue, Description)
   ON t.SettingKey = s.SettingKey
WHEN MATCHED THEN UPDATE SET Description = s.Description
WHEN NOT MATCHED BY TARGET THEN
    INSERT (SettingKey, TextValue, Description) VALUES (s.SettingKey, s.TextValue, s.Description);
PRINT '  cfg.Setting (sensitive columns)   seeded';
GO

/* sel.fn_RosterColumn — the real name of a roster column, or NULL when the mapped table
   does not have one by that name.  A load that names a column the table has not got
   would otherwise fail with a SQL error instead of a sentence.                        */
CREATE OR ALTER FUNCTION sel.fn_RosterColumn (@SettingKey nvarchar(80))
RETURNS nvarchar(128)
AS
BEGIN
    DECLARE @col nvarchar(128) = cfg.fn_SettingText(@SettingKey);
    IF @col IS NULL RETURN NULL;
    IF NOT EXISTS (SELECT 1 FROM sel.TableMappingColumn c
                   JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
                   WHERE m.SourceKey = N'ROSTER' AND c.ColumnName = @col)
        RETURN NULL;
    RETURN @col;
END
GO
PRINT '  sel.fn_RosterColumn               applied';
GO

/* sel.fn_ColumnOrNull — a column expression, or a typed NULL when the column is absent.
   One helper, so every load reads an optional column the same way.                    */
CREATE OR ALTER FUNCTION sel.fn_ColumnOrNull (@Alias nvarchar(20), @ColumnName nvarchar(128), @SqlType nvarchar(60))
RETURNS nvarchar(300)
AS
BEGIN
    IF @ColumnName IS NULL RETURN N'CAST(NULL AS ' + @SqlType + N')';
    RETURN N'TRY_CONVERT(' + @SqlType + N', ' + @Alias + N'.' + QUOTENAME(@ColumnName) + N')';
END
GO
PRINT '  sel.fn_ColumnOrNull               applied';
GO

/* =====================================================================================
   sel.usp_Roster_Load — roster -> stg.Employee -> sel.Employee
   -------------------------------------------------------------------------------------
   A row whose organisation does not resolve in sel.OrgNode becomes a load exception
   rather than a person nobody can see.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Roster_Load
    @LoginName nvarchar(128),
    @AsOf      date = NULL,
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    IF sec.fn_ScreenAccess(@LoginName, N'/Admin/Policy/') < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS int) AS Loaded; RETURN;
    END;

    DECLARE @obj nvarchar(300) = sel.fn_MappedObject(N'ROSTER');
    DECLARE @keyCol nvarchar(128) = (SELECT KeyColumn FROM sel.TableMapping WHERE SourceKey = N'ROSTER');
    IF @obj IS NULL OR @keyCol IS NULL
    BEGIN
        SET @Problem = cfg.fn_Message(N'ROSTER_UNMAPPED');
        SELECT TOP (0) CAST(NULL AS int) AS Loaded; RETURN;
    END;

    DECLARE @batch uniqueidentifier = NEWID();
    DECLARE @active nvarchar(400) = ISNULL(cfg.fn_SettingText(N'ROSTER_ACTIVE_VALUES'), N'Y');

    /* Every optional column resolves to itself or to a typed NULL, so a roster that is
       missing one still loads and the screen shows a blank rather than failing. */
    DECLARE @sql nvarchar(max) = N'
        INSERT stg.Employee (PersonnelNo, FullName, OrgCode, JobTitle, PermJobSuffix, PermJobSuffixDesc,
                             CurrentJobSuffix, GradeCode, ManagementLevelCode, ActiveInd, PermChiefInd,
                             HireDate, PromotionDate, BirthDate, Gender, Nationality, Email, BatchId)
        SELECT TRY_CONVERT(nvarchar(30),  rs.' + QUOTENAME(@keyCol) + N'),
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_NAME'),           N'nvarchar(200)') + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_ORG'),            N'nvarchar(40)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_JOBTITLE'),       N'nvarchar(200)') + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_SUFFIX'),         N'nvarchar(30)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_SUFFIXDESC'),     N'nvarchar(200)') + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_CURRENT_SUFFIX'), N'nvarchar(30)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_GRADE'),          N'nvarchar(20)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_MGMTLEVEL'),      N'nvarchar(40)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_ACTIVE'),         N'nvarchar(20)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_CHIEF'),          N'nvarchar(10)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_HIREDATE'),       N'date')          + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_PROMODATE'),      N'date')          + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_BIRTHDATE'),      N'date')          + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_GENDER'),         N'nvarchar(20)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_NATIONALITY'),    N'nvarchar(60)')  + N',
               ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_EMAIL'),          N'nvarchar(200)') + N',
               @batch
        FROM ' + @obj + N' rs;';

    BEGIN TRY
        TRUNCATE TABLE stg.Employee;
        EXEC sp_executesql @sql, N'@batch uniqueidentifier', @batch = @batch;
    END TRY
    BEGIN CATCH
        SET @Problem = N'The roster could not be read: ' + ERROR_MESSAGE();
        SELECT TOP (0) CAST(NULL AS int) AS Loaded; RETURN;
    END CATCH;

    /* The organisation tree, built from the roster's own org columns where it has them. */
    DECLARE @orgCol nvarchar(128) = sel.fn_RosterColumn(N'ROSTER_COL_ORG');
    IF @orgCol IS NOT NULL
    BEGIN
        DECLARE @orgSql nvarchar(max) = N'
            MERGE sel.OrgNode AS t
            USING (SELECT DISTINCT
                          OrgCode = TRY_CONVERT(nvarchar(40), rs.' + QUOTENAME(@orgCol) + N'),
                          Name    = ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_ORG_NAME'),   N'nvarchar(200)') + N',
                          Parent  = ' + sel.fn_ColumnOrNull(N'rs', sel.fn_RosterColumn(N'ROSTER_COL_ORG_PARENT'), N'nvarchar(40)')  + N'
                   FROM ' + @obj + N' rs
                   WHERE rs.' + QUOTENAME(@orgCol) + N' IS NOT NULL) AS s
               ON t.OrgCode = s.OrgCode
            WHEN MATCHED THEN UPDATE SET Name = ISNULL(s.Name, t.Name),
                                         ParentOrgCode = ISNULL(s.Parent, t.ParentOrgCode)
            WHEN NOT MATCHED BY TARGET THEN
                INSERT (OrgCode, Name, ParentOrgCode) VALUES (s.OrgCode, ISNULL(s.Name, s.OrgCode), s.Parent);';
        BEGIN TRY
            EXEC sp_executesql @orgSql;
        END TRY
        BEGIN CATCH
            INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText, BatchId)
            VALUES (N'ROSTER', @obj, NULL, N'ORG_BUILD_FAILED',
                    N'The organisation tree could not be built from the roster: ' + ERROR_MESSAGE(), @batch);
        END CATCH;
    END;

    /* A parent that does not exist would orphan a whole subtree: record it and cut the
       link, rather than losing everyone under it. */
    INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText, BatchId)
    SELECT N'ROSTER', @obj, n.OrgCode, N'ORG_PARENT_MISSING',
           N'Organisation ' + n.OrgCode + N' names a parent (' + n.ParentOrgCode
         + N') that is not in the roster, so it was treated as a root.', @batch
    FROM sel.OrgNode n
    WHERE n.ParentOrgCode IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM sel.OrgNode p WHERE p.OrgCode = n.ParentOrgCode);

    UPDATE n SET ParentOrgCode = NULL
    FROM sel.OrgNode n
    WHERE n.ParentOrgCode IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM sel.OrgNode p WHERE p.OrgCode = n.ParentOrgCode);

    DECLARE @p nvarchar(400);
    EXEC sel.usp_Org_RebuildAncestors @LoginName = @LoginName, @Problem = @p OUTPUT;

    /* Rows that cannot be placed.  Each one is a sentence, not a silent drop. */
    INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText, BatchId)
    SELECT N'ROSTER', @obj, ISNULL(s.PersonnelNo, N'(no personnel number)'),
           CASE WHEN s.PersonnelNo IS NULL THEN N'NO_KEY' ELSE N'ORG_NOT_FOUND' END,
           CASE WHEN s.PersonnelNo IS NULL
                THEN N'A roster row has no personnel number, so it cannot be joined to anything.'
                ELSE N'Personnel number ' + s.PersonnelNo + N' names organisation '
                   + ISNULL(s.OrgCode, N'(none)') + N', which is not in the organisation tree.' END,
           @batch
    FROM stg.Employee s
    WHERE s.BatchId = @batch
      AND (s.PersonnelNo IS NULL
        OR s.OrgCode IS NULL
        OR NOT EXISTS (SELECT 1 FROM sel.OrgNode o WHERE o.OrgCode = s.OrgCode));

    BEGIN TRAN;
    MERGE sel.Employee AS t
    USING (SELECT s.PersonnelNo, s.FullName, s.OrgCode, s.JobTitle, s.PermJobSuffix, s.PermJobSuffixDesc,
                  s.CurrentJobSuffix, s.GradeCode, s.ManagementLevelCode,
                  IsActive = CONVERT(bit, CASE WHEN N',' + @active + N',' LIKE N'%,' + ISNULL(s.ActiveInd, N'') + N',%'
                                  THEN 1 ELSE 0 END),
                  PermChiefInd = CASE WHEN UPPER(ISNULL(s.PermChiefInd, N'')) IN (N'Y', N'1', N'TRUE')
                                      THEN 1 ELSE 0 END,
                  s.HireDate, s.PromotionDate, s.BirthDate, s.Gender, s.Nationality, s.Email
           FROM stg.Employee s
           WHERE s.BatchId = @batch AND s.PersonnelNo IS NOT NULL
             AND EXISTS (SELECT 1 FROM sel.OrgNode o WHERE o.OrgCode = s.OrgCode)) AS src
       ON t.PersonnelNo = src.PersonnelNo
    WHEN MATCHED THEN UPDATE SET
        FullName = ISNULL(src.FullName, t.FullName), OrgCode = src.OrgCode, JobTitle = src.JobTitle,
        PermJobSuffix = src.PermJobSuffix, PermJobSuffixDesc = src.PermJobSuffixDesc,
        CurrentJobSuffix = src.CurrentJobSuffix, GradeCode = src.GradeCode,
        ManagementLevelCode = src.ManagementLevelCode, IsActive = src.IsActive,
        PermChiefInd = src.PermChiefInd, HireDate = src.HireDate, PromotionDate = src.PromotionDate,
        BirthDate = src.BirthDate, Gender = src.Gender, Nationality = src.Nationality,
        Email = src.Email, LoadedOnUtc = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (PersonnelNo, FullName, OrgCode, JobTitle, PermJobSuffix, PermJobSuffixDesc,
                CurrentJobSuffix, GradeCode, ManagementLevelCode, IsActive, PermChiefInd,
                HireDate, PromotionDate, BirthDate, Gender, Nationality, Email)
        VALUES (src.PersonnelNo, ISNULL(src.FullName, src.PersonnelNo), src.OrgCode, src.JobTitle,
                src.PermJobSuffix, src.PermJobSuffixDesc, src.CurrentJobSuffix, src.GradeCode,
                src.ManagementLevelCode, src.IsActive, src.PermChiefInd, src.HireDate,
                src.PromotionDate, src.BirthDate, src.Gender, src.Nationality, src.Email);
    DECLARE @loaded int = @@ROWCOUNT;
    COMMIT;

    /* Discover the roster's columns, then the fields and the column catalogue. */
    EXEC sel.usp_TableMapping_Discover @LoginName = @LoginName, @SourceKey = N'ROSTER', @Problem = @p OUTPUT;
    EXEC sel.usp_RosterField_Sync @LoginName = @LoginName, @Problem = @p OUTPUT;
    EXEC sel.usp_ColumnCatalog_Sync @LoginName = @LoginName, @Problem = @p OUTPUT;

    UPDATE sel.TableMapping SET LastSyncUtc = SYSUTCDATETIME(),
           RowCountCached = (SELECT COUNT(*) FROM stg.Employee WHERE BatchId = @batch)
    WHERE SourceKey = N'ROSTER';

    EXEC audit.usp_Log @TableName = N'sel.Employee', @KeyText = N'(roster load)', @ActionCode = N'LOAD',
                       @LoginName = @LoginName;

    SELECT Loaded = @loaded,
           StagedRows = (SELECT COUNT(*) FROM stg.Employee WHERE BatchId = @batch),
           Exceptions = (SELECT COUNT(*) FROM stg.LoadException WHERE BatchId = @batch),
           OrgNodes = (SELECT COUNT(*) FROM sel.OrgNode),
           BatchId = @batch;
END
GO
PRINT '  sel.usp_Roster_Load               applied';
GO

/* sel.usp_ColumnCatalog_Sync — the ~200-column employee record, grouped and searchable,
   behind the column picker.  Sensitive columns are marked from configuration.          */
CREATE OR ALTER PROCEDURE sel.usp_ColumnCatalog_Sync
    @LoginName nvarchar(128),
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Problem = NULL;

    IF NOT EXISTS (SELECT 1 FROM sel.TableMapping WHERE SourceKey = N'ROSTER' AND IsMapped = 1)
    BEGIN
        SET @Problem = cfg.fn_Message(N'ROSTER_UNMAPPED');
        SELECT TOP (0) CAST(NULL AS int) AS ColumnCatalogId; RETURN;
    END;

    DECLARE @sensitive nvarchar(400) = ISNULL(cfg.fn_SettingText(N'SENSITIVE_COLUMNS'), N'');
    DECLARE @defaults nvarchar(400) = ISNULL(cfg.fn_SettingText(N'ROSTER_COL_NAME'), N'')
                                    + N',' + ISNULL(cfg.fn_SettingText(N'ROSTER_COL_JOBTITLE'), N'')
                                    + N',' + ISNULL(cfg.fn_SettingText(N'ROSTER_COL_GRADE'), N'');

    UPDATE sel.ColumnCatalog SET IsPresent = 0;

    MERGE sel.ColumnCatalog AS t
    USING (SELECT c.ColumnName, c.DataType, c.OrdinalPos
           FROM sel.TableMappingColumn c
           JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
           WHERE m.SourceKey = N'ROSTER') AS s
       ON t.ColumnName = s.ColumnName
    WHEN MATCHED THEN UPDATE SET
        DataType = s.DataType, SortOrder = s.OrdinalPos, IsPresent = 1,
        IsSensitive = CONVERT(bit, CASE WHEN N',' + @sensitive + N',' LIKE N'%,' + s.ColumnName + N',%' THEN 1 ELSE 0 END)
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (ColumnName, Caption, GroupName, DataType, IsSensitive, IsDefault, SortOrder, IsPresent)
        VALUES (s.ColumnName, s.ColumnName,
                /* A rough grouping so the picker is not one flat list of two hundred. */
                CASE WHEN s.ColumnName LIKE N'%Org%'  OR s.ColumnName LIKE N'%Depart%' THEN N'Organisation'
                     WHEN s.ColumnName LIKE N'%Job%'  OR s.ColumnName LIKE N'%Position%'
                       OR s.ColumnName LIKE N'%Suffix%' OR s.ColumnName LIKE N'%Grade%' THEN N'Job'
                     WHEN s.ColumnName LIKE N'%Date%' OR s.ColumnName LIKE N'%Hire%'   THEN N'Dates'
                     WHEN s.ColumnName LIKE N'%Name%' OR s.ColumnName LIKE N'%Email%'  THEN N'Person'
                     ELSE N'Roster' END,
                s.DataType,
                CASE WHEN N',' + @sensitive + N',' LIKE N'%,' + s.ColumnName + N',%' THEN 1 ELSE 0 END,
                CASE WHEN N',' + @defaults  + N',' LIKE N'%,' + s.ColumnName + N',%' THEN 1 ELSE 0 END,
                s.OrdinalPos, 1);

    SELECT Columns = (SELECT COUNT(*) FROM sel.ColumnCatalog WHERE IsPresent = 1),
           Sensitive = (SELECT COUNT(*) FROM sel.ColumnCatalog WHERE IsPresent = 1 AND IsSensitive = 1),
           Missing = (SELECT COUNT(*) FROM sel.ColumnCatalog WHERE IsPresent = 0);
END
GO
PRINT '  sel.usp_ColumnCatalog_Sync        applied';
GO

/* =====================================================================================
   sel.usp_Evidence_SyncOne — one flag-mode source into sel.EmployeeRecord
   -------------------------------------------------------------------------------------
   MERGE on (PersonnelNo, KindCode, ItemCode).  Everything that could not be placed lands
   in stg.LoadException with a sentence.
   ===================================================================================== */
CREATE OR ALTER PROCEDURE sel.usp_Evidence_SyncOne
    @LoginName nvarchar(128),
    @SourceKey nvarchar(40),
    @KindCode  nvarchar(30),
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;

    DECLARE @obj nvarchar(300) = sel.fn_MappedObject(@SourceKey);
    IF @obj IS NULL
    BEGIN
        /* A missing source is never a silent zero. */
        SET @Problem = ISNULL((SELECT BreaksWhenUnmapped FROM sel.TableMapping WHERE SourceKey = @SourceKey),
                              N'No table is mapped for ' + @SourceKey + N'.');
        SELECT SourceKey = @SourceKey, Loaded = CAST(NULL AS int), Exceptions = CAST(NULL AS int), Problem = @Problem;
        RETURN;
    END;

    DECLARE @keyCol  nvarchar(128) = (SELECT KeyColumn  FROM sel.TableMapping WHERE SourceKey = @SourceKey);
    DECLARE @itemCol nvarchar(128) = (SELECT ItemColumn FROM sel.TableMapping WHERE SourceKey = @SourceKey);
    IF @keyCol IS NULL OR @itemCol IS NULL
    BEGIN
        SET @Problem = N'The mapping for ' + @SourceKey + N' does not name both a person column and an item column.';
        SELECT SourceKey = @SourceKey, Loaded = CAST(NULL AS int), Exceptions = CAST(NULL AS int), Problem = @Problem;
        RETURN;
    END;

    DECLARE @batch uniqueidentifier = NEWID();

    /* Land the source rows as they are, resolving the person key through the alias table
       where the source uses its own identifier.  Never fuzzy-match on a name. */
    CREATE TABLE #raw
    (
        SourceKeyText nvarchar(60)  NULL,
        PersonnelNo   nvarchar(30)  NULL,
        RawItemCode   nvarchar(120) NULL,
        ItemCode      nvarchar(60)  NULL,
        Status        nvarchar(60)  NULL,
        Score         decimal(18,4) NULL,
        MaxScore      decimal(18,4) NULL,
        CompletedOn   date          NULL,
        ExpiresOn     date          NULL
    );

    /* Optional columns resolve to typed NULLs when the source has not got them. */
    DECLARE @has nvarchar(max) = N'';
    DECLARE @statusExpr nvarchar(300) = N'CAST(NULL AS nvarchar(60))',
            @scoreExpr  nvarchar(300) = N'CAST(NULL AS decimal(18,4))',
            @maxExpr    nvarchar(300) = N'CAST(NULL AS decimal(18,4))',
            @compExpr   nvarchar(300) = N'CAST(NULL AS date)',
            @expExpr    nvarchar(300) = N'CAST(NULL AS date)';

    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = @SourceKey AND c.ColumnName = N'Status')
        SET @statusExpr = N'TRY_CONVERT(nvarchar(60), src.[Status])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = @SourceKey AND c.ColumnName = N'Score')
        SET @scoreExpr = N'TRY_CONVERT(decimal(18,4), src.[Score])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = @SourceKey AND c.ColumnName = N'MaxScore')
        SET @maxExpr = N'TRY_CONVERT(decimal(18,4), src.[MaxScore])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = @SourceKey AND c.ColumnName = N'CompletedOn')
        SET @compExpr = N'TRY_CONVERT(date, src.[CompletedOn])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = @SourceKey AND c.ColumnName = N'ExpiresOn')
        SET @expExpr = N'TRY_CONVERT(date, src.[ExpiresOn])';

    DECLARE @sql nvarchar(max) = N'
        INSERT #raw (SourceKeyText, PersonnelNo, RawItemCode, ItemCode, Status, Score, MaxScore, CompletedOn, ExpiresOn)
        SELECT SourceKeyText = TRY_CONVERT(nvarchar(60), src.' + QUOTENAME(@keyCol) + N'),
               /* The roster''s own number, or the one the alias table maps it to. */
               PersonnelNo = COALESCE(e.PersonnelNo, al.PersonnelNo),
               RawItemCode = TRY_CONVERT(nvarchar(120), src.' + QUOTENAME(@itemCol) + N'),
               /* Normalised on the way in: trimmed and upper-cased, so CAP02 and cap02
                  are the same code and only the dash is a real difference. */
               ItemCode = UPPER(LTRIM(RTRIM(TRY_CONVERT(nvarchar(60), src.' + QUOTENAME(@itemCol) + N')))),
               ' + @statusExpr + N', ' + @scoreExpr + N', ' + @maxExpr + N', ' + @compExpr + N', ' + @expExpr + N'
        FROM ' + @obj + N' src
        LEFT JOIN sel.Employee e ON e.PersonnelNo = TRY_CONVERT(nvarchar(30), src.' + QUOTENAME(@keyCol) + N')
        LEFT JOIN sel.PersonAlias al ON al.AliasKey = TRY_CONVERT(nvarchar(60), src.' + QUOTENAME(@keyCol) + N')
                                    AND al.SourceKey IN (@SourceKey, N''ALL'');';

    BEGIN TRY
        EXEC sp_executesql @sql, N'@SourceKey nvarchar(40)', @SourceKey = @SourceKey;
    END TRY
    BEGIN CATCH
        SET @Problem = @SourceKey + N' could not be read: ' + ERROR_MESSAGE();
        SELECT SourceKey = @SourceKey, Loaded = CAST(NULL AS int), Exceptions = CAST(NULL AS int), Problem = @Problem;
        DROP TABLE #raw; RETURN;
    END CATCH;

    /* Personnel numbers this source uses that the roster has never heard of. */
    INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText, BatchId)
    SELECT DISTINCT @SourceKey, @obj, ISNULL(r.SourceKeyText, N'(no key)'), N'PERSON_NOT_FOUND',
           N'"' + ISNULL(r.SourceKeyText, N'(no key)') + N'" is not a personnel number in the roster. '
         + N'Add a row to sel.PersonAlias if this source uses its own identifier.', @batch
    FROM #raw r WHERE r.PersonnelNo IS NULL;

    /* Item codes the catalogue has never seen.  Upsert them for review rather than
       dropping the evidence, and record each one. */
    INSERT sel.CatalogItem (ItemCode, Name, KindCode, NeedsReview)
    SELECT DISTINCT r.ItemCode, r.ItemCode, @KindCode, 1
    FROM #raw r
    WHERE r.ItemCode IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM sel.CatalogItem ci WHERE ci.KindCode = @KindCode AND ci.ItemCode = r.ItemCode);

    INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText, BatchId)
    SELECT DISTINCT @SourceKey, @obj, r.RawItemCode, N'ITEM_CODE_UNKNOWN',
           N'"' + ISNULL(r.RawItemCode, N'(blank)') + N'" was not in the catalogue. '
         + N'It has been added for review — check it is not a differently written form of an existing code.', @batch
    FROM #raw r
    WHERE r.ItemCode IS NOT NULL
      AND EXISTS (SELECT 1 FROM sel.CatalogItem ci
                  WHERE ci.KindCode = @KindCode AND ci.ItemCode = r.ItemCode AND ci.NeedsReview = 1);

    INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText, BatchId)
    SELECT @SourceKey, @obj, ISNULL(r.SourceKeyText, N'(no key)'), N'NO_ITEM_CODE',
           N'A row for ' + ISNULL(r.SourceKeyText, N'(no key)') + N' has no item code, so it cannot be matched.', @batch
    FROM #raw r WHERE r.ItemCode IS NULL OR r.ItemCode = N'';

    BEGIN TRAN;
    MERGE sel.EmployeeRecord AS t
    USING (SELECT PersonnelNo, ItemCode,
                  Status = MAX(Status), Score = MAX(Score), MaxScore = MAX(MaxScore),
                  CompletedOn = MAX(CompletedOn), ExpiresOn = MAX(ExpiresOn)
           FROM #raw
           WHERE PersonnelNo IS NOT NULL AND ItemCode IS NOT NULL AND ItemCode <> N''
           GROUP BY PersonnelNo, ItemCode) AS s
       ON t.PersonnelNo = s.PersonnelNo AND t.KindCode = @KindCode AND t.ItemCode = s.ItemCode
    WHEN MATCHED THEN UPDATE SET
        Status = s.Status, Score = s.Score, MaxScore = s.MaxScore,
        CompletedOn = s.CompletedOn, ExpiresOn = s.ExpiresOn,
        Source = @obj, LoadedOnUtc = SYSUTCDATETIME()
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (PersonnelNo, KindCode, ItemCode, Status, Score, MaxScore, CompletedOn, ExpiresOn, Source)
        VALUES (s.PersonnelNo, @KindCode, s.ItemCode, s.Status, s.Score, s.MaxScore,
                s.CompletedOn, s.ExpiresOn, @obj);
    DECLARE @loaded int = @@ROWCOUNT;
    COMMIT;

    UPDATE sel.TableMapping SET LastSyncUtc = SYSUTCDATETIME(),
           RowCountCached = (SELECT COUNT(*) FROM #raw) WHERE SourceKey = @SourceKey;
    UPDATE sel.EvidenceSource SET LastSyncUtc = SYSUTCDATETIME(),
           RowCountCached = (SELECT COUNT(*) FROM sel.EmployeeRecord WHERE KindCode = @KindCode)
    WHERE KindCode = @KindCode;

    SELECT SourceKey = @SourceKey, Loaded = @loaded,
           Exceptions = (SELECT COUNT(*) FROM stg.LoadException WHERE BatchId = @batch),
           Problem = CAST(NULL AS nvarchar(400));

    DROP TABLE #raw;
END
GO
PRINT '  sel.usp_Evidence_SyncOne          applied';
GO

/* sel.usp_Coverage_Sync — dbo.EmployeeCoverage into sel.EmployeeCoverage (the rows, for
   the conditions) AND sel.EmployeeMetric (the aggregate, for the criteria).  An
   aggregate cannot be taken apart again, which is why both are kept.                   */
CREATE OR ALTER PROCEDURE sel.usp_Coverage_Sync
    @LoginName nvarchar(128),
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;

    DECLARE @obj nvarchar(300) = sel.fn_MappedObject(N'EXPERIENCE');
    IF @obj IS NULL
    BEGIN
        SET @Problem = ISNULL((SELECT BreaksWhenUnmapped FROM sel.TableMapping WHERE SourceKey = N'EXPERIENCE'),
                              N'No coverage table is mapped.');
        SELECT SourceKey = N'EXPERIENCE', Loaded = CAST(NULL AS int), Problem = @Problem;
        RETURN;
    END;

    DECLARE @keyCol  nvarchar(128) = (SELECT KeyColumn  FROM sel.TableMapping WHERE SourceKey = N'EXPERIENCE');
    DECLARE @itemCol nvarchar(128) = (SELECT ItemColumn FROM sel.TableMapping WHERE SourceKey = N'EXPERIENCE');
    DECLARE @batch uniqueidentifier = NEWID();

    CREATE TABLE #cov
    (
        PersonnelNo nvarchar(30) NULL, SourceKeyText nvarchar(60) NULL,
        ItemCode nvarchar(60) NULL, CoverageType nvarchar(60) NULL,
        Department nvarchar(200) NULL, PositionSuffix nvarchar(30) NULL,
        StartDate date NULL, EndDate date NULL, Days decimal(18,4) NULL
    );

    DECLARE @deptExpr nvarchar(200) = N'CAST(NULL AS nvarchar(200))',
            @typeExpr nvarchar(200) = N'CAST(NULL AS nvarchar(60))',
            @startExpr nvarchar(200) = N'CAST(NULL AS date)',
            @endExpr  nvarchar(200) = N'CAST(NULL AS date)',
            @daysExpr nvarchar(200) = N'CAST(NULL AS decimal(18,4))';

    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = N'EXPERIENCE' AND c.ColumnName = N'Department')
        SET @deptExpr = N'TRY_CONVERT(nvarchar(200), src.[Department])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = N'EXPERIENCE' AND c.ColumnName = N'CoverageType')
        SET @typeExpr = N'TRY_CONVERT(nvarchar(60), src.[CoverageType])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = N'EXPERIENCE' AND c.ColumnName = N'StartDate')
        SET @startExpr = N'TRY_CONVERT(date, src.[StartDate])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = N'EXPERIENCE' AND c.ColumnName = N'EndDate')
        SET @endExpr = N'TRY_CONVERT(date, src.[EndDate])';
    IF EXISTS (SELECT 1 FROM sel.TableMappingColumn c JOIN sel.TableMapping m ON m.TableMappingId = c.TableMappingId
               WHERE m.SourceKey = N'EXPERIENCE' AND c.ColumnName = N'Days')
        SET @daysExpr = N'TRY_CONVERT(decimal(18,4), src.[Days])';

    DECLARE @sql nvarchar(max) = N'
        INSERT #cov (PersonnelNo, SourceKeyText, ItemCode, CoverageType, Department, PositionSuffix,
                     StartDate, EndDate, Days)
        SELECT COALESCE(e.PersonnelNo, al.PersonnelNo),
               TRY_CONVERT(nvarchar(60), src.' + QUOTENAME(@keyCol) + N'),
               UPPER(LTRIM(RTRIM(TRY_CONVERT(nvarchar(60), src.' + QUOTENAME(@itemCol) + N')))),
               ' + @typeExpr + N', ' + @deptExpr + N',
               TRY_CONVERT(nvarchar(30), src.' + QUOTENAME(@itemCol) + N'),
               ' + @startExpr + N', ' + @endExpr + N',
               /* If the source does not carry a day count, derive it from the dates. */
               COALESCE(' + @daysExpr + N',
                        CASE WHEN ' + @startExpr + N' IS NOT NULL AND ' + @endExpr + N' IS NOT NULL
                             THEN DATEDIFF(DAY, ' + @startExpr + N', ' + @endExpr + N') + 1 END)
        FROM ' + @obj + N' src
        LEFT JOIN sel.Employee e ON e.PersonnelNo = TRY_CONVERT(nvarchar(30), src.' + QUOTENAME(@keyCol) + N')
        LEFT JOIN sel.PersonAlias al ON al.AliasKey = TRY_CONVERT(nvarchar(60), src.' + QUOTENAME(@keyCol) + N')
                                    AND al.SourceKey IN (N''EXPERIENCE'', N''ALL'');';

    BEGIN TRY
        EXEC sp_executesql @sql;
    END TRY
    BEGIN CATCH
        SET @Problem = N'The coverage table could not be read: ' + ERROR_MESSAGE();
        SELECT SourceKey = N'EXPERIENCE', Loaded = CAST(NULL AS int), Problem = @Problem;
        DROP TABLE #cov; RETURN;
    END CATCH;

    INSERT stg.LoadException (SourceKey, SourceTable, KeyText, ReasonCode, ReasonText, BatchId)
    SELECT DISTINCT N'EXPERIENCE', @obj, ISNULL(c.SourceKeyText, N'(no key)'), N'PERSON_NOT_FOUND',
           N'"' + ISNULL(c.SourceKeyText, N'(no key)') + N'" is not a personnel number in the roster.', @batch
    FROM #cov c WHERE c.PersonnelNo IS NULL;

    BEGIN TRAN;
    /* The rows, replaced wholesale for the people this extract covers. */
    DELETE cv FROM sel.EmployeeCoverage cv
    WHERE cv.Source = @obj
      AND cv.PersonnelNo IN (SELECT DISTINCT PersonnelNo FROM #cov WHERE PersonnelNo IS NOT NULL);

    INSERT sel.EmployeeCoverage (PersonnelNo, ItemCode, CoverageType, Department, PositionSuffix,
                                 StartDate, EndDate, Days, Source)
    SELECT PersonnelNo, ItemCode, CoverageType, Department, PositionSuffix,
           StartDate, EndDate, Days, @obj
    FROM #cov WHERE PersonnelNo IS NOT NULL;
    DECLARE @loaded int = @@ROWCOUNT;
    COMMIT;

    UPDATE sel.TableMapping SET LastSyncUtc = SYSUTCDATETIME(), RowCountCached = @loaded
    WHERE SourceKey = N'EXPERIENCE';
    UPDATE sel.EvidenceSource SET LastSyncUtc = SYSUTCDATETIME() WHERE KindCode IN (N'COVERAGE', N'EXPERIENCE');

    SELECT SourceKey = N'EXPERIENCE', Loaded = @loaded,
           Exceptions = (SELECT COUNT(*) FROM stg.LoadException WHERE BatchId = @batch),
           Problem = CAST(NULL AS nvarchar(400));

    DROP TABLE #cov;
END
GO
PRINT '  sel.usp_Coverage_Sync             applied';
GO

/* sel.usp_Pmp_Sync — one row per person per year.  Never averaged on load: the average
   is a metric, computed afterwards, and can be undone.                                 */
CREATE OR ALTER PROCEDURE sel.usp_Pmp_Sync
    @LoginName nvarchar(128),
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET @Problem = NULL;

    DECLARE @obj nvarchar(300) = sel.fn_MappedObject(N'PMP');
    IF @obj IS NULL
    BEGIN
        SET @Problem = ISNULL((SELECT BreaksWhenUnmapped FROM sel.TableMapping WHERE SourceKey = N'PMP'),
                              N'No performance table is mapped.');
        SELECT SourceKey = N'PMP', Loaded = CAST(NULL AS int), Problem = @Problem;
        RETURN;
    END;

    DECLARE @keyCol nvarchar(128) = (SELECT KeyColumn FROM sel.TableMapping WHERE SourceKey = N'PMP');
    DECLARE @sql nvarchar(max) = N'
        MERGE sel.EmployeePmp AS t
        USING (SELECT PersonnelNo = COALESCE(e.PersonnelNo, al.PersonnelNo),
                      RatingYear  = TRY_CONVERT(smallint, src.[RatingYear]),
                      RatingCode  = TRY_CONVERT(nvarchar(20), src.[RatingCode]),
                      RatingValue = TRY_CONVERT(decimal(18,4), src.[RatingValue])
               FROM ' + @obj + N' src
               LEFT JOIN sel.Employee e ON e.PersonnelNo = TRY_CONVERT(nvarchar(30), src.' + QUOTENAME(@keyCol) + N')
               LEFT JOIN sel.PersonAlias al ON al.AliasKey = TRY_CONVERT(nvarchar(60), src.' + QUOTENAME(@keyCol) + N')
                                           AND al.SourceKey IN (N''PMP'', N''ALL'')) AS s
           ON t.PersonnelNo = s.PersonnelNo AND t.RatingYear = s.RatingYear
        WHEN MATCHED THEN UPDATE SET RatingCode = s.RatingCode, RatingValue = s.RatingValue,
                                     Source = @obj, LoadedOnUtc = SYSUTCDATETIME()
        WHEN NOT MATCHED BY TARGET AND s.PersonnelNo IS NOT NULL AND s.RatingYear IS NOT NULL THEN
            INSERT (PersonnelNo, RatingYear, RatingCode, RatingValue, Source)
            VALUES (s.PersonnelNo, s.RatingYear, s.RatingCode, s.RatingValue, @obj);';

    DECLARE @loaded int = 0;
    BEGIN TRY
        EXEC sp_executesql @sql, N'@obj nvarchar(300)', @obj = @obj;
        SET @loaded = @@ROWCOUNT;
    END TRY
    BEGIN CATCH
        SET @Problem = N'The performance table could not be read: ' + ERROR_MESSAGE();
        SELECT SourceKey = N'PMP', Loaded = CAST(NULL AS int), Problem = @Problem;
        RETURN;
    END CATCH;

    UPDATE sel.TableMapping SET LastSyncUtc = SYSUTCDATETIME(), RowCountCached = @loaded WHERE SourceKey = N'PMP';
    SELECT SourceKey = N'PMP', Loaded = @loaded, Exceptions = 0, Problem = CAST(NULL AS nvarchar(400));
END
GO
PRINT '  sel.usp_Pmp_Sync                  applied';
GO

/* sel.usp_Evidence_SyncAll — every source in order, finishing with the metric rebuild. */
CREATE OR ALTER PROCEDURE sel.usp_Evidence_SyncAll
    @LoginName nvarchar(128),
    @AsOf      date = NULL,
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Problem = NULL;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    IF sec.fn_ScreenAccess(@LoginName, N'/Admin/Policy/') < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS nvarchar(40)) AS SourceKey; RETURN;
    END;

    CREATE TABLE #result (SourceKey nvarchar(40), Loaded int NULL, Exceptions int NULL, Problem nvarchar(400) NULL);

    DECLARE @p nvarchar(400);
    INSERT #result EXEC sel.usp_Evidence_SyncOne @LoginName = @LoginName, @SourceKey = N'COURSE',
           @KindCode = N'COURSE', @Problem = @p OUTPUT;
    INSERT #result EXEC sel.usp_Evidence_SyncOne @LoginName = @LoginName, @SourceKey = N'ASSESSMENT',
           @KindCode = N'ASSESSMENT', @Problem = @p OUTPUT;
    INSERT #result EXEC sel.usp_Evidence_SyncOne @LoginName = @LoginName, @SourceKey = N'FEEDBACK360',
           @KindCode = N'FEEDBACK360', @Problem = @p OUTPUT;
    INSERT #result EXEC sel.usp_Coverage_Sync @LoginName = @LoginName, @Problem = @p OUTPUT;
    INSERT #result EXEC sel.usp_Pmp_Sync @LoginName = @LoginName, @Problem = @p OUTPUT;

    /* The aggregates the criteria builder filters on, rebuilt last. */
    EXEC sel.usp_Metric_Refresh @LoginName = @LoginName, @AsOf = @AsOf;

    EXEC audit.usp_Log @TableName = N'sel.EmployeeRecord', @KeyText = N'(sync all)', @ActionCode = N'SYNC',
                       @LoginName = @LoginName;

    /* A source that could not be read is reported, not hidden. */
    SELECT SourceKey, Loaded, Exceptions, Problem FROM #result ORDER BY SourceKey;

    DECLARE @failed int = (SELECT COUNT(*) FROM #result WHERE Problem IS NOT NULL);
    IF @failed > 0
        SET @Problem = CONVERT(nvarchar(10), @failed) + N' source'
                     + CASE WHEN @failed = 1 THEN N' could' ELSE N's could' END
                     + N' not be read. Every requirement that names them can never be met.';

    DROP TABLE #result;
END
GO
PRINT '  sel.usp_Evidence_SyncAll          applied';
GO

/* sel.usp_LoadException_Resolve — marking one dealt with, so the screen shows what is
   still outstanding rather than the whole history.                                     */
CREATE OR ALTER PROCEDURE sel.usp_LoadException_Resolve
    @LoginName       nvarchar(128),
    @LoadExceptionId bigint,
    @Problem         nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Problem = NULL;
    IF sec.fn_ScreenAccess(@LoginName, N'/Admin/Policy/') < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS bigint) AS LoadExceptionId; RETURN;
    END;

    UPDATE stg.LoadException
       SET IsResolved = 1, ResolvedOnUtc = SYSUTCDATETIME(), ResolvedByLogin = @LoginName
    WHERE LoadExceptionId = @LoadExceptionId;

    SELECT LoadExceptionId = @LoadExceptionId, Resolved = CAST(1 AS bit);
END
GO
PRINT '  sel.usp_LoadException_Resolve     applied';
GO

/* sel.usp_PersonAlias_Save — the answer to a personnel-number mismatch. */
CREATE OR ALTER PROCEDURE sel.usp_PersonAlias_Save
    @LoginName   nvarchar(128),
    @SourceKey   nvarchar(40),
    @AliasKey    nvarchar(60),
    @PersonnelNo nvarchar(30),
    @Note        nvarchar(400) = NULL,
    @Problem     nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Problem = NULL;
    IF sec.fn_ScreenAccess(@LoginName, N'/Admin/Policy/') < 2
    BEGIN
        SET @Problem = cfg.fn_Message(N'READONLY_REFUSAL');
        SELECT TOP (0) CAST(NULL AS int) AS PersonAliasId; RETURN;
    END;
    IF NOT EXISTS (SELECT 1 FROM sel.Employee WHERE PersonnelNo = @PersonnelNo)
    BEGIN
        SET @Problem = N'"' + @PersonnelNo + N'" is not a personnel number in the roster, so nothing can be mapped to it.';
        SELECT TOP (0) CAST(NULL AS int) AS PersonAliasId; RETURN;
    END;

    MERGE sel.PersonAlias AS t
    USING (SELECT @SourceKey AS SourceKey, @AliasKey AS AliasKey) AS s
       ON t.SourceKey = s.SourceKey AND t.AliasKey = s.AliasKey
    WHEN MATCHED THEN UPDATE SET PersonnelNo = @PersonnelNo, Note = @Note
    WHEN NOT MATCHED BY TARGET THEN
        INSERT (SourceKey, AliasKey, PersonnelNo, Note)
        VALUES (s.SourceKey, s.AliasKey, @PersonnelNo, @Note);

    DECLARE @keyText nvarchar(200) = @SourceKey + N'/' + @AliasKey;
    EXEC audit.usp_Log @TableName = N'sel.PersonAlias', @KeyText = @keyText, @ActionCode = N'SAVE',
                       @LoginName = @LoginName;

    SELECT SourceKey = @SourceKey, AliasKey = @AliasKey, PersonnelNo = @PersonnelNo;
END
GO
PRINT '  sel.usp_PersonAlias_Save          applied';
GO

/* sel.usp_Employee_Roster — the Employee roster screen: a server-paged read of the
   mapped roster, with search, sort and page size.  Sensitive columns are readable on a
   record but refused as filters, and the refusal says why.                             */
CREATE OR ALTER PROCEDURE sel.usp_Employee_Roster
    @LoginName nvarchar(128),
    @Search    nvarchar(200) = NULL,
    @OrgCode   nvarchar(40) = NULL,
    @SortBy    nvarchar(128) = NULL,
    @SortDir   nvarchar(4) = N'ASC',
    @PageNo    int = 1,
    @PageSize  int = NULL,
    @Problem   nvarchar(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET @Problem = NULL;
    IF @PageSize IS NULL SET @PageSize = CAST(ISNULL(cfg.fn_SettingNum(N'PAGE_SIZE_DEFAULT'), 50) AS int);
    IF @PageSize > CAST(ISNULL(cfg.fn_SettingNum(N'PAGE_SIZE_MAX'), 500) AS int)
        SET @PageSize = CAST(ISNULL(cfg.fn_SettingNum(N'PAGE_SIZE_MAX'), 500) AS int);
    IF @PageNo IS NULL OR @PageNo < 1 SET @PageNo = 1;
    /* A NULL direction is the default, not a value to compare: NULL NOT IN (...) is
       unknown, so the test below would leave it NULL, the ORDER BY clause would
       concatenate to NULL, and the whole statement would become NULL — which returns no
       rows at all rather than an error. ISNULL first. */
    SET @SortDir = UPPER(ISNULL(NULLIF(LTRIM(RTRIM(@SortDir)), N''), N'ASC'));
    IF @SortDir NOT IN (N'ASC', N'DESC') SET @SortDir = N'ASC';

    DECLARE @order nvarchar(200) = N'e.FullName ' + @SortDir;
    IF @SortBy IN (N'PersonnelNo', N'FullName', N'JobTitle', N'GradeCode', N'PermJobSuffix', N'HireDate')
        SET @order = N'e.' + QUOTENAME(@SortBy) + N' ' + @SortDir;
    ELSE IF @SortBy IS NOT NULL AND EXISTS (SELECT 1 FROM sel.ColumnCatalog WHERE ColumnName = @SortBy AND IsSensitive = 1)
    BEGIN
        SET @Problem = cfg.fn_Message(N'SENSITIVE_FILTER');
        SELECT TOP (0) CAST(NULL AS nvarchar(30)) AS PersonnelNo;
        SELECT TotalRows = CAST(NULL AS int); RETURN;
    END;

    DECLARE @sql nvarchar(max) = N'
        SELECT e.PersonnelNo, e.FullName, e.OrgCode, o.Name AS OrgName, e.JobTitle,
               e.PermJobSuffix, e.PermJobSuffixDesc, e.GradeCode, e.ManagementLevelCode,
               e.HireDate, e.PromotionDate, e.IsActive, e.PermChiefInd
        FROM sel.Employee e
        JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = e.OrgCode
        LEFT JOIN sel.OrgNode o ON o.OrgCode = e.OrgCode
        WHERE (@OrgCode IS NULL OR e.OrgCode = @OrgCode)
          AND (@Search IS NULL OR e.FullName LIKE N''%'' + @Search + N''%''
               OR e.PersonnelNo LIKE N''%'' + @Search + N''%''
               OR e.JobTitle LIKE N''%'' + @Search + N''%''
               OR o.Name LIKE N''%'' + @Search + N''%'')
        ORDER BY ' + @order + N'
        OFFSET (@PageNo - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;';

    EXEC sp_executesql @sql,
         N'@LoginName nvarchar(128), @OrgCode nvarchar(40), @Search nvarchar(200), @PageNo int, @PageSize int',
         @LoginName = @LoginName, @OrgCode = @OrgCode, @Search = @Search, @PageNo = @PageNo, @PageSize = @PageSize;

    SELECT TotalRows = COUNT(*)
    FROM sel.Employee e
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = e.OrgCode
    LEFT JOIN sel.OrgNode o ON o.OrgCode = e.OrgCode
    WHERE (@OrgCode IS NULL OR e.OrgCode = @OrgCode)
      AND (@Search IS NULL OR e.FullName LIKE N'%' + @Search + N'%'
           OR e.PersonnelNo LIKE N'%' + @Search + N'%'
           OR e.JobTitle LIKE N'%' + @Search + N'%'
           OR o.Name LIKE N'%' + @Search + N'%');
END
GO
PRINT '  sel.usp_Employee_Roster           applied';
GO

PRINT '== 13_loads complete =================================================';
GO


/* ---- 14_reports.sql ------------------------------------------------------- */

/* =====================================================================================
   14_reports.sql  —  read models, not new logic
   -------------------------------------------------------------------------------------
   A report that disagrees with a stage screen is a bug in the report, so each of these
   reads the same functions and procedures the screens read: sel.fn_CandidateBox for the
   funnel, sel.usp_Readiness_Spread for the distribution, sec.fn_UserOrgScope for who is
   counted at all.

   Every report returns three result sets, in this order:
     1. its columns  (key, caption, data type, alignment)
     2. its rows
     3. its note     (one sentence saying what the figures mean, and any caveat)
   ===================================================================================== */
SET NOCOUNT ON;
GO

PRINT '';
PRINT '== 14_reports ========================================================';
GO

/* The report registry, so the Reports screen is data rather than a switch. */
IF OBJECT_ID('sel.ReportDefinition') IS NULL
BEGIN
    CREATE TABLE sel.ReportDefinition
    (
        ReportDefinitionId int          IDENTITY(1,1) NOT NULL CONSTRAINT PK_sel_ReportDefinition PRIMARY KEY,
        ReportKey    nvarchar(60)  NOT NULL CONSTRAINT UQ_sel_ReportDefinition_Key UNIQUE,
        Name         nvarchar(160) NOT NULL,
        Description  nvarchar(600) NULL,
        ProcedureName nvarchar(160) NOT NULL,
        NeedsCycle   bit           NOT NULL CONSTRAINT DF_sel_ReportDefinition_Cycle DEFAULT (1),
        SortOrder    int           NOT NULL CONSTRAINT DF_sel_ReportDefinition_Sort  DEFAULT (0),
        IsActive     bit           NOT NULL CONSTRAINT DF_sel_ReportDefinition_Act   DEFAULT (1)
    );
    PRINT '  sel.ReportDefinition              created';
END
ELSE PRINT '  sel.ReportDefinition              skipped';
GO

/* sel.usp_Report_Pipeline — the funnel counts, and each as a share of those identified.
   It reads sel.fn_CandidateBox, so it cannot disagree with the stage screen.           */
CREATE OR ALTER PROCEDURE sel.usp_Report_Pipeline
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    SELECT ColumnKey, Caption, DataType, Align, SortOrder FROM (VALUES
        (N'ProcessName', N'Process',   N'text',   N'left',  10),
        (N'StageName',   N'Stage',     N'text',   N'left',  20),
        (N'Caption',     N'Box',       N'text',   N'left',  30),
        (N'Cnt',         N'People',    N'number', N'right', 40),
        (N'SharePct',    N'Share',     N'share',  N'right', 50)
    ) v (ColumnKey, Caption, DataType, Align, SortOrder) ORDER BY SortOrder;

    /* Everyone in the pool, once, inside this viewer's organisations. */
    CREATE TABLE #cand (PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY, SourceCode nvarchar(30) NOT NULL);
    INSERT #cand
    SELECT cc.PersonnelNo, cc.SourceCode
    FROM sel.CycleCandidate cc
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    WHERE cc.CycleId = @CycleId;

    DECLARE @identified int = (SELECT COUNT(*) FROM #cand);

    SELECT p.Name AS ProcessName, s.Name AS StageName, fp.Caption, fp.GroupNo, fp.SortOrder,
           fp.SemanticRole, fp.IsOutcome,
           Cnt = CASE WHEN fp.IsOutcome = 1
                      THEN (SELECT COUNT(*) FROM #cand c
                            WHERE sel.fn_CandidateBox(s.StageKindCode,
                                    (SELECT TOP (1) dv.ValueCode FROM sel.CandidateDecision d
                                     JOIN cfg.DomainValue dv ON dv.DomainValueId = d.DecisionValueId
                                     WHERE d.CycleStageId = s.CycleStageId AND d.PersonnelNo = c.PersonnelNo
                                     ORDER BY d.DecisionId DESC), c.SourceCode)
                                  IN (SELECT PillCode FROM sel.FunnelPill
                                      WHERE StageKindCode = s.StageKindCode AND CountsToTotal = 1))
                      ELSE (SELECT COUNT(*) FROM #cand c
                            WHERE sel.fn_CandidateBox(s.StageKindCode,
                                    (SELECT TOP (1) dv.ValueCode FROM sel.CandidateDecision d
                                     JOIN cfg.DomainValue dv ON dv.DomainValueId = d.DecisionValueId
                                     WHERE d.CycleStageId = s.CycleStageId AND d.PersonnelNo = c.PersonnelNo
                                     ORDER BY d.DecisionId DESC), c.SourceCode) = fp.PillCode) END,
           /* The share is returned as a count and a total: the formatter decides how it
              reads, so a non-zero count never prints as 0%. */
           ShareOf = @identified
    FROM sel.CycleProcess p
    JOIN sel.CycleStage s ON s.CycleProcessId = p.CycleProcessId
    JOIN sel.FunnelPill fp ON fp.StageKindCode = s.StageKindCode
    WHERE p.CycleId = @CycleId
    ORDER BY p.SortOrder, s.SortOrder, fp.GroupNo, fp.SortOrder;

    SELECT Note = N'Counted against the ' + CONVERT(nvarchar(20), @identified)
                + N' people in this cycle''s pool that you are granted. '
                + N'The boxes are the same ones the stage screens show, read from the same rule.';

    DROP TABLE #cand;
END
GO
PRINT '  sel.usp_Report_Pipeline           applied';
GO

/* sel.usp_Report_DecisionsByLevel — who decided what, at which management level. */
CREATE OR ALTER PROCEDURE sel.usp_Report_DecisionsByLevel
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT ColumnKey, Caption, DataType, Align, SortOrder FROM (VALUES
        (N'LevelName',    N'Decided by',  N'text',   N'left',  10),
        (N'DecisionName', N'Decision',    N'text',   N'left',  20),
        (N'Cnt',          N'Decisions',   N'number', N'right', 30),
        (N'People',       N'People',      N'number', N'right', 40),
        (N'TestCount',    N'Of which test', N'number', N'right', 50)
    ) v (ColumnKey, Caption, DataType, Align, SortOrder) ORDER BY SortOrder;

    SELECT LevelName = ISNULL(pv.Name, N'(not recorded)'),
           DecisionName = dv.Name, DecisionRole = dv.SemanticRole,
           Cnt = COUNT(*),
           People = COUNT(DISTINCT d.PersonnelNo),
           TestCount = SUM(CAST(d.IsTest AS int)),
           ShareOf = (SELECT COUNT(*) FROM sel.CandidateDecision d2
                      JOIN sec.fn_UserOrgScope(@LoginName) s2 ON s2.OrgCode = d2.OrgCode
                      WHERE d2.CycleId = @CycleId)
    FROM sel.CandidateDecision d
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = d.OrgCode
    JOIN cfg.DomainValue dv ON dv.DomainValueId = d.DecisionValueId
    LEFT JOIN cfg.DomainValue pv ON pv.DomainValueId = d.PerformerLevelValueId
    WHERE d.CycleId = @CycleId
    GROUP BY pv.Name, pv.SortOrder, dv.Name, dv.SemanticRole, dv.SortOrder
    ORDER BY ISNULL(pv.SortOrder, 999), dv.SortOrder;

    SELECT Note = N'Every decision row, including the ones that cleared an earlier decision, '
                + N'because clearing is itself a decision. Decisions taken in test mode are counted separately.';
END
GO
PRINT '  sel.usp_Report_DecisionsByLevel   applied';
GO

/* sel.usp_Report_NominationsByOrg — where the nominations came from. */
CREATE OR ALTER PROCEDURE sel.usp_Report_NominationsByOrg
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT ColumnKey, Caption, DataType, Align, SortOrder FROM (VALUES
        (N'OrgName',    N'Organisation', N'text',   N'left',  10),
        (N'InPool',     N'In the pool',  N'number', N'right', 20),
        (N'Nominated',  N'Nominated',    N'number', N'right', 30),
        (N'Watched',    N'Watch list',   N'number', N'right', 40),
        (N'Dropped',    N'Dropped',      N'number', N'right', 50),
        (N'SharePct',   N'Nominated share', N'share', N'right', 60)
    ) v (ColumnKey, Caption, DataType, Align, SortOrder) ORDER BY SortOrder;

    SELECT o.Name AS OrgName, cc.OrgCode,
           InPool = COUNT(DISTINCT cc.PersonnelNo),
           Nominated = COUNT(DISTINCT CASE WHEN latest.ValueCode IN (N'NOMINATED', N'KEPT') THEN cc.PersonnelNo END),
           Watched   = COUNT(DISTINCT CASE WHEN latest.ValueCode = N'WATCH'   THEN cc.PersonnelNo END),
           Dropped   = COUNT(DISTINCT CASE WHEN latest.ValueCode = N'DROPPED' THEN cc.PersonnelNo END),
           /* The share's numerator and denominator, for the one formatter. */
           ShareCount = COUNT(DISTINCT CASE WHEN latest.ValueCode IN (N'NOMINATED', N'KEPT') THEN cc.PersonnelNo END),
           ShareOf = COUNT(DISTINCT cc.PersonnelNo)
    FROM sel.CycleCandidate cc
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    LEFT JOIN sel.OrgNode o ON o.OrgCode = cc.OrgCode
    OUTER APPLY (SELECT TOP (1) dv.ValueCode
                 FROM sel.CandidateDecision d
                 JOIN cfg.DomainValue dv ON dv.DomainValueId = d.DecisionValueId
                 WHERE d.CycleId = cc.CycleId AND d.PersonnelNo = cc.PersonnelNo
                   AND dv.ValueCode <> N'NONE'
                 ORDER BY d.DecisionId DESC) latest
    WHERE cc.CycleId = @CycleId
    GROUP BY o.Name, cc.OrgCode
    ORDER BY COUNT(DISTINCT cc.PersonnelNo) DESC, o.Name;

    SELECT Note = N'One row per organisation, counting each person once at their latest decision. '
                + N'Only organisations you have been granted appear, so two viewers will see different totals.';
END
GO
PRINT '  sel.usp_Report_NominationsByOrg   applied';
GO

/* sel.usp_Report_ReadinessDistribution — the same figures the design step shows, because
   it calls the same procedure.                                                         */
CREATE OR ALTER PROCEDURE sel.usp_Report_ReadinessDistribution
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT ColumnKey, Caption, DataType, Align, SortOrder FROM (VALUES
        (N'LevelCode',    N'Level',          N'code',   N'left',  10),
        (N'Name',         N'Name',           N'text',   N'left',  20),
        (N'ThresholdPct', N'Threshold',      N'number', N'right', 30),
        (N'ClearCut',     N'Clear this cut', N'number', N'right', 40),
        (N'AtThisLevel',  N'Held here',      N'number', N'right', 50)
    ) v (ColumnKey, Caption, DataType, Align, SortOrder) ORDER BY SortOrder;

    /* The report is a read model: it calls the engine, it does not re-implement it. */
    EXEC sel.usp_Readiness_Spread @LoginName = @LoginName, @CycleId = @CycleId, @AsOf = @AsOf;
END
GO
PRINT '  sel.usp_Report_ReadinessDistribution applied';
GO

/* sel.usp_Report_AssessmentCoverage — who has been assessed, and who has not. */
CREATE OR ALTER PROCEDURE sel.usp_Report_AssessmentCoverage
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    SELECT ColumnKey, Caption, DataType, Align, SortOrder FROM (VALUES
        (N'ItemCode',  N'Assessment', N'code',   N'left',  10),
        (N'ItemName',  N'Name',       N'text',   N'left',  20),
        (N'Taken',     N'Taken',      N'number', N'right', 30),
        (N'Passed',    N'Passed',     N'number', N'right', 40),
        (N'Expired',   N'Expired',    N'number', N'right', 50),
        (N'SharePct',  N'Of the pool',N'share',  N'right', 60)
    ) v (ColumnKey, Caption, DataType, Align, SortOrder) ORDER BY SortOrder;

    DECLARE @pool int = (SELECT COUNT(*) FROM sel.CycleCandidate cc
                         JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
                         WHERE cc.CycleId = @CycleId);

    SELECT r.ItemCode, ItemName = ISNULL(ci.Name, r.ItemCode),
           Taken = COUNT(DISTINCT r.PersonnelNo),
           Passed = COUNT(DISTINCT CASE WHEN r.Status = N'Completed' THEN r.PersonnelNo END),
           /* An expired record is not a completion, and the report has to say so. */
           Expired = COUNT(DISTINCT CASE WHEN r.ExpiresOn IS NOT NULL AND r.ExpiresOn < @AsOf
                                         THEN r.PersonnelNo END),
           ShareCount = COUNT(DISTINCT r.PersonnelNo),
           ShareOf = @pool
    FROM sel.EmployeeRecord r
    JOIN sel.CycleCandidate cc ON cc.CycleId = @CycleId AND cc.PersonnelNo = r.PersonnelNo
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    LEFT JOIN sel.CatalogItem ci ON ci.KindCode = r.KindCode AND ci.ItemCode = r.ItemCode
    WHERE r.KindCode IN (N'ASSESSMENT', N'FEEDBACK360')
    GROUP BY r.ItemCode, ci.Name
    ORDER BY COUNT(DISTINCT r.PersonnelNo) DESC, r.ItemCode;

    SELECT Note = N'Counted against the ' + CONVERT(nvarchar(20), @pool)
                + N' people in this cycle''s pool that you are granted. '
                + N'An expired result is still counted as taken, and called out separately.';
END
GO
PRINT '  sel.usp_Report_AssessmentCoverage applied';
GO

/* sel.usp_Report_PopulationProfile — grade band, age band and gender across the pool.
   Gender and dates of birth are sensitive: they are reported in aggregate here, and
   still refused as filters everywhere else.                                            */
CREATE OR ALTER PROCEDURE sel.usp_Report_PopulationProfile
    @LoginName nvarchar(128),
    @CycleId   int,
    @AsOf      date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @AsOf IS NULL SET @AsOf = CAST(SYSUTCDATETIME() AS date);

    SELECT ColumnKey, Caption, DataType, Align, SortOrder FROM (VALUES
        (N'Dimension', N'Dimension', N'text',   N'left',  10),
        (N'Band',      N'Band',      N'text',   N'left',  20),
        (N'Cnt',       N'People',    N'number', N'right', 30),
        (N'SharePct',  N'Share',     N'share',  N'right', 40)
    ) v (ColumnKey, Caption, DataType, Align, SortOrder) ORDER BY SortOrder;

    CREATE TABLE #pool
    (
        PersonnelNo nvarchar(30) NOT NULL PRIMARY KEY,
        GradeCode nvarchar(20) NULL, Gender nvarchar(20) NULL, BirthDate date NULL
    );
    INSERT #pool
    SELECT cc.PersonnelNo, e.GradeCode, e.Gender, e.BirthDate
    FROM sel.CycleCandidate cc
    JOIN sec.fn_UserOrgScope(@LoginName) sc ON sc.OrgCode = cc.OrgCode
    JOIN sel.Employee e ON e.PersonnelNo = cc.PersonnelNo
    WHERE cc.CycleId = @CycleId;

    DECLARE @total int = (SELECT COUNT(*) FROM #pool);

    SELECT Dimension = N'Grade', Band = ISNULL(GradeCode, N'(not recorded)'),
           Cnt = COUNT(*), ShareCount = COUNT(*), ShareOf = @total, SortOrder = 1
    FROM #pool GROUP BY GradeCode
    UNION ALL
    SELECT N'Age band',
           CASE WHEN BirthDate IS NULL THEN N'(not recorded)'
                WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 30 THEN N'Under 30'
                WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 40 THEN N'30–39'
                WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 50 THEN N'40–49'
                WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 60 THEN N'50–59'
                ELSE N'60 and over' END,
           COUNT(*), COUNT(*), @total, 2
    FROM #pool
    GROUP BY CASE WHEN BirthDate IS NULL THEN N'(not recorded)'
                  WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 30 THEN N'Under 30'
                  WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 40 THEN N'30–39'
                  WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 50 THEN N'40–49'
                  WHEN DATEDIFF(YEAR, BirthDate, @AsOf) < 60 THEN N'50–59'
                  ELSE N'60 and over' END
    UNION ALL
    SELECT N'Gender', ISNULL(Gender, N'(not recorded)'), COUNT(*), COUNT(*), @total, 3
    FROM #pool GROUP BY Gender
    ORDER BY SortOrder, Cnt DESC;

    SELECT Note = N'The ' + CONVERT(nvarchar(20), @total) + N' people in this cycle''s pool that you are granted. '
                + N'Gender and date of birth are reported here in aggregate only; they stay readable on a '
                + N'person''s record and refused as filters.';

    DROP TABLE #pool;
END
GO
PRINT '  sel.usp_Report_PopulationProfile  applied';
GO

/* sel.usp_Report_List — the report menu, as data. */
CREATE OR ALTER PROCEDURE sel.usp_Report_List
    @LoginName nvarchar(128)
AS
BEGIN
    SET NOCOUNT ON;
